-- RASCUNHO EDITORIAL: NÃO APLICADO. Fora de supabase/migrations para evitar execução automática.
-- Aplicação coordenada por Matheus após revisão e conciliação das metragens.
-- 141 projetos com custo confirmado; 21 pendentes permanecem somente no JSON para revisão.
-- Guardas capturadas em 01/10/2026. Alterar cadastro exige regenerar as guardas.
-- Atualiza somente nove campos editoriais; não altera publicação, visibilidade, imagens ou metragens.
BEGIN;
DO $portfolio_editorial$
DECLARE affected integer;
BEGIN
  UPDATE public.projects
  SET summary = 'No Latitude Campo Belo, os 27,75 m² encontram junto à janela um lugar para refeições e permanência. O banco e a mesa redonda aproveitam essa faixa do studio, enquanto a cama ocupa a área interna. Para locação, o projeto oferece usos complementares em uma composição de tons neutros e superfícies amadeiradas.',
      intro = 'O banco junto ao envidraçamento transforma a borda do ambiente em apoio de uso cotidiano. Seu desenho baixo permite que a janela continue presente na composição, e a mesa branca de base central se destaca entre as superfícies amadeiradas e as cadeiras escuras. A madeira aproxima esse setor da cabeceira e do piso, reforçando uma leitura contínua do interior.

Na cozinha, frentes mais neutras, tampo claro e nichos amadeirados mantêm a paleta discreta. Os detalhes escuros dão contorno a móveis e equipamentos, sem substituir a base clara do conjunto. A roupa de cama e a cortina completam essa atmosfera suave. O custo de reforma informado na planilha foi de R$ 2.882,88/m².',
      challenge = 'Reunir descanso, refeições e organização para hóspedes exige aproveitar áreas que poderiam receber apenas decoração. Neste studio, a faixa próxima à janela é um ponto importante de permanência. O desafio está em equipá-la sem bloquear sua presença visual e sem acrescentar cadeiras e móveis dispersos por toda a passagem.',
      solution = 'O banco concentra lugares de sentar junto à parede e incorpora armazenamento na base. A mesa redonda organiza o apoio para refeições, enquanto a cozinha mantém os equipamentos alinhados. No banheiro, gabinete amadeirado, bancada clara e espelho iluminado repetem a combinação de base neutra e destaque pontual. Essas decisões ligam o aproveitamento de espaço à linguagem do projeto.',
      result_text = 'Na locação, o setor junto à janela constitui um uso apresentado com clareza nas fotografias. A contribuição ao investimento está na experiência: o hóspede encontra um lugar para comer e permanecer além da cama. A organização sustenta a proposta visual e transforma a proximidade da janela em um apoio presente na rotina da estadia.',
      scope = ARRAY['Banco junto à janela com assento claro e gavetas inferiores', 'Mesa redonda de refeições próxima ao banco', 'Bancada de trabalho na lateral da abertura', 'Cabeceira amadeirada com prateleira horizontal', 'Cozinha de bancada clara alinhada ao armário alto', 'Suporte suspenso para televisão entre os setores', 'Gabinete de banheiro com nichos e espelho de contorno iluminado']::text[],
      seo_title = 'Studio de 27,75 m² no Campo Belo — Latitude | Bewild',
      seo_description = 'Veja o Latitude Campo Belo: reforma de studio de 27,75 m² com banco junto à janela, mesa redonda e marcenaria contínua. Fotos da obra pronta.',
      cover_alt = 'Foto do Latitude Campo Belo com cama em primeiro plano, mesa redonda diante da janela e banco com assento claro ao fundo.'
  WHERE slug = 'tb-latitude-campo-belo'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'afe2652a051664fa030bf7c503bb49a1';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'tb-latitude-campo-belo';
  END IF;

  UPDATE public.projects
  SET summary = 'O Terrae, em Pinheiros, organiza seus 24,67 m² com uma combinação de azul, madeira e pontos de amarelo. O studio destinado à locação tem cozinha, cama e apoio para refeições e trabalho em um ambiente contínuo. Uma divisória vazada marca a transição junto à cama e introduz ritmo sem esconder completamente o espaço seguinte.',
      intro = 'As frentes azuladas da cozinha contrastam com os módulos superiores de aparência amadeirada e com a bancada escura. O azul acrescenta uma nota mais fria, equilibrada pelo calor visual da madeira que reaparece na cabeceira e nos apoios. No banco junto à mesa, o amarelo estabelece um acento acolhedor e distingue o lugar de sentar dentro da composição.

O revestimento claro com textura de tijolos na área de descanso e os objetos de inspiração náutica acrescentam uma leitura descontraída. A divisória de elementos verticais repete a linguagem da madeira e preserva visadas entre os setores. Segundo a planilha, o custo de reforma deste projeto foi de R$ 2.935,02/m².',
      challenge = 'Em um studio de locação, a proximidade entre cama e cozinha pode deixar todos os usos expostos ao mesmo tempo. O desafio perceptível é criar referências de cada setor sem ocupar a área com uma parede fechada. A mesa também precisa servir à rotina de refeições e à eventual atividade profissional do hóspede.',
      solution = 'O painel vazado introduz uma separação visual parcial. Na parede oposta, banco, mesa e bancada se aproximam, reunindo apoios de permanência e organização. Prateleiras acima desse trecho aproveitam a parede para objetos. A repetição de madeira e detalhes escuros dá continuidade à cozinha, à área de trabalho e ao descanso, mesmo com a presença de cores diferentes.',
      result_text = 'A identidade cromática oferece uma forma de apresentar o imóvel em um anúncio de temporada, inclusive no Airbnb. A intenção de contribuir ao investimento está em combinar essa imagem reconhecível com apoios úteis ao hóspede. Refeições, trabalho e descanso permanecem legíveis dentro de uma área integrada, sem exigir mudanças constantes na disposição dos móveis.',
      scope = ARRAY['Divisória vazada de elementos verticais junto à cozinha', 'Marcenaria azul acinzentada com bancada escura', 'Banco estofado amarelo com gavetas na base', 'Mesa branca de base central junto ao banco', 'Bancada de trabalho e prateleiras na parede da televisão', 'Cabeceira com revestimento claro e remos decorativos', 'Banheiro com cuba de apoio e espelho iluminado de contorno irregular']::text[],
      seo_title = 'Studio em Pinheiros — Terrae | Bewild',
      seo_description = 'Descubra a reforma do Terrae em Pinheiros, com divisória vazada, banco amarelo e cozinha azul acinzentada. Veja o studio fotografado.',
      cover_alt = 'Foto da entrada do Terrae com piso amadeirado, cozinha azul à direita, divisória vertical e cama ao fundo do studio.'
  WHERE slug = 'vc-terrae'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '01731d96a44790b72f4909e7aa44fe2b';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'vc-terrae';
  END IF;

  UPDATE public.projects
  SET summary = 'O Nurban Vila Madalena assume uma paleta mais expressiva nos seus 26,36 m². A cozinha em tons profundos de azul esverdeado se combina com marcenaria amadeirada e superfícies claras; no banheiro, os tons terrosos acrescentam outro ponto de identidade. A proposta para locação reúne organização espacial e uma apresentação visual reconhecível.',
      intro = 'O azul esverdeado dá presença à cozinha, enquanto os nichos amadeirados aproximam esse bloco da cabeceira e dos armários ao redor da cama. A madeira funciona como ligação entre áreas de uso diferente e suaviza o contraste das frentes mais escuras. O fundo claro da bancada e a cortina interrompem a sequência de cores intensas, deixando espaços de respiro na composição.

No banheiro, o revestimento em tom de ocre e a frente terrosa do gabinete dialogam com a aparência pontilhada das superfícies inferiores. A relação entre tons frios no ambiente principal e quentes no banho cria variedade com uma mesma intenção de acolhimento. A reforma tem custo informado de R$ 4.114,06/m².',
      challenge = 'A cor pode dar identidade a um imóvel de locação, mas precisa conviver com cama, armários e cozinha próximos. O desafio aqui está em oferecer uma composição marcante sem perder a organização do espaço. Também é necessário acomodar o armazenamento nas paredes, mantendo o centro disponível para os deslocamentos do hóspede.',
      solution = 'O conjunto ao redor da cama reúne cabeceira, armários superiores e armazenamento lateral. A cozinha concentra os equipamentos em uma frente definida, com nichos que quebram o volume fechado. Mesa e apoio sob a televisão completam os usos do ambiente. Linhas de iluminação destacam a marcenaria e ajudam a reconhecer os planos que compõem o interior.',
      result_text = 'Para a apresentação em plataformas como o Airbnb, a combinação cromática oferece uma identidade percebida nas fotografias. A relação com o investimento passa também pela capacidade de acomodar roupas, refeições e descanso no imóvel. Acabamentos expressivos e lugares de guardar objetos formam um espaço que pode ser compreendido tanto nas fotos quanto durante o uso.',
      scope = ARRAY['Cozinha escura com nichos amadeirados e bancada preta', 'Revestimento branco com pequenos grafismos na área de preparo', 'Painéis e armários formando um recuo para a cama', 'Mesa redonda com cadeiras verdes junto à abertura', 'Spots em trilho e linha luminosa no teto do studio', 'Banheiro com revestimento amarelo e laranja e superfícies pontilhadas', 'Gabinete terracota e box com perfis escuros']::text[],
      seo_title = 'Studio de 26,36 m² na Vila Madalena — Nurban | Bewild',
      seo_description = 'Veja o Nurban Vila Madalena: studio de 26,36 m² com cozinha escura, marcenaria ao redor da cama e banheiro colorido. Fotos da reforma.',
      cover_alt = 'Foto do Nurban Vila Madalena com cozinha escura, cama à direita, mesa ao fundo e linha de iluminação no teto.'
  WHERE slug = 'fg'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '2181f8b20a2efc9e1e51643ed4a80be1';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'fg';
  END IF;

  UPDATE public.projects
  SET summary = 'No Modern Campo Belo, a proposta organiza cozinha, apoio para refeições ou trabalho e descanso em um ambiente contínuo. A marcenaria amadeirada conecta a cozinha à bancada com duas cadeiras, enquanto frentes claras equilibram os volumes. O sofá em tom terracota marca a transição para a cama sem criar uma divisória alta.',
      intro = 'A proposta para o Modern Campo Belo, no bairro Campo Belo, parte de uma sequência linear de usos. Desde a entrada, a cozinha ocupa uma lateral e conduz o olhar até a bancada junto à janela. No lado oposto, sofá e cama compartilham a faixa destinada ao descanso, como mostra a planta 3D. O piso de aparência amadeirada reforça essa continuidade. Na composição, os tons claros de paredes e armários suavizam a presença dos painéis amadeirados, enquanto cadeiras pretas e sofá terracota introduzem contrastes pontuais, sem fragmentar visualmente o ambiente. A área do projeto é de 26 m². O custo de reforma registrado para este projeto é de R$ 2.596,37/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial sugerido pelas visualizações é acomodar preparo de alimentos, refeições, trabalho e descanso mantendo uma passagem central contínua. A proximidade entre sofá e cama pede uma distinção de usos pelo próprio mobiliário, enquanto a cozinha precisa reunir equipamentos e armazenamento sem avançar sobre o percurso até a janela.',
      solution = 'O desenho concentra pia, cooktop e micro-ondas na composição da cozinha, com armários superiores e inferiores. Um painel amadeirado enquadra a geladeira e se relaciona com a bancada de duas posições sob a televisão. Prateleiras e luz sob os armários destacam os apoios sem acrescentar volumes no piso. No banheiro, a bancada escura contrasta com o gabinete claro, e o fechamento transparente do box mantém visível a profundidade da área de banho.',
      result_text = 'As visualizações apresentam uma organização em que cada apoio tem posição definida: preparo próximo à entrada, refeições ou trabalho na bancada e descanso junto à janela. A continuidade amadeirada aproxima esses usos, enquanto o sofá baixo distingue o estar da cama sem interromper a vista. A cozinha linear reúne preparo e armazenamento em uma leitura direta. Para a hospedagem, essa organização ajuda o visitante a reconhecer os usos e valoriza a apresentação do apartamento no anúncio.',
      scope = ARRAY['Cozinha linear com pia, cooktop e nicho inferior para micro-ondas', 'Armários claros combinados a painéis e nichos amadeirados', 'Enquadramento da geladeira pela marcenaria', 'Bancada longitudinal com duas cadeiras pretas e televisão acima', 'Prateleiras com iluminação linear sobre cozinha e bancada', 'Sofá terracota posicionado junto ao pé da cama', 'Banheiro com bancada escura, gabinete claro e espelho redondo', 'Box transparente com revestimentos de aparência mineral']::text[],
      seo_title = 'Modern Campo Belo: interiores e marcenaria',
      seo_description = 'Proposta no Modern Campo Belo com cozinha linear, bancada para refeições ou trabalho e sofá terracota junto à cama, conectados pela marcenaria.',
      cover_alt = 'Área de descanso com cama clara, poltrona em tom terracota, armários cinza e cortina cobrindo a janela lateral.'
  WHERE slug = 'ab-modern-campo-belo'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '2c10771bcd5b3c3647cb1c320a00dba1';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'ab-modern-campo-belo';
  END IF;

  UPDATE public.projects
  SET summary = 'No Atmosfera Studio 360, no Brooklin, a proposta organiza cozinha, apoio para refeições e descanso com uma estante vazada como divisória. A estrutura dourada enquadra a televisão e recebe um tampo amadeirado, enquanto a marcenaria clara acompanha a lateral do ambiente e mantém os volumes de armazenamento visualmente discretos.',
      intro = 'As visualizações apresentam um ambiente em que a cozinha linear fica diante da bancada com duas cadeiras, separada da cama por uma estrutura de perfis delgados. Essa peça estabelece um limite entre os usos sem formar uma parede contínua: a televisão ocupa o centro, e as prateleiras superiores deixam intervalos abertos. Branco, bege e superfícies amadeiradas claras aproximam os diferentes setores. Os contornos dourados marcam a estante, o armário e o espelho alongado, enquanto a geladeira e a tela introduzem contrastes mais escuros. Ao fundo, a cortina percorre a abertura junto à cama. A área do projeto é de 24 m². O custo de reforma registrado para este projeto é de R$ 2.884,74/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava conciliar a passagem entre cozinha e bancada com o espaço de descanso imediatamente ao lado. Uma separação inteiramente fechada interromperia a continuidade visual. Também era necessário acomodar equipamentos, utensílios e roupas sem transformar toda a lateral em uma sequência de volumes opacos e visualmente pesados.',
      solution = 'A estante proposta reúne suporte para a televisão voltada à cama, prateleiras e um tampo que serve às refeições ou ao apoio de trabalho. Seus vãos mantêm relações visuais entre os setores, embora a tela ofereça uma separação parcial. Na cozinha, portas claras envolvem a bancada pontilhada, e o armário de roupas aparece com fechamento translúcido e contornos dourados. O banheiro retoma essa paleta com bancada pontilhada, gabinete aberto e espelho assimétrico; a parede de sulcos verticais contrasta com a superfície amadeirada do box.',
      result_text = 'Nas visualizações, a organização depende de poucos elementos com funções definidas: a estante separa e sustenta, a bancada oferece apoio e a marcenaria concentra a guarda. A repetição dos tons claros aproxima cozinha e descanso, enquanto os perfis dourados tornam seus limites legíveis. A estante vazada permite assistir à televisão da cama e separar os usos sem fechar o ambiente. Essa flexibilidade favorece a experiência do hóspede em uma estadia compacta.',
      scope = ARRAY['Estante divisória vazada com televisão voltada para a cama', 'Bancada amadeirada com duas cadeiras junto à cozinha', 'Cozinha linear com armários claros e superfície pontilhada', 'Armário de roupas com fechamento translúcido e contornos dourados', 'Espelho vertical de extremidades arredondadas ao lado da cama', 'Cortina clara ao longo da abertura junto ao descanso', 'Banheiro com espelho assimétrico, gabinete aberto e parede de sulcos verticais']::text[],
      seo_title = 'Atmosfera Studio 360 no Brooklin | Interiores',
      seo_description = 'Proposta no Atmosfera Studio 360, no Brooklin, com estante divisória dourada, cozinha clara e bancada que conecta refeições e descanso.',
      cover_alt = 'Planta em perspectiva 3D de apartamento com cama, área de estar, cozinha linear e banheiro separados por divisórias.'
  WHERE slug = 'bf'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'da45ea0cb66c729cda102debab19c43b';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'bf';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o Vibe Vila Olímpia organiza cozinha, estar e apoio de trabalho em uma sequência marcada pela marcenaria amadeirada. O verde pontua paredes e gavetas, enquanto superfícies claras equilibram os elementos pretos. Um painel translúcido canelado delimita a cozinha sem interromper completamente a relação visual com o estar.',
      intro = 'Nas visualizações do Vibe Vila Olímpia, a distribuição acompanha um eixo que termina na abertura para a varanda. À esquerda, a bancada com duas cadeiras oferece apoio de trabalho, seguida pelo móvel baixo sob a televisão; à direita, a cozinha linear antecede o sofá cinza. A mesa redonda junto ao sofá acrescenta uma superfície para refeições, e o pufe complementa os assentos. O piso de aparência amadeirada aproxima visualmente essas áreas, enquanto cortinas claras filtram a abertura ao fundo e contrastam com o verde que a emoldura. A área do projeto é de 25 m². O custo de reforma registrado para este projeto é de R$ 3.146,70/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar superfícies de preparo, trabalho e refeição sem transformar o espaço central em uma sucessão de barreiras. Também há uma diferença de linguagem a equilibrar: perfis e bancada escuros têm presença forte, enquanto o estar pede uma composição menos carregada ao redor do sofá e da televisão.',
      solution = 'A proposta concentra armazenamento nas laterais e usa um painel canelado com contorno preto para marcar a transição entre cozinha e estar. Armários superiores claros reduzem o contraste com o teto, enquanto frentes amadeiradas dão continuidade aos móveis baixos. Na área de guarda de roupas, cabideiro, prateleiras abertas e gavetas verdes separam peças penduradas, dobradas e objetos menores. No banheiro, a bancada verde de aparência marmorizada destaca a área da cuba sobre o gabinete amadeirado, acompanhada por espelho de contorno orgânico.',
      result_text = 'As visualizações apresentam usos próximos, mas reconhecíveis pelo desenho dos móveis e pelas mudanças de superfície. A varanda permanece separada pelo fechamento transparente e recebe mesa alta com dois bancos, acrescentando outro apoio de refeição sem ocupar o eixo interno. A divisória translúcida diferencia o descanso da cozinha sem transformar o studio em pequenos cômodos fechados. Para a locação, a proposta equilibra acolhimento e uma identidade visual reconhecível nas fotos.',
      scope = ARRAY['Cozinha linear com bancada escura e armários claros e amadeirados', 'Painel translúcido canelado com contorno preto entre cozinha e estar', 'Bancada de trabalho com duas cadeiras estofadas', 'Móvel baixo e prateleira amadeirada junto à televisão', 'Mesa redonda junto ao sofá cinza e pufe', 'Guarda de roupas aberta com cabideiro, prateleiras e gavetas verdes', 'Banheiro com bancada verde marmorizada e espelho orgânico', 'Varanda com mesa alta e dois bancos']::text[],
      seo_title = 'Vibe Vila Olímpia: interiores em verde e amadeirado',
      seo_description = 'Conheça a proposta do Vibe Vila Olímpia, com cozinha linear, painel canelado, apoio de trabalho e marcenaria em verde e amadeirado.',
      cover_alt = 'Cama diante de televisão na parede, armário amadeirado com módulo aberto e nicho superior para objetos de uso cotidiano.'
  WHERE slug = 'sr-vibe-vila-olimpia'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '23bdb0f94680c74fdad2024785d1074e';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'sr-vibe-vila-olimpia';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o La Vida, em Santo Amaro, aproxima descanso, estar e cozinha sem apagar seus limites. A cabeceira amadeirada e a marcenaria branca organizam os apoios, enquanto uma trama de cordas marca a passagem junto à cama. Ao fundo, a cobertura transparente e os perfis escuros enquadram a vegetação.',
      intro = 'Nas visualizações do La Vida, a cama ocupa uma faixa lateral, deixando um percurso contínuo até o estar e a cozinha. A cabeceira amadeirada recebe uma linha de luz que destaca seu limite contra a parede cinza, enquanto nichos ao lado oferecem apoio sem acrescentar outro móvel ao piso. Branco, cinza e tons amarronzados se repetem no enxoval, no sofá e nos assentos, conectando os ambientes. Os perfis pretos das aberturas introduzem contraste e desenham uma moldura para o verde junto ao fechamento transparente. A área do projeto é de 38 m². O custo de reforma registrado para este projeto é de R$ 3.684,18/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar a proximidade entre cama, circulação, bancada e estar, mantendo legíveis as áreas de uso. Outro ponto é acomodar guarda e superfícies de apoio ao longo do percurso sem criar uma sequência visualmente pesada. A relação com a varanda pede uma separação que não bloqueie a vista.',
      solution = 'A trama vertical de cordas delimita parcialmente o descanso, mantendo aberturas entre seus elementos. Na parede oposta, a marcenaria alterna armário alto, nichos e bancada com cadeira, reunindo guarda de roupas e apoio para trabalho. Perto da entrada, um banco branco ocupa um recuo sob a prateleira iluminada. No estar, a mesa redonda com dois assentos atende pequenas refeições junto ao sofá; a cozinha acompanha a lateral, com frentes brancas que contrastam com os painéis amadeirados.',
      result_text = 'O resultado proposto é uma sequência de usos conectados pelo percurso lateral e pela repetição dos acabamentos. A divisória vazada sinaliza o limite da cama, enquanto armário, bancada e banco concentram funções nas bordas. A vegetação pontua o fechamento do estar. A cabeceira com nichos e luz linear acolhe a rotina do quarto, enquanto a divisão leve preserva a continuidade do espaço. O foco da moradia está nessa combinação de intimidade e conforto.',
      scope = ARRAY['Cabeceira amadeirada com iluminação linear e nichos laterais', 'Divisória vazada de cordas junto à cama', 'Armário alto e bancada com cadeira na circulação', 'Banco branco em recuo de marcenaria com prateleira iluminada', 'Estar com sofá, mesa redonda e dois assentos', 'Cozinha lateral com frentes brancas e painéis amadeirados', 'Varanda com cobertura transparente, perfis escuros e vegetação']::text[],
      seo_title = 'La Vida em Santo Amaro: marcenaria e integração visual',
      seo_description = 'Conheça a proposta do La Vida, em Santo Amaro: cabeceira iluminada, divisória de cordas e marcenaria que conecta descanso, estar e cozinha.',
      cover_alt = 'Armário amadeirado de piso a teto junto à entrada, espelho vertical e abertura para a área de estar e descanso.'
