  UPDATE public.projects
  SET summary = 'A proposta para o Latitude Campo Belo reúne cozinha linear, bancada com dois lugares e área de descanso em uma composição de bege, cinza e amadeirado claro. A marcenaria delimita os apoios sem fechar o ambiente, enquanto a abertura envidraçada mantém a varanda e sua mesa de refeições à vista.',
      intro = 'Nas visualizações do Latitude Campo Belo, em Campo Belo, a organização parte de duas frentes: cozinha e bancada de um lado, cama e estrutura aberta para roupas do outro. Entre elas, um assento estofado alongado oferece apoio para sentar junto à abertura da varanda. O amadeirado claro aproxima visualmente piso, painéis e prateleiras; as portas em bege deixam os volumes de armazenamento menos contrastantes. Já os perfis escuros do fechamento envidraçado marcam o limite com a varanda, sem interromper a vista entre a cama e a mesa redonda externa. A área do projeto é de 22 m². O custo de reforma registrado para este projeto é de R$ 2.824,43/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa acomodar preparo de alimentos, trabalho, refeições e descanso em posições próximas, sem transformar todos os apoios em uma única superfície indiferenciada. Outro ponto é conciliar armários fechados na cozinha com a guarda aberta de roupas junto à cama, mantendo uma linguagem visual comum.',
      solution = 'Na proposta, painéis verticais amadeirados enquadram a cozinha e distinguem sua bancada pontilhada do tampo adjacente com duas cadeiras. Armários superiores e inferiores concentram a guarda, enquanto prateleiras acomodam objetos à vista. O revestimento claro com linhas verticais acrescenta textura sem competir com essas divisões. Junto à cama, a estrutura aberta reúne cabideiro e prateleira. A faixa luminosa na cabeceira destaca o plano de fundo, e os trilhos de teto distribuem pontos de luz ao longo do ambiente.',
      result_text = 'As visualizações mostram usos próximos, mas reconhecíveis pelo desenho dos móveis: preparo na bancada com cuba e cooktop, trabalho no tampo com cadeiras e descanso junto à cabeceira. Na varanda, a mesa redonda oferece um segundo apoio para refeições, separado pelo fechamento envidraçado. Na hospedagem, o contraste entre o plano claro e a madeira torna a cozinha fácil de reconhecer. A bancada contínua concentra os equipamentos e deixa o restante do ambiente disponível para descansar.',
      scope = ARRAY['Cozinha linear com bancada pontilhada, cuba e cooktop', 'Armários bege com painéis laterais amadeirados', 'Bancada de trabalho com duas cadeiras sob a televisão', 'Estrutura aberta com cabideiro e prateleira junto à cama', 'Cabeceira amadeirada com faixa luminosa', 'Assento estofado alongado próximo à varanda', 'Mesa redonda e cadeiras na varanda com fechamento envidraçado']::text[],
      seo_title = 'Latitude Campo Belo | Cozinha, trabalho e descanso',
      seo_description = 'Proposta de interiores no Latitude Campo Belo com cozinha linear, bancada de trabalho, guarda aberta e varanda conectadas por tons claros.',
      cover_alt = 'Ambiente integrado com painel para televisão, bancada de trabalho amadeirada, cadeiras claras e nichos sobre o armário.'
  WHERE slug = 'dm'
