  UPDATE public.projects
  SET summary = 'No My One, em Pinheiros, a proposta organiza cozinha e apoio para refeições em lados opostos de uma passagem que conduz ao estar. A marcenaria escura contrasta com planos amadeirados e paredes claras. O desenho reserva espaços distintos para descanso e trabalho, sem interromper a continuidade visual do piso.',
      intro = 'As visualizações do My One mostram uma composição longitudinal: de um lado, a cozinha reúne bancada cinza pontilhada, armários escuros e uma prateleira aberta; do outro, um tampo amadeirado com três cadeiras oferece apoio para refeições. A geladeira aparece enquadrada pela marcenaria, enquanto prateleiras superiores aproveitam a parede sem ocupar o tampo. Ao fundo, o sofá cinza marca a transição para o estar. O piso amadeirado acompanha esse percurso e reaparece junto à cama e à bancada de trabalho, conectando visualmente setores que recebem tratamentos próprios. A área do projeto é de 30,5 m². O custo de reforma registrado para este projeto é de R$ 3.290,62/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta está em acomodar atividades ao longo de uma planta estreita, mantendo o percurso entre elas. A presença de armários altos e frentes escuras também pede equilíbrio: paredes claras, nichos abertos e superfícies amadeiradas evitam que toda a composição seja percebida como um volume fechado.',
      solution = 'O desenho concentra o preparo em uma bancada linear e posiciona as refeições na parede oposta. Uma divisória clara separa a cama do estar; no espaço de descanso, a TV suspensa dispensa um móvel de apoio à frente da cama, e o espelho vertical acompanha a parede lateral. Para trabalho, uma bancada ocupa a extremidade da faixa envidraçada, com cadeira e prateleiras acima, formando um posto separado da mesa de refeições.',
      result_text = 'Nas visualizações, a proposta estabelece uma sequência legível entre preparo, refeições e estar, com descanso resguardado pela divisória e trabalho em uma faixa lateral. O contraste entre preto, cinza e amadeirado aproxima os setores sem tornar todos os planos visualmente iguais. A mesa de madeira com três lugares amplia as possibilidades de uso durante a estadia. Refeições e pequenas atividades encontram apoio próprio, enquanto a cozinha escura dá personalidade ao anúncio.',
      scope = ARRAY['Cozinha linear com frentes escuras e bancada cinza pontilhada', 'Tampo amadeirado para refeições com três cadeiras', 'Enquadramento da geladeira por marcenaria amadeirada', 'Prateleiras abertas sobre o apoio de refeições', 'Separação entre cama e estar por divisória clara', 'TV suspensa e espelho vertical junto à cama', 'Bancada de trabalho com prateleiras na faixa envidraçada', 'Continuidade do piso amadeirado entre os setores']::text[],
      seo_title = 'My One em Pinheiros | Cozinha linear e espaços conectados',
      seo_description = 'Conheça a proposta do My One, em Pinheiros: cozinha linear, apoio para refeições, espaço de descanso separado e bancada de trabalho junto ao vidro.',
      cover_alt = 'Área de descanso com cama clara, cabeceira cinza, televisão suspensa e espelho vertical junto ao armário branco.'
  WHERE slug = 'sc-my-one'
