  UPDATE public.projects
  SET summary = 'A proposta para o YBY, no Ibirapuera, aproxima descanso, bancada de apoio e cozinha por meio da marcenaria amadeirada. O verde-oliva dá profundidade às paredes, enquanto tecidos claros equilibram os volumes dos armários. A bancada com duas cadeiras reúne possibilidades de trabalho e refeições diante da televisão, sem criar outra divisão.',
      intro = 'Nas visualizações do YBY, a cama e a bancada ocupam lados opostos de um mesmo ambiente, com a abertura envidraçada ao fundo. As cortinas claras filtram a luz representada e suavizam o contraste entre paredes verde-oliva, cadeiras escuras e superfícies amadeiradas. A televisão fica acima do tampo, acompanhada por prateleiras que acomodam livros e objetos sem ocupar a área de apoio. Ao lado, um armário alto de portas de correr concentra a guarda de roupas. A cozinha aparece próxima ao acesso, conectada ao restante pela repetição dos acabamentos e pela faixa de circulação entre os volumes. A área do projeto é de 22,5 m². O custo de reforma registrado para este projeto é de R$ 3.533,64/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar preparo de alimentos, guarda de roupas, apoio para atividades e descanso sem sobrepor seus espaços de uso. O principal cuidado era equilibrar a presença dos armários altos com a abertura ao fundo, mantendo um percurso contínuo e diferenciando a cozinha da área da cama sem fechar o ambiente.',
      solution = 'A proposta concentra pia, superfície de preparo, nicho do micro-ondas e armários em uma cozinha linear, com bancada escura e revestimento de aparência lisa em peças retangulares. No lado oposto, as portas de correr dispensam área frontal de abertura junto à circulação. A bancada com duas cadeiras atende ao trabalho ou a refeições, enquanto as prateleiras aproveitam a parede acima. Na cama, a cabeceira de desenho vertical marca o descanso; a iluminação sob os armários destaca o apoio da cozinha.',
      result_text = 'As visualizações apresentam uma composição em que a marcenaria organiza funções distintas sem multiplicar divisórias. O verde-oliva conecta os planos de parede, e os tecidos claros destacam a cama. A faixa livre entre cozinha, armário e bancada torna legível o percurso até a janela. A composição em verde oliva e madeira procura oferecer uma sensação acolhedora ao visitante. Os dois lugares de apoio permitem alternar refeição e trabalho, uma possibilidade relevante para estadias de diferentes durações.',
      scope = ARRAY['Paleta verde-oliva com superfícies amadeiradas e tecidos claros', 'Bancada com duas cadeiras para trabalho e refeições', 'Televisão e prateleiras acima da bancada', 'Armário alto com portas de correr para guarda de roupas', 'Cozinha linear com bancada escura e nicho para micro-ondas', 'Cabeceira com desenho vertical e apoio lateral junto à cama', 'Cortinas claras e iluminação linear no teto']::text[],
      seo_title = 'YBY no Ibirapuera | Verde-oliva e marcenaria',
      seo_description = 'Conheça a proposta de interiores do YBY, no Ibirapuera: verde-oliva, marcenaria amadeirada e bancada que aproxima trabalho, refeições e descanso.',
      cover_alt = 'Cozinha amadeirada com geladeira prateada, iluminação sob os armários e cama junto à parede em tonalidade verde.'
  WHERE slug = 'ag'
