  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'ag';
  END IF;

  UPDATE public.projects
  SET summary = 'No Balkon Campo Belo, a proposta combina superfícies cinza e amadeiradas para conectar cozinha, circulação e descanso. Armários junto às paredes concentram a guarda, enquanto a bancada com duas cadeiras oferece apoio para refeições e trabalho. Detalhes pretos pontuam a composição sem competir com os planos claros.',
      intro = 'As visualizações do Balkon Campo Belo mostram uma organização longitudinal: da cozinha, o percurso segue até a cama e a bancada próxima à janela. O piso de aparência amadeirada acompanha essa ligação, também presente nos tampos, no painel junto à entrada e na prateleira acima da televisão. Em contraste, paredes cinza e portas claras formam superfícies visualmente mais uniformes. O preto aparece em elementos delimitados, como a bancada da cozinha, os trilhos e a tela. Essa distribuição diferencia apoios e equipamentos sem fragmentar a leitura do ambiente. A área do projeto é de 27,32 m². O custo de reforma registrado para este projeto é de R$ 2.800,15/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial está em reunir preparo de alimentos, guarda de roupas, refeições, trabalho e descanso mantendo uma passagem contínua entre eles. Como a cama e a bancada compartilham o mesmo ambiente, o desenho precisa acomodar as cadeiras e os armários sem criar barreiras no percurso central.',
      solution = 'A proposta posiciona pia e cooktop na bancada escura de aparência pontilhada, com armários claros e amadeirados ao redor. Na parede oposta, um móvel baixo oferece apoio junto à circulação, complementado por módulos superiores. Perto da cama, a bancada alongada recebe duas cadeiras, e a televisão fica suspensa acima dela, liberando o tampo. O armário alto concentra a guarda de roupas ao lado desse apoio. Uma porta de correr branca permite fechar o vão sem ocupar a passagem com o giro da folha.',
      result_text = 'Nas visualizações, a continuidade dos acabamentos aproxima os diferentes usos, enquanto o mobiliário encostado às paredes mantém o eixo de circulação desimpedido. Cortinas claras enquadram a área de descanso, e a bancada compartilhada oferece alternativas de uso sem acrescentar uma mesa solta.',
      scope = ARRAY['Cozinha com pia e cooktop em bancada escura pontilhada', 'Móvel de apoio amadeirado junto à circulação', 'Armários superiores claros sobre o painel da entrada', 'Bancada com duas cadeiras para refeições e trabalho', 'Televisão suspensa e prateleira amadeirada acima do tampo', 'Armário alto de portas claras ao lado da bancada', 'Porta branca de correr com trilho preto aparente', 'Área de descanso junto à janela com cortinas claras']::text[],
      seo_title = 'Balkon Campo Belo | Cozinha, bancada e descanso integrados',
      seo_description = 'Conheça a proposta do Balkon Campo Belo, com cozinha compacta, marcenaria cinza e amadeirada e bancada para refeições e trabalho junto à cama.',
      cover_alt = 'Armário branco com compartimentos abertos ao lado de mesa de refeições, televisão e painel em tonalidade cinza.'
  WHERE slug = 'fd-balkon-campo-belo'
