  UPDATE public.projects
  SET summary = 'No Península Vila Madalena, a proposta aproxima descanso, preparo de refeições e trabalho sem dividir o ambiente principal. A cabeceira amadeirada e a bancada com duas cadeiras ocupam paredes opostas, deixando uma faixa de circulação entre elas. Tons claros equilibram os detalhes pretos da cozinha, dos assentos e da iluminação.',
      intro = 'As visualizações do estúdio na Vila Madalena mostram a cama junto à abertura com cortinas, enquanto cozinha e bancada de apoio se alinham na parede oposta. Essa distribuição concentra o mobiliário nas laterais e mantém livre o percurso desde a entrada. O acabamento amadeirado aparece na cabeceira, nas prateleiras e nos volumes altos da marcenaria, aproximando visualmente os diferentes usos. Já as frentes claras dos armários suavizam a presença da cozinha. Ao fundo da cama, um espelho vertical reflete as cortinas e prolonga a leitura do ambiente, sem acrescentar outra divisão. A área do projeto é de 23 m². O custo de reforma registrado para este projeto é de R$ 2.739,13/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar a proximidade entre cama, cozinha e apoio de trabalho sem sobrepor seus espaços de uso. A bancada precisa receber duas cadeiras, enquanto a cozinha reúne pia, superfície de cocção e refrigerador. O banheiro, por sua vez, permanece separado por paredes e porta.',
      solution = 'A proposta reserva uma bancada clara diante da cama para trabalho ou refeições, com a televisão acima e volumes amadeirados nas laterais. Na cozinha, prateleiras abertas liberam a leitura da parede revestida por peças brancas retangulares em relevo. A superfície preta pontilhada contrasta com os armários claros e delimita o preparo. A cabeceira contínua incorpora apoios laterais, enquanto o banheiro combina superfícies claras, bancada pontilhada e fechamento transparente na área de banho.',
      result_text = 'O conjunto proposto diferencia os usos pela posição do mobiliário e pelo contraste entre superfícies, não por novas barreiras no ambiente principal. A repetição do amadeirado conecta cozinha e descanso, enquanto a bancada compartilhada permite alternar refeições e trabalho no mesmo apoio. Para a locação, a bancada de estudo acrescenta uma possibilidade de uso além das refeições e do descanso. Esse apoio procura atender hóspedes com rotinas diferentes, sem exigir outro ambiente fechado.',
      scope = ARRAY['Cabeceira amadeirada contínua com apoios laterais', 'Bancada clara com duas cadeiras diante da cama', 'Televisão e prateleira acima do apoio de trabalho e refeições', 'Cozinha linear com bancada preta pontilhada e armários claros', 'Prateleiras amadeiradas sobre revestimento branco retangular em relevo', 'Espelho vertical próximo ao acesso do banheiro', 'Banheiro separado com bancada clara pontilhada e fechamento transparente do banho']::text[],
      seo_title = 'Península Vila Madalena | Verde, preto e amadeirado',
      seo_description = 'Proposta no Península Vila Madalena reúne cama, cozinha linear e bancada para refeições e trabalho, com marcenaria amadeirada e tons claros.',
      cover_alt = 'Cozinha de armários claros e bancada preta, nichos amadeirados e painel para televisão junto à bancada de refeições.'
  WHERE slug = 'ab-peninsula-vila-madalena'
