  UPDATE public.projects
  SET summary = 'No YBY Urban Home, a proposta aproxima cozinha, trabalho e descanso, diferenciando cada função pelo desenho do mobiliário. Armários claros e superfícies amadeiradas dão continuidade ao ambiente, enquanto a bancada escura da cozinha, a mesa redonda e os detalhes pretos estabelecem contrastes pontuais sem dominar a composição.',
      intro = 'As visualizações apresentam uma cozinha linear junto à passagem de entrada e, na sequência, uma bancada de trabalho sob a televisão. Ao lado dela, o armário alto concentra a guarda de roupas, próximo à cama. Essa disposição reúne os volumes maiores em uma mesma lateral, enquanto a mesa redonda com duas cadeiras cria um apoio separado para refeições. O piso de aparência amadeirada clara conecta esses usos. Nas paredes, a combinação de branco e cinza aparece tanto no ambiente principal quanto no corredor, onde um espelho vertical de contorno arredondado acompanha a circulação. A área do projeto é de 27,83 m². O custo de reforma registrado para este projeto é de R$ 2.407,47/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é aproximar preparo de alimentos, trabalho, refeições e descanso sem confundir seus apoios. A presença da geladeira e do armário alto também exige equilíbrio visual: seus volumes precisam se relacionar com a bancada mais leve de trabalho e com a cama, situada em frente.',
      solution = 'A proposta diferencia os apoios: a bancada escura reúne cuba e cooktop, o tampo amadeirado recebe a cadeira de trabalho e a mesa circular atende às refeições. Na cozinha, portas lisas claras contrastam com o revestimento branco retangular em relevo. A prateleira acima da televisão, iluminada por baixo, marca o plano de trabalho. Já o banheiro mantém superfícies claras e recortes escuros no chuveiro, no suporte de toalha e na borda do espelho, repetindo o contraste presente no ambiente principal.',
      result_text = 'O estudo em 3D apresenta funções próximas, mas reconhecíveis por seus móveis e superfícies de apoio. A repetição de tons claros e amadeirados conecta cozinha e descanso, enquanto elementos pretos pontuam a composição e tornam mais nítidos seus diferentes planos. O nicho do micro-ondas integrado à marcenaria evita que o equipamento dispute a bancada com o preparo. Para a locação, o desenho apresenta uma cozinha organizada e uma imagem de conjunto coerente.',
      scope = ARRAY['Cozinha linear com bancada escura, cuba e cooktop', 'Armários claros e nicho amadeirado para micro-ondas', 'Bancada de trabalho sob televisão e prateleira iluminada', 'Armário alto para roupas junto à área de descanso', 'Mesa redonda preta com duas cadeiras para refeições', 'Parede bicolor e espelho vertical arredondado no corredor', 'Banheiro claro com box transparente e detalhes pretos']::text[],
