  UPDATE public.projects
  SET summary = 'A proposta para o Next One Vila Nova, no Jardim Paulista, aproxima cozinha, refeições e estar em um eixo contínuo. A marcenaria amadeirada marca a transição entre bancada e sofá, enquanto o banco junto à parede acomoda a mesa redonda. O dormitório separado mantém o descanso fora dessa sequência de usos.',
      intro = 'Nas visualizações, o percurso entre a cozinha e a janela revela como o desenho distribui os usos pelas laterais. De um lado, a bancada reúne cuba e cooktop sob armários amadeirados; do outro, volumes claros envolvem a geladeira e dão lugar ao banco estofado. Ao fundo, a mesa redonda compartilha espaço com o estar, sem uma divisória entre eles. Bege, cinza e superfícies amadeiradas formam uma base próxima em tonalidade, pontuada pela cadeira, pelas luminárias e pelo ventilador pretos. A faixa vertical de vegetação acrescenta contraste de cor e textura ao lado do sofá. A área do projeto é de 27 m². O custo de reforma registrado para este projeto é de R$ 3.111,11/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial está na proximidade entre preparo, refeições e estar: bancada, assentos e mesa precisam conviver sem bloquear o percurso longitudinal. Ao mesmo tempo, a quantidade de armários poderia tornar essa passagem visualmente pesada. O desenho contrapõe frentes claras à marcenaria amadeirada e concentra os volumes altos junto às paredes.',
      solution = 'O banco encostado à parede dispensa cadeiras desse lado da mesa, deixando o centro menos ocupado. Na cozinha, o nicho para eletrodoméstico e a faixa de luz sob a marcenaria organizam o plano acima da bancada clara pontilhada. Uma lateral amadeirada alta delimita a cozinha junto ao sofá, sem fechar o ambiente. No dormitório, a cabeceira horizontal acompanha a cama e os apoios laterais; a planta mostra a guarda de roupas próxima ao acesso, separada da área de refeições.',
      result_text = 'As visualizações apresentam uma composição em que a marcenaria tanto armazena quanto demarca usos. A continuidade amadeirada aproxima os ambientes, enquanto a separação do dormitório, o banco lateral e a cozinha linear dão posições distintas ao descanso, às refeições e ao preparo. O nicho iluminado integra os equipamentos à composição da cozinha. A intenção para a locação é oferecer ao hóspede uma leitura organizada do preparo e uma apresentação visual que ajude a diferenciar o imóvel.',
      scope = ARRAY['Cozinha linear com frentes bege e armários superiores amadeirados', 'Nicho para eletrodoméstico e iluminação linear sobre a bancada', 'Banco estofado com base amadeirada de linhas verticais', 'Mesa redonda com cadeira preta junto à janela', 'Sofá cinza-claro ao lado de faixa vertical de vegetação', 'Dormitório com cabeceira amadeirada e apoios laterais pretos', 'Guarda de roupas com compartimento aberto representada na planta 3D']::text[],
      seo_title = 'Next One Vila Nova | Interiores no Jardim Paulista',
      seo_description = 'Conheça a proposta do Next One Vila Nova, no Jardim Paulista: cozinha linear, banco para refeições e marcenaria que delimita os ambientes.',
      cover_alt = 'Cozinha e apoio de refeições com armários claros, nichos amadeirados, mesa redonda, televisão e cadeiras de cor escura.'
