  UPDATE public.projects
  SET summary = 'A proposta para o Metrocasa Berrini reúne cama, sofá, apoio para refeições e bancada de trabalho em um ambiente contínuo. O desenho combina superfícies amadeiradas, frentes claras e detalhes pretos. A marcenaria concentra a guarda de roupas e os apoios, enquanto o painel atrás da cama e do sofá aproxima visualmente as duas áreas.',
      intro = 'Nas visualizações do Metrocasa Berrini, a cozinha ocupa uma lateral próxima à entrada, e a cama se posiciona junto à janela ao fundo. Entre esses pontos, sofá e mesa redonda acrescentam lugares para sentar e fazer refeições sem estabelecer uma divisão fechada. Em frente à cama, a bancada com cadeira e televisão fica ao lado do armário espelhado. O amadeirado aparece no piso, no painel e na marcenaria, contrapondo-se às paredes claras e aos tecidos em bege e branco. Contornos pretos em luminárias, quadros e bases de mobiliário pontuam essa composição suave. A área do projeto é de 26 m². O custo de reforma registrado para este projeto é de R$ 2.479,08/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar funções distintas ao longo de um espaço estreito, mantendo legível a passagem entre a entrada e a janela. A proximidade entre cama, sofá e cozinha pede unidade visual, enquanto trabalho, refeições e guarda de roupas precisam de apoios próprios, sem depender da mesma superfície.',
      solution = 'A bancada de trabalho ocupa um vão da marcenaria, com prateleira superior e televisão na parede, deixando o tampo disponível para o computador. Ao lado, portas espelhadas refletem a janela e atenuam visualmente o volume do armário. A mesa redonda oferece um apoio independente junto ao sofá. Na cozinha, frentes bege e bancada clara pontilhada acompanham a paleta do ambiente. No banheiro, o desenho contrapõe paredes lisas claras ao fundo canelado do box, com prateleira horizontal e fechamento transparente.',
      result_text = 'As visualizações apresentam uma composição em que os usos se distinguem pelo mobiliário, não por novas divisórias. O painel contínuo conecta cama e sofá, enquanto bancada, mesa redonda e armário distribuem trabalho, refeições e guarda em pontos reconhecíveis do ambiente. A bancada junto à televisão e a prateleira superior organizam apoios sem distribuir pequenos móveis pelo piso. Para o hóspede, o apartamento oferece possibilidades de uso reunidas em um desenho contínuo.',
      scope = ARRAY['Bancada amadeirada com cadeira, televisão e prateleira superior', 'Armário com portas espelhadas ao lado da bancada', 'Painel amadeirado contínuo atrás da cama e do sofá', 'Mesa redonda de base central junto ao sofá', 'Cozinha linear com frentes bege e bancada clara pontilhada', 'Persianas claras na janela próxima à cama', 'Box transparente com fundo canelado e prateleira horizontal']::text[],
      seo_title = 'Metrocasa Berrini: interiores e marcenaria',
