  UPDATE public.projects
  SET summary = 'A proposta em Cidade Jardim aproxima cozinha, jantar e estar, enquanto mantém o quarto separado. O piso amadeirado estabelece continuidade entre os ambientes, e a marcenaria branca reduz o contraste dos volumes de guarda. Atrás do sofá, uma bancada oferece apoio para trabalho sem ocupar a mesa de refeições.',
      intro = 'A planta 3D apresenta uma organização em que cozinha e mesa oval ficam de um lado, e o sofá voltado para a televisão ocupa a faixa central. Uma bancada amadeirada acompanha as costas do estofado, criando uma superfície independente para notebook e pequenos objetos. Junto à abertura lateral, uma poltrona e a vegetação compõem outro ponto de pausa. O quarto aparece delimitado por paredes e porta, com cama, apoios laterais e armário. A paleta branca e bege aproxima esses setores, enquanto o piso amadeirado e as almofadas castanhas introduzem variações de cor sem fragmentar o desenho. A área do projeto é de 37 m². O custo de reforma registrado para este projeto é de R$ 3.000,13/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial sugerido pela planta é aproximar preparo de alimentos, refeições e estar sem sobrepor seus apoios. Também importa manter o descanso em um ambiente separado. Como o sofá ocupa uma posição central, o desenho de suas duas faces participa tanto da organização do estar quanto da área de trabalho.',
      solution = 'A proposta posiciona a mesa oval perto da cozinha em L e utiliza a bancada atrás do sofá para distinguir trabalho e estar sem uma divisória alta. No painel da televisão, a luz de contorno destaca a superfície branca, e os frisos dourados acrescentam linhas verticais ao conjunto. O móvel suspenso deixa uma faixa de piso aparente. No banheiro, superfícies claras de aparência marmorizada contrastam suavemente com a faixa amadeirada do box, delimitado por vidro.',
      result_text = 'As visualizações mostram uma composição em que a integração não elimina os limites entre atividades: mesa, bancada e sofá definem apoios próprios, enquanto o quarto permanece separado. A continuidade dos tons claros conecta os ambientes sem depender da ausência de divisórias. A mesa oval com quatro lugares transforma as refeições em um momento de convivência. Para morar, a cozinha em L e a combinação de branco e madeira articulam praticidade diária e acolhimento.',
      scope = ARRAY['Cozinha em L com frentes brancas e trechos amadeirados', 'Mesa oval com quatro cadeiras próxima à cozinha', 'Bancada de apoio ao trabalho atrás do sofá', 'Painel de televisão com iluminação de contorno e frisos dourados', 'Móvel suspenso sob a televisão', 'Quarto separado com armário e apoios ao lado da cama', 'Banheiro com box de vidro e contraste entre superfícies claras e amadeiradas']::text[],
      seo_title = 'Interiores em Cidade Jardim | Tons claros e usos conectados',
