  UPDATE public.projects
  SET summary = 'No Cyrela by You Perdizes, a marcenaria dá unidade aos 24 m² do studio. A madeira percorre cozinha, armazenamento e cabeceira, acompanhada por cinza, vidro e detalhes pretos. Para a locação, essa organização permite reunir os apoios da estadia em uma composição organizada, que também tenha presença nas fotografias do imóvel.',
      intro = 'As frentes amadeiradas criam a base acolhedora do interior. Nas portas superiores da cozinha, o vidro com moldura preta interrompe a sequência de superfícies fechadas e diferencia esse trecho. O preto reaparece na bancada, nos puxadores e no trilho de spots, formando uma linha de detalhes que organiza o contraste com o revestimento branco.

Sob a televisão, as gavetas cinza introduzem uma pausa na textura da madeira. A cor mais contida aproxima esse móvel da roupa de cama e evita que todos os elementos disputem atenção. Já a iluminação junto à cabeceira e à prateleira destaca planos da marcenaria. O custo informado da reforma foi de R$ 2.929,22/m².',
      challenge = 'Para receber hóspedes em uma área compacta, guardar objetos e manter apoios disponíveis são necessidades simultâneas. O desafio perceptível é concentrar cozinha, armário e televisão em uma mesma frente sem transformar o conjunto em um volume indistinto, preservando uma leitura clara de onde preparar refeições, guardar roupas e descansar.',
      solution = 'A alternância de madeira, vidro, nichos e gavetas identifica as funções dentro da frente contínua. A mesa para duas pessoas ocupa outra parede e pode receber refeições ou um computador. No banheiro, as prateleiras sobre o vaso acrescentam apoio sem exigir mais um móvel no piso. A repetição da madeira entre os ambientes mantém a linguagem do projeto consistente.',
      result_text = 'A relação com o investimento aparece no uso concentrado da marcenaria: armazenamento e apoios cotidianos fazem parte da composição. Na locação por temporada, a identidade amadeirada apresenta um interior acolhedor, enquanto mesa e armários sustentam a estadia. O acolhimento se traduz na paleta consistente, e a praticidade aparece nos lugares de guardar, apoiar e circular.',
      scope = ARRAY['Marcenaria amadeirada contínua entre cozinha e armário alto', 'Portas superiores envidraçadas com moldura preta na cozinha', 'Bancada preta com revestimento branco e puxadores redondos', 'Móvel de televisão com gavetas cinza e prateleira iluminada', 'Cabeceira com linha de luz indireta', 'Mesa de madeira com duas cadeiras pretas', 'Prateleiras abertas sobre o vaso e gabinete amadeirado no banheiro']::text[],
