  UPDATE public.projects
  SET summary = 'No Sergipe Boutique Apartments by You, na Consolação, a proposta aproxima cozinha, bancada com duas cadeiras e área de descanso em uma composição linear. O azul profundo pontua a marcenaria e a cabeceira, enquanto superfícies amadeiradas dão continuidade ao percurso. Relevos brancos e iluminação sob o nicho diferenciam a cozinha sem romper a unidade visual.',
      intro = 'As visualizações apresentam uma cozinha junto à entrada, com bancada escura, cuba, cooktop e geladeira alinhados em uma das laterais. Esse arranjo mantém uma passagem direta até a cama e a abertura envidraçada ao fundo. Próxima à janela, a bancada amadeirada com duas cadeiras oferece apoio para refeições ou trabalho, sem acrescentar uma mesa no centro do ambiente. Na área de descanso, a cabeceira azul se estende além da cama e contrasta com a parede branca de pequenos relevos horizontais. As cortinas cinzas acompanham a altura da abertura e permitem filtrar a luz junto aos dois usos. A área do projeto é de 25 m². O custo de reforma registrado para este projeto é de R$ 3.487,14/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar preparo de alimentos, armazenamento, apoio de mesa e descanso ao longo de uma circulação estreita. A presença da geladeira e dos armários altos pede uma composição que organize os volumes sem bloquear a perspectiva até a janela, enquanto a cama exige apoios laterais que não ocupem a passagem.',
      solution = 'A proposta concentra os equipamentos da cozinha sob armários e nichos, alternando frentes azuis, interiores claros e acabamento amadeirado. A bancada preta pontilhada destaca o plano de preparo diante do revestimento branco em relevo, iluminado por uma faixa sob o nicho. No trecho seguinte, o painel azul de cantos arredondados delimita visualmente a televisão acima da bancada. Junto à cama, luminárias de parede e um pequeno apoio circular reduzem a quantidade de móveis no piso.',
      result_text = 'Nas visualizações, a repetição do azul conecta cozinha, televisão e cabeceira, enquanto o amadeirado aproxima teto, piso e bancada. Os usos permanecem reconhecíveis pelo desenho dos móveis, e a passagem entre a entrada e a janela fica visualmente desimpedida. A marcenaria azul ganha leveza com os nichos de madeira iluminados. Para a hospedagem, essa escolha dá personalidade à cozinha e procura tornar o preparo parte de um ambiente convidativo.',
      scope = ARRAY['Cozinha linear com cuba, cooktop e bancada preta pontilhada', 'Marcenaria azul e amadeirada com nichos claros e espaço para micro-ondas', 'Iluminação linear no teto e sob o nicho da cozinha', 'Bancada com duas cadeiras junto à abertura envidraçada', 'Painel azul de cantos arredondados para televisão', 'Cabeceira azul com luminárias de parede e apoio lateral circular', 'Cortinas cinzas e composição de relevos brancos junto à cama']::text[],
      seo_title = 'Sergipe Boutique Apartments by You | Consolação',
