  UPDATE public.projects
  SET summary = 'A proposta para o Metrocasa Berrini, no Brooklin Paulista, aproxima cozinha, refeições e descanso em um ambiente de tons claros. A marcenaria bege concentra os apoios da cozinha, enquanto o painel amadeirado conecta visualmente cama e sofá. Elementos pretos pontuam o desenho sem competir com as superfícies maiores.',
      intro = 'Nas visualizações do Metrocasa Berrini, a cozinha ocupa uma lateral junto à entrada, com armários inferiores e aéreos, nicho aberto e refrigerador ao final da bancada. Do lado oposto, a mesa redonda se associa ao sofá e a uma cadeira, formando um apoio para refeições separado da área de preparo. A cama fica mais próxima da janela e compartilha com o sofá um painel amadeirado contínuo. Essa faixa horizontal reúne os dois usos pela aparência, enquanto os próprios móveis definem onde sentar, comer e descansar, sem uma parede entre eles. A área do projeto é de 26 m². O custo de reforma registrado para este projeto é de R$ 2.479,08/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar os volumes da cozinha e os móveis de descanso sem interromper a passagem entre entrada e janela. Também é necessário distinguir cama, sofá e refeições dentro do mesmo campo visual, evitando que armários, estofados e apoios disputem atenção no espaço compacto.',
      solution = 'A proposta concentra o armazenamento da cozinha em uma composição vertical de portas bege e nicho aberto. O piso e o painel de aparência amadeirada contrastam com paredes e estofados claros, dando continuidade ao ambiente. Puxadores, bases de mesas, estruturas das cadeiras e trilho de iluminação introduzem linhas pretas mais finas. No banheiro, a parede canelada diferencia a área do banho das superfícies lisas; o fechamento transparente mantém essa textura visível, e uma prateleira oferece apoio aos frascos.',
      result_text = 'As visualizações apresentam um estúdio organizado por duas laterais de mobiliário e uma passagem central. A repetição do bege e do amadeirado aproxima cozinha e descanso, enquanto a mesa redonda cria um ponto específico de refeição junto ao sofá. Na preparação para locação por temporada, o apoio junto à cama reúne refeições e pequenas tarefas. A proposta procura facilitar a experiência do hóspede e apresentar a unidade com usos compreensíveis nas fotografias.',
      scope = ARRAY['Cozinha linear com armários bege, nicho aberto e bancada clara', 'Painel amadeirado contínuo atrás da cama e do sofá', 'Mesa redonda com base central junto ao sofá e à cadeira', 'Composição de estofados claros com almofadas contrastantes', 'Trilho preto de iluminação no eixo longitudinal do ambiente', 'Área de banho com parede canelada, fechamento transparente e prateleira', 'Piso de aparência amadeirada no ambiente integrado']::text[],
      seo_title = 'Metrocasa Berrini: estúdio no Brooklin Paulista',
      seo_description = 'Conheça a proposta do Metrocasa Berrini, no Brooklin Paulista, com cozinha bege, painel amadeirado e mesa redonda junto ao sofá.',
      cover_alt = 'Cozinha de armários claros com nichos amadeirados, geladeira prateada e bancada de refeições ao lado da cama.'
  WHERE slug = 'tr-metrocasa-berrini'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '5dd6bcb66d70c3c842cabe03229985df';
