    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'tr-metrocasa-berrini';
  END IF;

  UPDATE public.projects
  SET summary = 'No Metrocasa Berrini, no Brooklin Paulista, a proposta concentra cozinha, armários altos e bancada de trabalho em uma mesma parede. Em frente, sofá, mesa redonda e cama compartilham o espaço sem divisórias. O contraste entre superfícies cinza-claras e painéis amadeirados diferencia os módulos e dá continuidade ao desenho.',
      intro = 'As visualizações apresentam um estúdio organizado por duas frentes: de um lado, a marcenaria reúne preparo de refeições, armazenamento e trabalho; do outro, os estofados e a cama formam a sequência de estar e descanso. A mesa redonda ocupa a transição entre esses usos, oferecendo apoio para refeições junto ao sofá. Ao fundo, a abertura envidraçada permanece no eixo da circulação. O piso de aparência amadeirada aproxima visualmente as duas frentes, enquanto paredes brancas e armários cinza-claros deixam os painéis verticais em evidência sem introduzir contrastes fortes. A área do projeto é de 26,74 m². O custo de reforma registrado para este projeto é de R$ 2.430,82/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é aproximar cozinha, trabalho, refeições e descanso sem transformar os apoios em obstáculos na passagem longitudinal. Como a cama e o sofá dividem o mesmo ambiente, a organização precisa vir da posição dos móveis e da composição da marcenaria, e não de uma separação física entre setores.',
      solution = 'O desenho intercala volumes altos amadeirados com nichos de uso: a cozinha recebe bancada clara, gavetas e nicho para micro-ondas; a área de trabalho tem tampo sob a televisão e prateleira superior. Essa alternância distingue as atividades dentro de uma composição contínua. A mesa com base central aproxima o apoio de refeições do sofá. No banheiro, a proposta combina cuba de apoio, gabinete aberto com prateleiras, espelho redondo e box transparente.',
      result_text = 'A proposta apresenta uma divisão de funções legível pela disposição dos móveis. A bancada permite trabalhar sem ocupar a mesa de refeições, enquanto sofá e cama mantêm apoios distintos para estar e descanso. Tons claros e amadeirados conectam visualmente os setores.',
      scope = ARRAY['Composição linear de cozinha, armários altos e bancada de trabalho', 'Armários cinza-claros e nicho aberto para micro-ondas', 'Bancada de trabalho sob a televisão, com prateleira superior', 'Mesa redonda com base central junto ao sofá cinza', 'Cama voltada para a parede da televisão', 'Iluminação linear no teto acompanhando o eixo do ambiente', 'Banheiro com gabinete aberto, cuba de apoio e espelho redondo']::text[],
      seo_title = 'Metrocasa Berrini: interiores no Brooklin Paulista',
      seo_description = 'Proposta para estúdio no Metrocasa Berrini, Brooklin Paulista, com cozinha linear, bancada de trabalho e marcenaria em tons claros e amadeirados.',
      cover_alt = 'Cama com roupa clara junto a mesa redonda branca, cadeiras claras, janela ampla e cozinha de detalhes amadeirados.'
  WHERE slug = 'pg-metrocasa-berrini'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '5841ac5b6b020868e47d5373951fd3d6';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'pg-metrocasa-berrini';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o NOW Butantã combina planos azul-acinzentados, marcenaria preta e superfícies amadeiradas. O desenho aproxima estar e mesa de refeições, enquanto mantém o dormitório separado. Na composição, tecidos claros e paredes neutras equilibram os elementos escuros, que destacam a cabeceira, o painel de televisão e os volumes de guarda.',
      intro = 'As visualizações do NOW Butantã mostram um estar organizado entre o sofá cinza e o painel de televisão, com passagem central em direção à mesa redonda junto à abertura envidraçada. O piso de aparência amadeirada dá continuidade visual a esse percurso e reaparece no dormitório. Atrás do sofá, o azul-acinzentado encontra uma faixa amadeirada vertical; na parede oposta, o móvel preto suspenso reúne portas e nichos abaixo da televisão. Prateleiras altas com plantas acrescentam verde à composição sem ocupar o caminho entre os móveis. A planta apresenta ainda a cozinha junto ao acesso. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 3.610,15/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio sugerido pelo desenho é conciliar a presença dos volumes escuros com a passagem entre estar, refeições e dormitório. Também importa distinguir os apoios de cada atividade: o sofá voltado à televisão, a mesa próxima à abertura envidraçada e a cama em um ambiente separado, acompanhada por um armário.',
      solution = 'A proposta concentra a marcenaria nas laterais dos ambientes, deixando o percurso central reconhecível. Junto à mesa redonda, a planta indica um apoio amadeirado com cadeira, distinto do lugar de refeições. No quarto, a cabeceira escura recebe uma linha luminosa que evidencia a textura mineral da parede. Cortinas claras e roupa de cama predominantemente branca contrastam com esse fundo. No banheiro, nichos abertos sob a bancada oferecem apoio acessível.',
      result_text = 'O conjunto apresentado nas visualizações estabelece continuidade pelas superfícies amadeiradas e pelos tons cinza, mas diferencia cada ambiente pelo mobiliário. O estar se orienta para a televisão, o quarto concentra descanso e guarda de roupas, e o banheiro combina bancada pontilhada, espelho circular iluminado e prateleira alta. O sofá cinza sobre a parede azul acinzentada estabelece um lugar de pausa com identidade própria. Na hospedagem, esse estar complementa o descanso da cama e acrescenta variedade à experiência do visitante.',
      scope = ARRAY['Composição do estar com sofá cinza e parede azul-acinzentada', 'Painel de televisão com faixas amadeiradas e móvel preto suspenso', 'Mesa redonda junto à abertura envidraçada e apoio lateral com cadeira', 'Dormitório separado com armário de aparência amadeirada', 'Cabeceira escura com linha luminosa sobre a cama', 'Banheiro com bancada pontilhada e nichos inferiores abertos', 'Espelho circular iluminado e prateleira amadeirada com planta pendente']::text[],
      seo_title = 'NOW Butantã | Interiores em azul, preto e amadeirado',
      seo_description = 'Conheça a proposta do NOW Butantã: estar com painel de TV, dormitório separado e marcenaria que combina preto e superfícies amadeiradas.',
      cover_alt = 'Ambiente integrado com parede azulada, espelho vertical, painel amadeirado e sofá claro ao lado da cozinha compacta.'
  WHERE slug = 'ap-now-butanta'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '2c9d2bd90844e8c15a99e92740d2e2e6';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'ap-now-butanta';
  END IF;

  UPDATE public.projects
  SET summary = 'No Spotlights Pinheiros, a proposta organiza cozinha, bancada de apoio e cama em um ambiente contínuo. O amadeirado aproxima visualmente os diferentes usos, enquanto superfícies brancas e beges equilibram os volumes altos. A bancada escura distingue a cozinha, e o apoio com duas cadeiras permite alternar refeições e trabalho.',
      intro = 'As visualizações do estúdio em Pinheiros mostram uma distribuição longitudinal: a cozinha fica junto à entrada, a bancada com duas cadeiras ocupa a parede oposta e a cama se aproxima da abertura com cortinas. Essa disposição reúne os usos sem inserir uma divisória entre preparo e descanso. Na cozinha, o desenho amadeirado contorna a geladeira e prossegue nos armários superiores. Do outro lado, uma estrutura branca de montantes e prateleiras acompanha a bancada e inclui um trecho para pendurar roupas. Perto da cama, a mesma linguagem reaparece na cabeceira, conectando visualmente as extremidades do ambiente. A área do projeto é de 26,43 m². O custo de reforma registrado para este projeto é de R$ 2.782,30/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta é acomodar volumes altos, apoio para refeições e trabalho e uma cama no mesmo campo visual. A proximidade entre esses elementos pede uma composição que diferencie suas funções sem multiplicar barreiras, além de organizar a guarda de objetos e roupas ao longo das paredes.',
      solution = 'O desenho combina armários fechados com prateleiras abertas, concentrando a guarda nas laterais. Sob a TV, a bancada clara oferece apoio para computador ou refeições, com duas cadeiras. A faixa bege na parede contrasta suavemente com o branco, enquanto linhas de luz destacam a prateleira superior e a cabeceira lisa amadeirada. No banheiro, o gabinete suspenso recebe uma bancada clara pontilhada, acompanhada por espelho redondo e fechamento transparente do banho.',
      result_text = 'A proposta apresenta um estúdio em que a repetição do amadeirado dá continuidade ao espaço, e os contrastes marcam usos específicos. Cozinha, apoio de trabalho e descanso permanecem próximos, com a bancada de duas posições oferecendo flexibilidade para diferentes momentos de uma estadia. A cozinha clara com bancada escura oferece uma leitura direta da área de preparo. Para Airbnb, esse contraste busca tornar o apartamento fácil de compreender e visualmente atraente para o hóspede.',
      scope = ARRAY['Cozinha linear com bancada escura pontilhada e armários brancos', 'Composição amadeirada ao redor da geladeira e nos armários superiores', 'Bancada clara com duas cadeiras para refeições e trabalho', 'Estrutura branca com prateleiras e trecho aberto para pendurar roupas', 'Cabeceira lisa amadeirada com linha de luz e quadros acima', 'Parede da TV em branco e bege com prateleira superior iluminada', 'Banheiro com gabinete suspenso, bancada clara pontilhada e espelho redondo']::text[],
      seo_title = 'Spotlights Pinheiros: interiores em branco e amadeirado',
      seo_description = 'Conheça a proposta do Spotlights Pinheiros, com cozinha linear, bancada para refeições e trabalho e marcenaria amadeirada junto à cama.',
      cover_alt = 'Cozinha com armários brancos, bancada preta, nichos amadeirados iluminados e cama clara próxima à porta de vidro.'
  WHERE slug = 'rs-spotlights-pinheiros'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '63f7424058f94a2f028d396e7317471d';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'rs-spotlights-pinheiros';
  END IF;

  UPDATE public.projects
  SET summary = 'Nesta proposta para a Chácara Klabin, o verde acinzentado aproxima armário, bancada de trabalho e cozinha, enquanto os volumes amadeirados delimitam cada trecho. A textura de tijolinhos brancos costura essa frente de mobiliário, diante da área de descanso. Na varanda, uma mesa alta com duas banquetas cria um apoio separado para refeições.',
      intro = 'As visualizações apresentam uma sequência de usos organizada ao longo de uma parede: cozinha junto à entrada, bancada com computador e armário alto próximo à abertura para a varanda. O desenho reúne essas funções pela repetição do verde suave, mas diferencia a cozinha com um contorno amadeirado que envolve armários superiores e nicho aberto. Na parede oposta, cama e sofá ocupam a faixa destinada ao descanso, acompanhados por uma composição bicolor em branco e cinza. O piso de aparência amadeirada percorre o espaço interno e estabelece continuidade entre as duas frentes. A área do projeto é de 25 m². O custo de reforma registrado para este projeto é de R$ 2.280,00/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial está na proximidade entre preparo de alimentos, trabalho, armazenamento e descanso. A proposta precisa distinguir essas atividades sem acrescentar barreiras no trecho central. Também exige equilibrar o volume do armário alto e da cozinha com a abertura visual da bancada e a passagem em direção à varanda.',
      solution = 'O desenho alterna volumes fechados e superfícies abertas: o armário concentra a guarda, enquanto a bancada sob a televisão oferece apoio ao computador, com dois pufes recolhidos abaixo. O painel vertical amadeirado marca a transição para a cozinha sem fechar o ambiente. Tijolinhos brancos dão textura ao fundo, em contraste com as frentes lisas. Trilhos pretos acompanham essa sequência no teto; na varanda, mesa e banquetas também pretas se destacam diante das paredes de aparência tijolada.',
      result_text = 'A proposta organiza funções próximas por meio de mudanças no mobiliário, e não por divisórias entre cozinha, trabalho e descanso. O verde conecta os pontos de armazenamento, o amadeirado demarca a cozinha e a varanda oferece uma superfície de refeição fora da circulação interna. O volume alto em verde acinzentado reúne armazenamento e apoio de trabalho. Para a locação, essa combinação permite acomodar objetos da estadia e atender quem precisa de uma bancada durante a viagem.',
      scope = ARRAY['Frente de marcenaria verde acinzentada com armário alto e bancada de trabalho', 'Cozinha com contorno amadeirado, nicho aberto e bancada escura', 'Parede de tijolinhos brancos com televisão e prateleira suspensa', 'Bancada com cadeira e dois pufes recolhidos sob o tampo', 'Área de descanso com cama, sofá e parede bicolor', 'Trilhos pretos com spots ao longo da frente de marcenaria', 'Varanda com mesa alta redonda e duas banquetas pretas']::text[],
      seo_title = 'Chácara Klabin: marcenaria verde e usos integrados',
      seo_description = 'Proposta na Chácara Klabin combina marcenaria verde, cozinha amadeirada e bancada de trabalho, com descanso integrado e mesa alta na varanda.',
      cover_alt = 'Cozinha com nichos amadeirados, armários cinza e brancos, geladeira escura e parede de fundo com revestimento claro.'
  WHERE slug = 'co-chacara-klabin'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '1db89ba22ea45aacbdf536e99e2f9474';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'co-chacara-klabin';
  END IF;

  UPDATE public.projects
  SET summary = 'No My One Brooklin, a proposta aproxima cozinha, estar e bancada de apoio por meio da marcenaria azul-petróleo. Superfícies amadeiradas e planos claros equilibram a cor, enquanto o quarto permanece separado. As visualizações mostram ainda a extensão do sofá aberta, revelando como essa configuração altera a circulação junto à bancada.',
      intro = 'A proposta para o My One Brooklin, no Brooklin, organiza cozinha e estar em uma faixa longitudinal. De um lado, a bancada pontilhada reúne cuba e cooktop, seguida pelo sofá; do outro, um tampo azul-petróleo com duas cadeiras oferece apoio para trabalho ou refeições sob a televisão. Armários superiores amadeirados e nichos abertos aproveitam as paredes sem ocupar o caminho central. O mesmo tom azul aproxima os móveis baixos, enquanto piso amadeirado, cortina clara e paredes cinza suavizam o contraste. No quarto separado, o desenho troca a cor intensa por uma composição de branco, cinza e amadeirado. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 2.896,32/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio do desenho é acomodar preparo de alimentos, assento e superfície de apoio em um ambiente estreito, mantendo legível o percurso entre eles. A visualização com o sofá estendido evidencia uma condição importante: ampliar a área de descanso reduz o espaço disponível diante da bancada com cadeiras.',
      solution = 'A marcenaria distribui a guarda entre armários fechados, gavetas e nichos, deixando utensílios e objetos em posições distintas. Na cozinha, o revestimento branco em pequenos módulos contrasta com a bancada pontilhada e recebe luz sob o armário. O trilho preto acompanha o eixo do ambiente. Já no quarto, a cabeceira amadeirada com iluminação linear reúne visualmente cama e apoios laterais; o guarda-roupa branco concentra a guarda de roupas sem repetir o peso cromático dos móveis azuis.',
      result_text = 'As visualizações apresentam uma composição em que a cor conecta cozinha e estar, mas não invade o quarto. A separação por paredes e porta resguarda a área da cama, enquanto os móveis alinhados às laterais definem o percurso no ambiente integrado. O azul petróleo torna a cozinha um ponto de identidade do studio. Para a locação, a proposta associa uma imagem reconhecível no anúncio a um conjunto concentrado para preparo e armazenamento.',
      scope = ARRAY['Cozinha linear com frentes azul-petróleo e bancada pontilhada', 'Armários superiores amadeirados e nicho aberto sobre a cozinha', 'Bancada com duas cadeiras sob a televisão para trabalho ou refeições', 'Sofá azul com extensão aberta apresentada na galeria', 'Trilho preto de iluminação no eixo da cozinha e do estar', 'Cabeceira amadeirada com iluminação linear e apoios laterais', 'Guarda-roupa branco no quarto separado']::text[],
      seo_title = 'My One Brooklin | Interiores em azul-petróleo e amadeirado',
      seo_description = 'Proposta no My One Brooklin com cozinha azul-petróleo, bancada para trabalho e refeições, sofá extensível e quarto separado em tons neutros.',
      cover_alt = 'Bancada de trabalho azulada sob televisão, prateleiras amadeiradas e cortina clara em um ambiente integrado de descanso.'
  WHERE slug = 'cc-my-one-brooklin'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '0de23553da8bf5e30c998ef958b1ee99';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'cc-my-one-brooklin';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o DO IT Vila Olímpia organiza cozinha, trabalho e descanso em um ambiente contínuo. A marcenaria escura concentra armários e enquadra a bancada de trabalho, enquanto o piso amadeirado e os tecidos claros equilibram a composição. Uma mesa redonda oferece apoio para refeições separado da escrivaninha.',
      intro = 'As visualizações mostram um espaço alongado, com a cozinha próxima à entrada e a cama junto à abertura com cortinas. Entre esses pontos, o desenho distribui os móveis pelas laterais e mantém uma faixa central de circulação. Na parede oposta à cama, dois volumes altos de marcenaria ladeiam a bancada de trabalho, com televisão acima e prateleira superior. O acabamento escuro desses volumes contrasta com os interiores claros dos armários. Já a parede da cama combina uma faixa inferior cinza-escura com a parte superior clara, criando uma linha horizontal que acompanha também a mesa redonda. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 2.888,35/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar preparo de alimentos, guarda de roupas, trabalho e descanso sem inserir divisórias entre essas atividades. A presença de armários altos e acabamentos escuros também pede contrapontos visuais: superfícies claras, tecidos e áreas livres precisam equilibrar o peso da marcenaria ao longo do ambiente.',
      solution = 'A proposta reúne cabideiro, prateleiras e gavetas em torno da escrivaninha, deixando os diferentes tipos de guarda próximos ao apoio de trabalho. A cozinha ocupa a continuação dessa lateral, com nicho para micro-ondas e bancada escura pontilhada. Do outro lado, a mesa redonda atende às refeições sem ocupar a escrivaninha. Cortinas claras suavizam a abertura junto à cama. No banheiro separado, o gabinete amadeirado escuro contrasta com a cuba branca, e o espelho circular recebe iluminação de contorno.',
      result_text = 'Nas visualizações, a organização depende mais da posição dos móveis do que de divisórias. A marcenaria reúne armazenamento e apoios em uma lateral, enquanto cama e mesa ocupam a outra. O piso amadeirado contínuo aproxima os usos, e o banheiro permanece delimitado. O armário para roupas e a bancada lateral colocam bagagem e trabalho no mesmo conjunto de marcenaria. Para a hospedagem, a intenção é oferecer apoios definidos que deixem o descanso mais organizado.',
      scope = ARRAY['Armários altos com cabideiro e prateleiras nas laterais da escrivaninha', 'Bancada de trabalho com gaveteiro, televisão e prateleira superior', 'Cozinha linear com bancada escura pontilhada e nicho para micro-ondas', 'Mesa redonda preta com cadeira junto à parede bicolor', 'Área de descanso com cama, apoio lateral e cortinas claras', 'Piso de aparência amadeirada no ambiente contínuo', 'Banheiro com gabinete escuro, cuba branca, espelho circular iluminado e box transparente']::text[],
