  UPDATE public.projects
  SET summary = 'Nesta proposta para o HUB Brooklin by EZ, no Brooklin, o azul intenso marca a área de descanso, enquanto a marcenaria cinza reúne cozinha, armários e bancada de apoio na parede oposta. O piso amadeirado claro e o enxoval branco equilibram os planos escuros, e o fechamento transparente mantém a continuidade visual.',
      intro = 'As visualizações mostram um estúdio em que cama, cozinha e apoio de trabalho compartilham o mesmo ambiente. A parede azul envolve a cabeceira cinza, com uma linha de luz na transição entre as duas cores e luminárias direcionadas junto aos travesseiros. Em frente à cama, a televisão ocupa um painel sobre a bancada com cadeira, posicionada ao lado da cozinha. Essa proximidade concentra os apoios sem introduzir uma mesa solta no centro do espaço. Armários altos intercalam os trechos abertos da composição, enquanto o espelho de contorno irregular, próximo à entrada, reflete o dormitório. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 2.607,14/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é aproximar preparo de alimentos, trabalho, guarda de roupas e descanso sem transformar a parede de armários em um bloco visualmente pesado. Também é necessário equilibrar a presença do azul e do cinza escuro com superfícies claras, mantendo legíveis os espaços de circulação ao redor da cama.',
      solution = 'A proposta alterna volumes fechados de marcenaria com a bancada aberta e as prateleiras acima da televisão. Na cozinha, armários superiores aproveitam a altura, enquanto o tampo preto e o revestimento claro em pequenos retângulos distinguem a faixa de preparo. O piso amadeirado percorre o ambiente e aproxima visualmente os usos. Junto ao dormitório, o fechamento transparente com perfis pretos estabelece um limite físico sem criar uma parede opaca; na cabeceira, a iluminação linear evidencia o encontro entre azul e cinza.',
      result_text = 'Nas visualizações, o conjunto se organiza por duas frentes: descanso na parede azul e apoios na marcenaria cinza. A bancada admite trabalho ou uma refeição breve, enquanto os armários verticais concentram a guarda e dispensam peças avulsas entre cama e cozinha.',
      scope = ARRAY['Parede azul intensa com cabeceira cinza e iluminação linear', 'Luminárias direcionadas nas laterais da cama', 'Cozinha linear com tampo preto e revestimento retangular claro', 'Marcenaria cinza com armários superiores e volumes verticais', 'Bancada com cadeira sob a televisão e prateleiras abertas', 'Fechamento transparente com perfis pretos junto ao dormitório', 'Espelho de contorno irregular próximo à entrada']::text[],
      seo_title = 'HUB Brooklin by EZ | Azul e marcenaria no estúdio',
      seo_description = 'Conheça a proposta no HUB Brooklin by EZ: parede azul, cozinha linear e marcenaria cinza que reúne armários, televisão e bancada de apoio.',
      cover_alt = 'Cozinha cinza e branca com armários superiores escuros, nicho iluminado, geladeira prateada e porta ao fundo do corredor.'
  WHERE slug = 'me-hub-brooklin-by-ez'
