  UPDATE public.projects
  SET summary = 'No Modern Estação Butantã, a proposta reúne cozinha linear, bancada com dois assentos e área de descanso em um ambiente alongado. O piso amadeirado conecta os usos, enquanto a parede bicolor dá contorno à cama. Marcenaria clara, tecidos com textura e pequenos apoios circulares equilibram superfícies contínuas e pontos de uso.',
      intro = 'O desenho do estúdio no Butantã posiciona cozinha e banheiro próximos à entrada, deixando cama, bancada e poltrona na sequência do ambiente. Na planta 3D, a circulação acompanha a cozinha e passa entre a bancada e os pés da cama, conectando os setores sem uma divisória para o descanso. As perspectivas mostram uma faixa inferior mais escura nas paredes, separada da porção clara por uma linha branca. Esse traço atravessa o entorno da cama e unifica visualmente o volume do banheiro com a área de dormir. Almofadas em tons terrosos e tecidos claros acrescentam contraste sem romper a paleta neutra. A área do projeto é de 27,82 m². O custo de reforma registrado para este projeto é de R$ 2.372,11/m², conforme a base de contratos da Bewild.',
      challenge = 'A configuração alongada pede uma distribuição que acomode preparo de alimentos, apoio para refeições ou trabalho e descanso sem sobrepor seus acessos. Outro ponto é diferenciar a área da cama em um espaço aberto, mantendo relação visual com a bancada de dois lugares e os volumes de armazenamento na parede oposta.',
      solution = 'A proposta concentra a cozinha em uma lateral e reserva à bancada um trecho diante da cama, permitindo alternar refeições e uso de computador. Um armário alto ocupa a extremidade próxima à cortina. Junto à cama, apoios circulares e uma poltrona oferecem superfícies e assento sem criar uma nova barreira. No banheiro, o gabinete de contorno amadeirado e prateleiras abertas contrasta com o revestimento cinza de aparência mineral.',
      result_text = 'As visualizações apresentam uma composição em que o mobiliário distingue os usos e a cor mantém a continuidade entre eles. A cama ganha um fundo marcado pela faixa escura, enquanto a bancada compartilhada e a poltrona oferecem alternativas de apoio além do descanso.',
      scope = ARRAY['Cozinha linear próxima à entrada, com cuba e área de cocção', 'Bancada amadeirada com dois assentos diante da cama', 'Armário alto junto à extremidade da bancada', 'Parede bicolor com linha branca no entorno da cama', 'Apoios circulares de cabeceira e poltrona lateral', 'Gabinete de banheiro com prateleiras abertas e bancada pontilhada', 'Espelho oval e divisória transparente na área de banho']::text[],
      seo_title = 'Modern Estação Butantã | Estúdio em tons neutros',
      seo_description = 'Conheça a proposta no Modern Estação Butantã: cozinha linear, bancada para dois e parede bicolor organizam os usos em uma composição neutra.',
