  UPDATE public.projects
  SET summary = 'A proposta para o Nex One Paraíso, na Vila Mariana, aproxima cozinha, apoio para refeições e estar sem ocupar o centro da circulação. Marcenaria branca e amadeirada organiza essa sequência, enquanto a bancada pontilhada e os elementos pretos introduzem contraste. Junto à varanda, uma poltrona clara delimita o lugar de pausa.',
      intro = 'Nas visualizações do Nex One Paraíso, a cozinha se concentra em uma parede e se prolonga até uma bancada com duas cadeiras, próxima à abertura para a varanda. Essa disposição reúne preparo, refeições e apoio eventual ao trabalho, deixando uma passagem entre a marcenaria e a poltrona na parede oposta. O branco das frentes inferiores se aproxima das paredes, enquanto o amadeirado dos armários superiores, da prateleira e do piso conecta visualmente os diferentes trechos. Cortinas claras enquadram a esquadria preta e acrescentam textura sem introduzir outra cor dominante. A área do projeto é de 31,43 m². O custo de reforma registrado para este projeto é de R$ 2.386,22/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial sugerido pelas imagens é acomodar equipamentos, armazenamento, assentos e superfície de apoio em um ambiente estreito, mantendo o percurso até a varanda. A proximidade entre cozinha e estar também pede equilíbrio visual: muitos volumes e contrastes poderiam fazer a parede equipada dominar toda a composição.',
      solution = 'O desenho concentra a guarda em módulos superiores e inferiores, com um nicho aberto para o micro-ondas. A prateleira prolonga a linha da marcenaria sobre a televisão, conectando cozinha e apoio de refeições. A bancada pontilhada marca a área de preparo diante do revestimento branco em relevo. Perto da entrada, um pequeno banco amadeirado oferece apoio, enquanto a poltrona ocupa a lateral oposta sem atravessar a passagem.',
      result_text = 'As visualizações apresentam usos próximos, mas reconhecíveis pelos móveis e pelas superfícies de apoio. A concentração dos armários em uma parede mantém o eixo de passagem legível, e a repetição de branco e amadeirado aproxima cozinha, refeições e estar sem apagar suas diferenças. A combinação de armários claros e nichos amadeirados organiza os objetos sem carregar o ambiente. Na locação por temporada, essa leitura procura facilitar o uso e construir uma apresentação acolhedora para o anúncio.',
      scope = ARRAY['Cozinha linear com frentes brancas e armários superiores amadeirados', 'Nicho aberto para micro-ondas acima da área de preparo', 'Bancada pontilhada e revestimento branco em relevo', 'Apoio para refeições e trabalho com duas cadeiras junto à varanda', 'Prateleira contínua sobre a televisão e a cozinha', 'Banco de apoio próximo à entrada', 'Poltrona clara voltada para a parede equipada']::text[],
      seo_title = 'Nex One Paraíso: interiores na Vila Mariana',
