  UPDATE public.projects
  SET summary = 'A proposta para o Latitude Campo Belo organiza cozinha, guarda de roupas, descanso e apoios de refeição e trabalho em um espaço visualmente conectado. O verde pontua a marcenaria e as cadeiras, enquanto os planos cinza e amadeirados estabelecem continuidade. A mesa redonda junto ao banco cria um núcleo de refeições próximo às janelas.',
      intro = 'No Latitude Campo Belo, em Campo Belo, as visualizações apresentam uma sequência que parte da cozinha linear e conduz o olhar até as janelas. Armários inferiores amadeirados e módulos superiores verdes distinguem a área de preparo, seguida por um volume alto de portas cinza destinado à guarda de roupas. A cama ocupa o lado oposto, sem uma divisória fechada entre os usos. Ao fundo, o banco estofado acompanha a mesa redonda branca, enquanto uma bancada verde com cadeira oferece apoio de trabalho ao lado da cabeceira. A repetição dessas cores aproxima peças com funções diferentes. A área do projeto é de 27,75 m². O custo de reforma registrado para este projeto é de R$ 2.882,88/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta é conciliar preparo de alimentos, armazenamento e descanso ao longo de uma passagem compartilhada. Os volumes altos precisam oferecer guarda sem dominar visualmente a composição, enquanto os apoios de refeição e trabalho devem se distinguir da cama mesmo sem o recurso de ambientes fechados.',
      solution = 'O desenho concentra a guarda em frentes cinza contínuas e reserva o verde para pontos específicos: armários da cozinha, bancada de trabalho e gaveteiro junto à cama. A bancada clara pontilhada contrasta com a cuba escura e o revestimento branco retangular. A mesa de base central aproxima as cadeiras do banco, que incorpora compartimentos inferiores. A televisão suspensa dispensa um móvel de piso, e a cabeceira amadeirada demarca o descanso.',
      result_text = 'Nas visualizações, os usos permanecem reconhecíveis pela posição e pelo desenho dos móveis, não por separações completas. O amadeirado conecta cozinha, banco e cabeceira, enquanto o verde distribui pontos de destaque e os grandes planos cinza equilibram a composição. A marcenaria verde sobre a base de madeira dá personalidade à cozinha compacta. Para a locação, a intenção é apresentar um ambiente de preparo organizado e uma paleta que diferencie o imóvel nas fotos.',
      scope = ARRAY['Cozinha linear com frentes amadeiradas e módulos superiores verdes', 'Bancada clara pontilhada e revestimento branco retangular', 'Armário alto cinza com puxadores verticais escuros', 'Mesa redonda branca junto a banco estofado com compartimentos inferiores', 'Bancada verde de trabalho próxima às janelas', 'Cabeceira amadeirada com gaveteiro verde e luminária esférica', 'Televisão suspensa em suporte fixado ao teto', 'Banheiro com box transparente e superfícies claras']::text[],
      seo_title = 'Latitude Campo Belo | Interiores em verde e amadeirado',
      seo_description = 'Conheça a proposta do Latitude Campo Belo, com cozinha linear, armário cinza, banco para refeições e apoio de trabalho em verde junto às janelas.',
      cover_alt = 'Dormitório integrado com cama clara, mesa redonda branca, cadeiras verdes e espelho vertical junto ao armário aberto.'
  WHERE slug = 'tbcf-latitude-campo-belo'
