  UPDATE public.projects
  SET summary = 'A proposta para o Level Brooklin aproxima cozinha, estar, trabalho e refeições em uma faixa contínua, enquanto mantém o quarto separado. O piso amadeirado equilibra as superfícies cinza e o verde suave da marcenaria. Junto ao fechamento envidraçado, mesa oval, banco e vegetação compõem uma segunda área de convivência.',
      intro = 'No Brooklin, o desenho organiza a área social em sequência: a cozinha fica próxima à entrada, a bancada de trabalho acompanha a parede do sofá e a mesa de refeições ocupa a extremidade envidraçada. Essa distribuição reúne atividades cotidianas sem levar o trabalho para dentro do quarto. Nas visualizações, o piso amadeirado dá continuidade aos ambientes, enquanto paredes claras e superfícies de aparência mineral formam uma base discreta. O verde suave aparece na marcenaria, e os elementos pretos — luminárias, esquadrias e suportes — criam contraste pontual, sem dominar a composição. A área do projeto é de 37,38 m². O custo de reforma registrado para este projeto é de R$ 2.908,81/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio espacial da proposta é aproximar usos sociais distintos e, ao mesmo tempo, reservar um ambiente para dormir. A planta também precisa acomodar os apoios de trabalho e refeição sem concentrá-los em uma única mesa, mantendo um percurso entre a entrada, o estar e a área envidraçada.',
      solution = 'A separação entre sala e quarto oferece uma superfície para a televisão voltada ao sofá. A bancada de trabalho ocupa o trecho ao lado do estar, enquanto a mesa oval combina cadeiras com um banco junto à parede. Prateleiras abertas acomodam objetos e plantas sem formar outro fechamento. No banheiro, o gabinete verde sob a bancada pontilhada concentra a guarda, e a faixa iluminada abaixo do espelho destaca o plano de apoio.',
      result_text = 'As visualizações apresentam uma moradia com convivência distribuída e descanso resguardado. No quarto, cortinas claras filtram a relação com a área externa; junto às plantas, a poltrona suspensa cria um ponto de pausa separado do sofá e da mesa de refeições.',
      scope = ARRAY['Cozinha linear com marcenaria em verde suave', 'Bancada de trabalho ao lado do sofá', 'Parede entre sala e quarto com televisão voltada ao estar', 'Mesa oval com cadeiras e banco junto à parede', 'Poltrona suspensa cercada por vasos de plantas', 'Quarto separado com cortinas claras e televisão', 'Banheiro com gabinete verde, bancada pontilhada e espelho iluminado']::text[],
      seo_title = 'Level Brooklin: interiores com quarto reservado e área integrada',
      seo_description = 'Conheça a proposta do Level Brooklin: cozinha, estar e trabalho conectados, quarto separado e mesa oval junto à área envidraçada com plantas.',
