  UPDATE public.projects
  SET summary = 'No The Collection Madalena, na Vila Madalena, a proposta aproxima estar e cozinha por meio da marcenaria amadeirada, com ripas que sinalizam a transição entre os usos. Tons claros equilibram o desenho marcado da bancada e do frontão. Junto ao fechamento envidraçado, mesa redonda e bancada de trabalho oferecem apoios distintos.',
      intro = 'As visualizações apresentam um estar linear, com sofá cinza voltado para a TV e um móvel baixo que acompanha boa parte da parede. Prateleiras amadeiradas acrescentam espaço para livros e objetos sem ocupar o piso, enquanto as frentes fechadas concentram a guarda abaixo da tela. Na cozinha, o mesmo tom amadeirado aparece nos armários inferiores, contrastando com os módulos superiores claros. A planta 3D mostra a área de descanso separada do estar e uma faixa junto ao envidraçamento que reúne a mesa de refeições e o posto de trabalho. A área do projeto é de 38,68 m². O custo de reforma registrado para este projeto é de R$ 3.736,12/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho enfrenta a proximidade entre cozinha, estar e circulação: era necessário distinguir essas funções sem inserir uma barreira visual contínua. Outro ponto era acomodar apoios para refeições e trabalho junto ao envidraçamento, mantendo cada atividade reconhecível e evitando que a mesa redonda fosse o único apoio disponível.',
      solution = 'A proposta usa ripas verticais na lateral da cozinha para marcar seu limite, mantendo intervalos que permitem enxergar o outro ambiente. O móvel baixo da TV estabelece continuidade com os armários amadeirados, enquanto bancada e frontão de aparência mineral rajada concentram o contraste gráfico. No posto de trabalho, a bancada com dois monitores recebe um gaveteiro lateral; acima, a prateleira com iluminação inferior oferece exposição para objetos sem ocupar a superfície de trabalho.',
      result_text = 'Nas visualizações, a repetição do amadeirado conecta os ambientes, e as superfícies claras equilibram os contrastes da cozinha e da tela. A setorização combina uma divisória vazada, mobiliário de apoio específico e a separação da área de descanso indicada na planta. O móvel baixo e as prateleiras organizam o estar sem fechar sua relação com os demais usos. Na moradia, a divisória de madeira introduz um limite acolhedor entre convivência e descanso.',
      scope = ARRAY['Móvel baixo amadeirado e prateleiras na parede da TV', 'Divisória de ripas verticais entre estar e cozinha', 'Armários de cozinha com frentes inferiores amadeiradas e superiores claras', 'Bancada e frontão de aparência mineral rajada', 'Bancada de trabalho com dois monitores e gaveteiro lateral', 'Prateleira com iluminação inferior no posto de trabalho', 'Mesa redonda para refeições junto ao envidraçamento']::text[],
      seo_title = 'The Collection Madalena | Interiores na Vila Madalena',
      seo_description = 'Proposta no The Collection Madalena, na Vila Madalena, com marcenaria amadeirada, divisória ripada e apoios distintos para refeições e trabalho.',
      cover_alt = 'Cozinha de armários claros e nichos amadeirados, bancada junto à janela e móvel baixo longo sob a televisão do estar.'
  WHERE slug = 'jp-the-collection-madalena'
