  UPDATE public.projects
  SET summary = 'A proposta para o The Collection Paulista aproxima cozinha, refeição, trabalho e descanso sem recorrer a divisórias entre esses usos. O armário amadeirado marca a transição entre mesa e bancada, enquanto cinzas, superfícies claras e detalhes escuros diferenciam os elementos. Junto à abertura para a varanda, cama e apoio de trabalho compartilham a faixa de luz natural.',
      intro = 'Nas visualizações, a organização parte de uma cozinha linear próxima à entrada e de uma cama posicionada junto à abertura envidraçada. Entre esses pontos, a mesa redonda branca oferece apoio para refeições, separado da bancada de trabalho com duas cadeiras. Um armário alto de aparência amadeirada ocupa o trecho entre os dois apoios e introduz uma superfície vertical de tom mais quente diante das paredes cinza. A mesma linguagem clara aparece na cabeceira e no piso. Cortinas brancas acompanham a abertura para a varanda, criando uma camada visual entre o interior e a vista externa. A área do projeto é de 26,26 m². O custo de reforma registrado para este projeto é de R$ 2.646,61/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava conciliar a presença da cama com os equipamentos da cozinha, a guarda de roupas e dois tipos de apoio: refeição e trabalho. A questão espacial está em acomodar esses volumes sem transformar o centro em uma sequência de barreiras, mantendo reconhecíveis as áreas de preparo, permanência e passagem.',
      solution = 'A proposta concentra os equipamentos e armários da cozinha em uma parede, com bancada escura contrastando com frentes cinza e módulos superiores claros. A mesa redonda fica fora dessa linha, enquanto o apoio de trabalho ocupa o trecho ao lado do armário alto, sob a tela. No banheiro, o fechamento transparente do box mantém a leitura dos revestimentos claros; a prateleira amadeirada atravessa a parede da cuba e do vaso, oferecendo apoio sem acrescentar outro volume fechado.',
      result_text = 'As visualizações apresentam uma composição em que os móveis distinguem funções dentro do espaço compartilhado. O contraste mais forte fica na cozinha, enquanto cama e bancada recebem tons claros. O armário amadeirado conecta visualmente essas áreas e concentra a guarda em um volume definido. A mesa redonda oferece um lugar de refeição próprio diante da cozinha de tons neutros. Para a hospedagem, essa escolha aproxima o studio da experiência cotidiana de uma casa.',
      scope = ARRAY['Cozinha linear com bancada escura e armários cinza e claros', 'Mesa redonda branca como apoio de refeições', 'Bancada de trabalho com duas cadeiras sob a tela', 'Armário alto amadeirado entre mesa e bancada', 'Cama com cabeceira clara e apoios laterais', 'Cortinas brancas junto à abertura para a varanda', 'Banheiro com box transparente, espelho arredondado e prateleira amadeirada']::text[],
      seo_title = 'The Collection Paulista | Interiores em cinza e amadeirado',
      seo_description = 'Proposta para o The Collection Paulista com cozinha linear, mesa redonda, bancada de trabalho e armário amadeirado junto à área de descanso.',
      cover_alt = 'Cama próxima à varanda envidraçada, armário amadeirado, cozinha compacta ao fundo e mesa de apoio com cadeira clara.'
  WHERE slug = 'az-the-collection-paulista'
