  UPDATE public.projects
  SET summary = 'A proposta para o Mobi Tucuruvi organiza trabalho, refeições e descanso em torno de uma bancada amadeirada. Entre o sofá claro e a cama, esse móvel reúne gavetas e um compartimento com espelho. Cinzas, superfícies claras e detalhes pretos equilibram o conjunto, enquanto o armário concentra a guarda de roupas junto ao leito.',
      intro = 'Nas visualizações do Mobi Tucuruvi, a bancada ocupa uma posição central: de um lado, aproxima-se do sofá; do outro, recebe a cadeira de trabalho e estabelece um limite baixo para a área da cama. As cadeiras adicionais permitem usar o mesmo tampo como apoio para refeições. Acima dele, a televisão suspensa dispensa um rack no piso. O acabamento amadeirado reaparece na cabeceira e no volume que envolve a geladeira, conectando visualmente setores distintos. Já o sofá claro, as cortinas e as paredes neutras contrastam com os contornos pretos das cadeiras e da iluminação. A área do projeto é de 31,21 m². O custo de reforma registrado para este projeto é de R$ 2.242,87/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é acomodar uma superfície de trabalho e refeições entre estar e descanso sem transformar essa divisão em uma parede. A proposta também precisa reunir roupas e pequenos objetos em pontos definidos, mantendo o acesso à cozinha e a passagem ao lado da cama.',
      solution = 'O desenho da bancada incorpora gavetas e uma tampa elevável com espelho, que revela divisórias para pequenos itens sem exigir outro móvel de apoio. Junto à cama, o armário apresenta cabideiros, prateleiras e gavetas, distribuindo diferentes formas de guarda. Na cozinha, frentes cinzas e um fundo preto contrastam com o entorno amadeirado. No banheiro, superfícies claras, piso de aparência pontilhada e fechamento transparente do banho recebem detalhes pretos em puxador e acessórios.',
      result_text = 'As visualizações apresentam uma organização em que a bancada aproxima usos e, ao mesmo tempo, marca a transição para o descanso. A repetição do amadeirado conecta cozinha, mesa e cabeceira, enquanto os volumes de guarda evitam depender apenas de superfícies expostas para organizar objetos.',
      scope = ARRAY['Bancada amadeirada para trabalho e refeições entre sofá e cama', 'Compartimento com divisórias e tampa elevável com espelho', 'Televisão suspensa sobre a bancada central', 'Armário junto à cama com cabideiros, prateleiras e gavetas', 'Cabeceira amadeirada sob parede cinza com inscrição luminosa azul', 'Cozinha com frentes cinzas, fundo preto e entorno amadeirado da geladeira', 'Banheiro claro com piso pontilhado e fechamento transparente do banho']::text[],
      seo_title = 'Mobi Tucuruvi: bancada multifuncional e interiores',
