  UPDATE public.projects
  SET summary = 'Neste estúdio em Pinheiros, a proposta organiza cozinha, apoio de trabalho e descanso ao longo de uma circulação central. A marcenaria alterna superfícies claras e amadeiradas, enquanto o verde suave junto à cama diferencia o setor de descanso. Nichos abertos, armários e uma bancada com duas cadeiras distribuem funções sem criar novos cômodos.',
      intro = 'O desenho para o My One Estação Frandique Coutinho aproxima usos distintos sem tratar todo o espaço da mesma maneira. Na entrada, a bancada amadeirada com duas cadeiras fica diante da cozinha linear, oferecendo apoio para trabalho ou refeições. Mais adiante, o sofá claro ocupa a lateral oposta à cama, com a televisão instalada em um suporte vertical entre os dois. A base de cores claras dá continuidade ao ambiente; o amadeirado marca os apoios e os nichos, enquanto o verde suave e os tecidos rosados concentram a cor no descanso. A área do projeto é de 28,4 m². O custo de reforma registrado para este projeto é de R$ 2.389,03/m², conforme a base de contratos da Bewild.',
      challenge = 'A configuração estreita pede uma distribuição que concilie preparo de alimentos, assentos, guarda de roupas e cama sem ocupar a passagem central. Outro desafio é diferenciar o descanso da cozinha e da bancada de trabalho, já que esses usos permanecem conectados visualmente e não contam com uma separação completa.',
      solution = 'A proposta concentra os armários da cozinha em uma lateral e acomoda a bancada de dois lugares na parede oposta. O guarda-roupa reúne cabideiro, prateleiras e compartimentos superiores, concentrando a guarda junto à cama. Na cozinha, o nicho amadeirado interrompe as portas claras e recebe plantas e objetos. O revestimento pontilhado acrescenta contraste, enquanto a faixa verde atrás da cama delimita visualmente o descanso sem erguer uma divisória.',
      result_text = 'As visualizações apresentam um estúdio em que a passagem conecta os diferentes apoios, da bancada de entrada à área junto à janela. A repetição do amadeirado aproxima cozinha e trabalho, enquanto cor, tecidos e composição da cabeceira distinguem a cama do restante.',
      scope = ARRAY['Cozinha linear com armários inferiores amadeirados e superiores claros', 'Bancada de trabalho ou refeições com duas cadeiras', 'Guarda-roupa com cabideiro, prateleiras e compartimentos superiores', 'Nicho amadeirado na cozinha com plantas pendentes', 'Revestimento pontilhado acima da bancada da cozinha', 'Faixa verde e apoio estreito para quadros junto à cabeceira', 'Televisão em suporte vertical entre cama e sofá']::text[],
