  UPDATE public.projects
  SET summary = 'No Greenview Brooklin, em Santo Amaro, a proposta aproxima cozinha, bancada de apoio e cama sem recorrer a divisórias entre esses usos. Superfícies amadeiradas e tons claros conectam o ambiente, enquanto cadeiras, puxadores e trilho de iluminação escuros pontuam a composição. A cortina ocupa o fundo e suaviza a passagem de luz.',
      intro = 'As visualizações apresentam um estúdio organizado por duas frentes: de um lado, a cozinha e a bancada com duas cadeiras; do outro, a cama. Entre elas, uma faixa de circulação permite acessar os diferentes apoios. O piso de aparência amadeirada prolonga a tonalidade dos armários inferiores, enquanto paredes e roupa de cama claras reduzem o contraste das superfícies maiores. O verde aparece discretamente na vegetação pendente e no apoio lateral da cama. Ao fundo, a cortina de altura total forma um plano contínuo que acompanha a área de descanso e a bancada. A área do projeto é de 22,02 m². O custo de reforma registrado para este projeto é de R$ 2.904,84/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é aproximar preparo de alimentos, refeições, trabalho e descanso em um único ambiente, mantendo acesso à cama e aos armários. A presença da geladeira junto à bancada exige uma composição que acomode esse volume sem interromper a sequência de apoios na mesma lateral.',
      solution = 'A cozinha concentra cuba e cooktop sobre uma bancada clara pontilhada, com gavetas e portas abaixo e nicho amadeirado acima. Após a geladeira, o tampo com duas cadeiras oferece apoio para refeições ou trabalho, sob a televisão e uma prateleira. No banheiro, o gabinete amadeirado, a bancada pontilhada e as superfícies espelhadas retomam a composição da cozinha; a transparência da divisória mantém visível a área de banho.',
      result_text = 'A proposta estabelece continuidade pelas cores e diferencia os usos pelo mobiliário: armários e bancada para preparo, tampo com cadeiras para atividades sentadas e cama junto à cortina para descanso. Os elementos escuros marcam detalhes sem dominar os planos claros. A parede verde e os planos amadeirados acrescentam identidade à unidade destinada à locação. O objetivo é que o hóspede encontre um ambiente acolhedor, com apoios de trabalho e descanso reconhecíveis.',
      scope = ARRAY['Cozinha linear com cuba, cooktop e bancada clara pontilhada', 'Armários inferiores amadeirados com gavetas e puxadores escuros', 'Nicho superior com vegetação pendente e revestimento branco retangular', 'Bancada com duas cadeiras sob televisão e prateleira', 'Área de descanso com cortina de altura total e apoio lateral verde', 'Trilho escuro com pontos de luz direcionáveis', 'Banheiro com gabinete amadeirado, espelheira e divisória transparente']::text[],
      seo_title = 'Greenview Brooklin | Estúdio integrado em Santo Amaro',
      seo_description = 'Conheça a proposta do Greenview Brooklin, em Santo Amaro: cozinha amadeirada, bancada para dois e descanso conectados por tons claros.',
      cover_alt = 'Cama clara diante de parede verde suave, espelho oval, cozinha compacta e bancada amadeirada com cadeira de trabalho.'
  WHERE slug = 'es'
