  UPDATE public.projects
  SET summary = 'No Voxx Itaim, na Vila Nova Conceição, a proposta organiza cozinha, trabalho e descanso com uma faixa contínua de marcenaria amadeirada. Bancadas escuras e armários superiores em tom azul-acinzentado contrastam com cortinas e roupa de cama claras. Espelhos, nichos iluminados e uma mesa redonda completam a composição sem fechar os usos em cômodos separados.',
      intro = 'As visualizações apresentam um estúdio em que a cozinha ocupa uma das laterais e conduz o olhar até a bancada de trabalho, junto à cortina. Na lateral oposta, a cama recebe uma cabeceira amadeirada com apoios baixos, enquanto uma pequena mesa redonda oferece lugar para refeições. O espelho acima da cabeceira reflete a cozinha e estende visualmente a profundidade desse trecho. A base clara de piso, paredes e tecidos equilibra a presença dos volumes amadeirados e das linhas escuras, que destacam bancadas, molduras e iluminação no teto. A área do projeto é de 25,73 m². O custo de reforma registrado para este projeto é de R$ 3.493,03/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar equipamentos de cozinha, superfície de trabalho e apoios de refeição próximos à cama, sem fragmentar o espaço com novas divisões. Outro ponto era dosar a presença dos armários: oferecer áreas de guarda e exposição sem fazer a composição parecer uma sequência de volumes fechados.',
      solution = 'A proposta concentra geladeira, bancada e demais equipamentos em uma linha de marcenaria, com iluminação sob os armários para destacar a superfície de preparo e o fundo canelado. Ao final, a mesa de trabalho ocupa um nicho próprio, acompanhado de cadeira com rodízios. Junto à entrada, prateleiras abertas brancas alternam com nichos amadeirados iluminados para livros, plantas e pequenos objetos. Na área de descanso, a mesa redonda evita uma quina voltada à passagem, e o pendente marca o apoio de refeição.',
      result_text = 'Nas visualizações, os usos permanecem próximos, mas são reconhecíveis pelos móveis e pela iluminação. A continuidade amadeirada conecta cozinha e descanso; já o espelho, as prateleiras abertas e os tecidos claros reduzem visualmente o peso dos armários e painéis.',
      scope = ARRAY['Cozinha linear com bancada escura e equipamentos alinhados à marcenaria', 'Armários superiores azul-acinzentados com frentes translúcidas', 'Fundo canelado com iluminação sob os armários da cozinha', 'Bancada de trabalho junto à cortina com cadeira de rodízios', 'Cabeceira amadeirada com apoios baixos e espelho horizontal', 'Mesa redonda escura com cadeira estofada e pendente', 'Estante de entrada com nichos iluminados e prateleiras brancas']::text[],
      seo_title = 'Voxx Itaim: interiores na Vila Nova Conceição',
      seo_description = 'Proposta de estúdio no Voxx Itaim, na Vila Nova Conceição, com cozinha linear, bancada de trabalho, espelho e marcenaria amadeirada.',
      cover_alt = 'Cama com cabeceira amadeirada, divisória escura vazada e cozinha linear, acompanhada de plantas e pontos de luz no teto.'
