  UPDATE public.projects
  SET summary = 'A proposta para o estúdio no The Collection, em Perdizes, organiza cozinha, descanso, trabalho e refeições ao longo de um espaço contínuo. O painel amadeirado com bancada diante da cama conecta diferentes apoios, enquanto cinzas, superfícies claras e iluminação linear distinguem os planos sem recorrer a divisórias entre os usos principais.',
      intro = 'Nas visualizações, a cama ocupa a faixa central do estúdio, entre a cozinha próxima à entrada e os apoios de trabalho e refeição junto à abertura envidraçada. Diante dela, o painel da televisão reúne prateleiras e uma bancada comprida, com espaço inferior para um pufe e um equipamento de bebidas. O acabamento amadeirado desse conjunto acompanha visualmente o piso e contrasta com as frentes lisas cinza dos armários. Na parede oposta, a cabeceira escura destaca a roupa de cama clara, enquanto uma linha de luz marca a transição para a parte superior da parede. A área do projeto é de 29,73 m². O custo de reforma registrado para este projeto é de R$ 2.402,69/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar atividades distintas sem fragmentar o eixo entre a entrada e a abertura ao fundo. A cama permanece exposta ao ambiente principal, exigindo que armários, bancada e apoios menores se concentrem nas laterais. O lavatório externo ao banheiro também pede uma delimitação própria junto à área de descanso.',
      solution = 'A marcenaria concentra superfícies de apoio e armazenamento nas bordas: um armário alto de portas lisas fica próximo ao painel da televisão, e prateleiras suspensas recebem objetos sem ocupar o piso. Ao fundo, a bancada com cadeira de trabalho se diferencia da mesa redonda com duas cadeiras, separando as tarefas pela disposição do mobiliário. Junto à cama, o lavatório ocupa um nicho lateral com bancada de aparência marmorizada, espelho redondo e prateleiras abertas; uma faixa vertical de parede delimita esse conjunto.',
      result_text = 'O resultado proposto combina continuidade visual e apoios distintos para cada atividade. A repetição do amadeirado aproxima os setores, enquanto a cabeceira cinza e as linhas de iluminação dão destaque ao descanso. Trabalho e refeições permanecem próximos à abertura, sem interromper a sequência do ambiente.',
      scope = ARRAY['Organização linear entre cozinha, cama e área junto à abertura', 'Painel amadeirado para televisão com bancada e prateleiras', 'Armário alto com portas lisas em tom cinza', 'Bancada de trabalho junto à abertura envidraçada', 'Mesa redonda com duas cadeiras para refeições', 'Cabeceira escura com iluminação linear acima', 'Lavatório externo com espelho redondo e prateleiras abertas']::text[],
      seo_title = 'The Collection em Perdizes | Estúdio e marcenaria',
