  UPDATE public.projects
  SET summary = 'A proposta para o estúdio no Nurban Santa Cecília, em Campos Elíseos, reúne cozinha linear, cama e bancada com duas cadeiras no mesmo ambiente. O azul profundo marca a cozinha, enquanto a cabeceira e os elementos amadeirados contrapõem os armários escuros. Na varanda, uma mesa redonda oferece outro apoio para refeições.',
      intro = 'Nas visualizações, a cozinha ocupa uma extremidade do estúdio, e a cama se posiciona entre a cabeceira amadeirada e a bancada sob a televisão. Essa disposição aproxima preparo, descanso e trabalho sem recorrer a divisórias altas entre eles. As paredes de aparência mineral cinza formam um fundo contínuo, contrastado pela roupa de cama clara e pelas cortinas brancas. O amadeirado aparece em lados opostos do ambiente, na cabeceira e na composição da bancada com armários superiores, criando uma ligação visual entre o lugar de dormir e o apoio para outras atividades. A área do projeto é de 25,83 m². O custo de reforma registrado para este projeto é de R$ 2.765,47/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho está em acomodar usos próximos sem deixar que a cozinha domine a área de descanso. Armários escuros ocupam boa parte da parede de preparo; por isso, superfícies claras, pontos de luz e trechos amadeirados são importantes para distribuir os contrastes pelo ambiente, em vez de concentrá-los em uma única extremidade.',
      solution = 'A cozinha proposta concentra cooktop, duas cubas e nicho para micro-ondas em uma composição linear, com bancada clara pontilhada e revestimento azul em relevo. Em frente à cama, a bancada amadeirada com duas cadeiras pode apoiar refeições ou trabalho, sem exigir mesas separadas para cada atividade. A iluminação sob os armários superiores destaca esse plano de apoio. Já a luz junto à cabeceira desenha uma faixa horizontal que diferencia visualmente o descanso da área de preparo.',
      result_text = 'As visualizações apresentam um estúdio organizado por frentes de uso: cozinha ao fundo, descanso junto à cabeceira e apoio multifuncional sob a televisão. A mesa da varanda acrescenta uma alternativa para sentar e fazer refeições, separada do núcleo principal. As duas cadeiras e o apoio de refeições acrescentam um uso compartilhado à área compacta. Na locação por temporada, esse arranjo procura ampliar a experiência oferecida ao hóspede sem acrescentar uma mesa isolada.',
      scope = ARRAY['Cozinha linear com armários escuros e nicho para micro-ondas', 'Bancada clara pontilhada com cooktop e duas cubas', 'Revestimento azul profundo em relevo na cozinha', 'Cabeceira amadeirada com faixa de iluminação', 'Bancada sob a televisão com duas cadeiras e armários superiores', 'Mesa redonda com duas cadeiras na varanda', 'Composição de paredes cinza, cortinas brancas e roupa de cama clara']::text[],
      seo_title = 'Nurban Santa Cecília: projeto de estúdio em Campos Elíseos',
      seo_description = 'Conheça a proposta do Nurban Santa Cecília, em Campos Elíseos: cozinha azul, cabeceira amadeirada e bancada para refeições ou trabalho.',
      cover_alt = 'Cozinha com armário alto preto, nichos amadeirados, bancada cinza e mesa compacta acompanhada de duas cadeiras escuras.'
  WHERE slug = 'ec-nurban-santa-cecilia'
