  UPDATE public.projects
  SET summary = 'O On Vila Madalena transforma a varanda em parte ativa da experiência de uso dos seus 25,75 m². Mesa de refeições e bancada de trabalho ficam junto ao envidraçamento, enquanto a cama ocupa o interior. Para locação, essa distribuição cria apoios úteis ao hóspede e dá ao studio uma identidade ligada à permanência junto à janela.',
      intro = 'A cabeceira amadeirada traz uma sensação de acolhimento à área de descanso e reaparece no nicho da cozinha e no tampo de trabalho. O cinza da parede da varanda introduz um fundo mais contido, equilibrado pela mesa branca e pela textura do painel de vegetação. Madeira, cinza e branco se complementam pela alternância entre calor visual, sobriedade e leveza.

Os perfis escuros da esquadria e a bancada preta da cozinha dão contorno aos dois setores. A transparência da porta permite perceber a varanda a partir da cama, mantendo a conexão visual mesmo com usos separados. O custo de reforma registrado para esta unidade foi de R$ 2.775,05/m².',
      challenge = 'Distribuir trabalho, refeições e descanso em um studio para locação pede mais do que inserir móveis pequenos. É preciso dar lugar a atividades que podem ocorrer em horários diferentes. Neste caso, a varanda oferece uma extensão de uso, e a relação com o interior define como ela participa da estadia.',
      solution = 'A bancada encostada na parede recebe o computador, e a mesa redonda estabelece um apoio próprio para refeições. A cama fica preservada na área interna. O nicho elevado para micro-ondas libera a bancada da cozinha de mais um equipamento solto. No banheiro, madeira, bancada escura e espelho redondo com alça retomam a combinação de superfícies suaves e detalhes marcados.',
      result_text = 'A varanda equipada oferece um argumento concreto para apresentar o imóvel na locação: há lugares distintos para trabalhar, comer e descansar. Essa distribuição pode integrar a proposta de um anúncio no Airbnb, conectando o investimento à experiência oferecida. O hóspede pode trabalhar junto à janela e retornar a uma área de descanso com menos atividades ao redor da cama.',
      scope = ARRAY['Varanda com mesa branca redonda de base central', 'Bancada amadeirada para trabalho junto à janela', 'Esquadria de vidro com perfis escuros entre cama e varanda', 'Cabeceira de madeira na área de descanso', 'Cozinha com bancada preta e nicho elevado para micro-ondas', 'Painel de vegetação fotografado na varanda', 'Gabinete de banheiro com cuba de apoio e espelho redondo com alça']::text[],
      seo_title = 'Studio de 25,75 m² na Vila Madalena — On | Bewild',
      seo_description = 'Conheça a reforma do On Vila Madalena: studio de 25,75 m² com mesa redonda e bancada de trabalho na varanda. Veja fotos e projeto 3D.',
      cover_alt = 'Foto da varanda do On Vila Madalena voltada para a cama, com porta de vidro aberta, cozinha ao fundo e piso amadeirado.'
