  UPDATE public.projects
  SET summary = 'A proposta para o Vitacon Boa Vista, no Alto da Boa Vista, aproxima cozinha, apoio para refeições e trabalho e área de descanso por meio de uma paleta contínua. Superfícies amadeiradas se destacam entre planos claros e cinza, enquanto a marcenaria concentra armazenamento e define os apoios de cada uso.',
      intro = 'Nas visualizações, o desenho combina frentes lisas em tom claro com superfícies amadeiradas na cozinha, na mesa e na cabeceira. Essa repetição aproxima visualmente os diferentes usos, sem exigir que todos os móveis tenham a mesma aparência. Ao lado da cozinha, uma mesa com duas cadeiras fica sob a televisão e oferece apoio tanto para refeições quanto para trabalho. Na área da cama, a faixa cinza da parede acompanha a cabeceira, criando um fundo mais escuro para a roupa de cama clara. O armário de portas lisas reúne a guarda de roupas junto ao descanso. A área do projeto é de 24 m². O custo de reforma registrado para este projeto é de R$ 2.768,17/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta está em acomodar apoios de cozinha, mesa compartilhada e armazenamento sem transformar todas as paredes em volumes fechados. Na área de descanso, o desenho também precisa equilibrar a presença do guarda-roupa com a cama, mantendo distintos os planos de fundo e o mobiliário.',
      solution = 'A cozinha reúne armários superiores claros, base amadeirada e bancada preta, com um nicho aberto entre os volumes fechados. Ao lado, a mesa ocupa a parede da televisão, e uma prateleira alta oferece apoio sem tomar sua superfície. No banheiro, a proposta repete o contraste entre cinza, preto e amadeirado. O espelho de contorno orgânico suaviza a composição de linhas retas, enquanto o fechamento transparente do box mantém o revestimento claro visível.',
      result_text = 'As visualizações apresentam uma composição em que cada apoio tem posição reconhecível: armazenamento na cozinha e no guarda-roupa, mesa para usos alternados e cabeceira marcando o descanso. A continuidade de cores conecta essas partes, enquanto bancadas escuras e planos amadeirados estabelecem contrastes localizados.',
      scope = ARRAY['Cozinha com bancada preta e armários de frentes claras e amadeiradas', 'Nicho aberto entre a bancada e os armários superiores', 'Mesa com duas cadeiras sob a televisão', 'Prateleira alta na parede cinza da mesa', 'Cabeceira amadeirada associada à faixa cinza da parede', 'Guarda-roupa de portas lisas junto à cama', 'Banheiro com espelho orgânico, bancada escura e box transparente']::text[],
      seo_title = 'Vitacon Boa Vista: interiores no Alto da Boa Vista',
      seo_description = 'Proposta de interiores no Vitacon Boa Vista, no Alto da Boa Vista, com cozinha compacta, mesa para dois e contrastes entre cinza e amadeirado.',
      cover_alt = 'Cozinha com armários cinza e amadeirados, bancada preta, nichos iluminados e passagem livre junto à área de descanso.'
  WHERE slug = 'jr-vitacon-boa-vista'
