  UPDATE public.projects
  SET summary = 'No Place Klabin Residence, na Chácara Klabin, a proposta organiza cozinha, guarda e descanso ao longo de um percurso até a varanda. Frentes cinzas e superfícies amadeiradas aproximam os diferentes móveis, enquanto a parede escura atrás da cama destaca o setor de descanso sem separá-lo do restante do estúdio.',
      intro = 'As visualizações apresentam um estúdio em que a cozinha ocupa uma lateral próxima à entrada, com a cama posicionada junto à abertura da varanda. Entre esses pontos, os armários altos e o pequeno apoio de trabalho acompanham uma das paredes, deixando uma passagem ao lado da cama. Na parede oposta, um móvel baixo oferece guarda fechada e uma superfície de apoio sem bloquear a vista até a cortina. O desenho combina planos claros, frentes cinzas e aparência amadeirada; o contraste mais intenso fica concentrado na parede da cabeceira, que dá destaque à composição do descanso. A área do projeto é de 23,3 m². O custo de reforma registrado para este projeto é de R$ 2.918,45/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é aproximar preparo de alimentos, armazenamento, trabalho e descanso sem transformar os móveis em barreiras no percurso. Como a cama permanece à vista desde a entrada, a proposta também precisa relacionar sua composição à cozinha e aos armários, mantendo diferenças visuais entre as funções.',
      solution = 'A marcenaria alterna volumes altos junto à geladeira e um armário baixo na parede oposta. O tampo amadeirado desse móvel retoma a aparência da cabeceira e dos nichos da cozinha, conectando os usos pela cor. A bancada pontilhada distingue a área de preparo, enquanto a mesa com cadeira oferece apoio de trabalho diante da cama. No banheiro, superfícies claras e o fechamento transparente do banho contrastam com acessórios escuros, sem acrescentar outra cor à paleta.',
      result_text = 'O resultado proposto reúne funções próximas, mas reconhecíveis pelo desenho dos apoios e pela altura dos móveis. A continuidade amadeirada conecta entrada, cozinha e cama; já o fundo escuro da cabeceira concentra a atenção no descanso, em contraste com as cortinas claras. Na locação por temporada, o móvel de apoio próximo à cama complementa a cozinha linear. O desenho procura distribuir as atividades com clareza, valorizando a funcionalidade do apartamento para o hóspede.',
      scope = ARRAY['Cozinha linear com bancada de aparência pontilhada e nicho amadeirado', 'Armários altos cinzas junto à geladeira', 'Móvel baixo com portas cinzas e tampo amadeirado na circulação', 'Apoio de trabalho com cadeira diante da cama', 'Cabeceira amadeirada sob parede escura com composição de quadros', 'Cortinas claras na abertura para a varanda', 'Banheiro com superfícies claras, fechamento transparente e acessórios escuros']::text[],
      seo_title = 'Place Klabin Residence: interiores na Chácara Klabin',
      seo_description = 'Conheça a proposta do Place Klabin Residence, na Chácara Klabin: cozinha linear, marcenaria cinza e amadeirada e descanso integrado.',
      cover_alt = 'Cozinha linear de armários cinza e amadeirados, geladeira prateada e móvel de apoio com tampo claro perto da cama.'
  WHERE slug = 'ah-place-klabin-residence'
