  UPDATE public.projects
  SET summary = 'O Now Butantã dá personalidade aos 29,35 m² pela relação entre tons de azul, madeira e uma parede de aparência de tijolos avermelhados. O studio destinado à locação reúne descanso, refeições e trabalho em uma composição expressiva. A identidade visual se apoia em elementos repetidos entre os setores, além dos objetos de decoração.',
      intro = 'Na área de dormir, os tons quentes da parede e da cabeceira encontram os azuis dos detalhes do mobiliário e dos tecidos. A combinação alterna calor e frescor visual, enquanto a roupa de cama clara oferece uma pausa entre as cores. Na cozinha, a marcenaria amadeirada se destaca diante do revestimento preto brilhante, que retoma os perfis escuros vistos em outros pontos.

O armário envidraçado com moldura preta, o trilho de spots e os contornos do espelho na entrada formam uma família de detalhes. A bancada de trabalho com gavetas azuladas liga a função profissional à mesma paleta. O custo de reforma registrado para este studio foi de R$ 3.185,69/m².',
      challenge = 'Uma apresentação marcante pode ser útil a um imóvel de locação, mas precisa acompanhar usos bem definidos. O desafio neste studio é distribuir as cores entre volumes próximos sem tornar toda a composição igualmente intensa. Ao mesmo tempo, refeições e trabalho precisam de apoios próprios, para que a cama permaneça associada ao descanso.',
      solution = 'A mesa redonda próxima à abertura envidraçada estabelece um ponto de refeições. A bancada sob a televisão recebe o computador e incorpora gavetas. Na cozinha, a luz sob os armários destaca a área de preparo, enquanto o revestimento escuro aproxima esse trecho dos perfis do armário. O banheiro retoma o azul e a madeira, ampliando a continuidade da linguagem.',
      result_text = 'Na apresentação para locação por temporada, a paleta oferece uma identidade reconhecível nas fotografias. O vínculo com o investimento também está no uso: mesa, bancada e armazenamento dão suporte à permanência do hóspede. A arquitetura reúne personalidade e organização: o hóspede encontra apoios para momentos diferentes da estadia, com continuidade entre as cores dos móveis e dos ambientes.',
      scope = ARRAY['Cabeceira com painel de madeira e revestimento de aparência de tijolo', 'Painel da televisão integrado à bancada de trabalho', 'Gavetas azuis e prateleiras com perfis escuros', 'Cozinha com revestimento preto brilhante e iluminação sob os armários', 'Mesa escura de refeições próxima à cama', 'Banco e espelho alto no setor de entrada azul', 'Banheiro com espelho redondo e gabinete amadeirado']::text[],
      seo_title = 'Studio de 29,35 m² no Butantã — Now | Bewild',
      seo_description = 'Explore o Now Butantã, studio de 29,35 m² com tijolinhos, detalhes azuis e bancada de trabalho integrada ao painel da TV. Fotos da obra pronta.',
      cover_alt = 'Foto do Now Butantã com cama, almofadas azuis e alaranjadas, cabeceira amadeirada e parede com aparência de tijolo.'
  WHERE slug = 'ea-now-butanta'
