  UPDATE public.projects
  SET summary = 'A proposta para o ID Home & Lifestyle Paraíso aproxima cozinha, descanso e uma bancada de uso duplo. A marcenaria amadeirada organiza os volumes altos, enquanto frentes claras e prateleiras escuras equilibram o conjunto. Duas cadeiras azuladas marcam o apoio para refeições ou trabalho diante da cama.',
      intro = 'No bairro Paraíso, o desenho deste estúdio reúne os usos em um ambiente compartilhado, sem criar divisórias entre a cozinha e a cama. A geladeira ocupa um vão na marcenaria amadeirada, que também aparece nos armários altos ao redor da bancada com duas cadeiras. Essa repetição aproxima visualmente os diferentes trechos do ambiente. Tons claros predominam nas frentes inferiores, na roupa de cama e na cortina, contrapondo-se à bancada preta e às prateleiras escuras. O azul das cadeiras concentra a cor junto ao apoio de refeições e trabalho, sem disputar atenção com os volumes maiores. A área do projeto é de 21,81 m². O custo de reforma registrado para este projeto é de R$ 2.980,28/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta é acomodar preparo de alimentos, apoio para duas pessoas, armazenamento e descanso mantendo a passagem entre os móveis. Como a cama e a cozinha compartilham o mesmo campo visual, o desenho precisa diferenciar suas funções sem recorrer a uma separação física que fragmente o ambiente.',
      solution = 'A cozinha concentra cuba e cooktop em uma bancada escura de aparência pontilhada, com armários inferiores claros e prateleiras abertas acima. O revestimento branco retangular recebe luz sob a prateleira, evidenciando seu relevo. No trecho diante da cama, a bancada clara fica entre armários altos, com televisão suspensa e uma segunda prateleira iluminada. As cadeiras podem atender tanto às refeições quanto ao trabalho. No banheiro, superfícies cinza-claras e o fechamento transparente do box mantêm uma composição de pouco contraste.',
      result_text = 'As visualizações apresentam uma organização em que os móveis delimitam atividades sem fechar o espaço. A cortina clara forma um fundo contínuo ao lado da cama, enquanto os armários concentram a guarda nas laterais da bancada e acima da geladeira. Os nichos e as frentes amadeiradas dão continuidade à composição, enquanto a cozinha concentra os apoios de preparo. Para locação, o projeto busca conciliar uma apresentação acolhedora com uma rotina simples para o hóspede.',
      scope = ARRAY['Cozinha linear com cuba e cooktop sobre bancada escura pontilhada', 'Marcenaria amadeirada envolvendo o vão da geladeira', 'Armários inferiores claros com puxadores pretos', 'Prateleiras escuras com iluminação voltada às superfícies de apoio', 'Bancada para duas pessoas com cadeiras azuladas e televisão suspensa', 'Armários altos nas laterais da bancada de refeições e trabalho', 'Área de descanso com tecidos claros e cortina de extensão contínua', 'Banheiro com superfícies cinza-claras e box transparente']::text[],
      seo_title = 'ID Home & Lifestyle Paraíso | Estúdio integrado',
      seo_description = 'Proposta de estúdio no Paraíso com cozinha linear, marcenaria amadeirada e bancada para refeições ou trabalho diante da área de descanso.',
      cover_alt = 'Banheiro com cuba branca sobre bancada clara, gabinete amadeirado aberto, espelho circular e revestimentos brancos.'
  WHERE slug = 'ga-id-home-lifestyle-paraiso'
