  UPDATE public.projects
  SET summary = 'A proposta para o Exalt Ibirapuera by EZ, na Vila Clementino, organiza cozinha, bancada de apoio e descanso em um ambiente aberto. A marcenaria alterna frentes claras e amadeiradas, enquanto o verde suave delimita a área da televisão e da mesa. Superfícies escuras pontuam a composição sem dominar o espaço.',
      intro = 'Nas visualizações, a cozinha ocupa uma das laterais do estúdio e se prolonga visualmente até a bancada com duas cadeiras. Entre esses usos, um armário alto de portas claras cria uma pausa na sequência de superfícies amadeiradas e concentra espaço de guarda. A cama fica no lado oposto, junto à cortina que cobre a abertura ao fundo. O piso de aparência amadeirada conecta os setores, enquanto o verde aparece em trechos verticais específicos. Essa distribuição permite reunir preparo de alimentos, refeições, trabalho e descanso sem inserir uma divisória entre cozinha e cama. A área do projeto é de 31,4 m². O custo de reforma registrado para este projeto é de R$ 3.853,50/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é acomodar atividades distintas ao longo de uma faixa de circulação compartilhada, evitando que cozinha, armazenamento e descanso disputem o mesmo plano visual. A presença da cama diante da marcenaria também pede equilíbrio entre volumes fechados, superfícies de apoio e elementos mais leves, como mesa e prateleira.',
      solution = 'O desenho concentra os armários superiores e o volume alto em acabamento claro, reservando o amadeirado às frentes inferiores, ao nicho do micro-ondas e aos apoios. A bancada preta pontilhada marca a área de preparo. Já a mesa com duas cadeiras oferece apoio para refeições ou trabalho sob a televisão. No banheiro, a proposta combina bancada clara pontilhada, gabinete amadeirado com nicho aberto e espelho amplo com iluminação junto à borda inferior.',
      result_text = 'As visualizações apresentam um estúdio com usos reconhecíveis pela posição do mobiliário e pelos contrastes de acabamento. O verde destaca a bancada multifuncional, as portas claras reduzem o peso visual do armário alto e a cortina estabelece um fundo contínuo para a área de descanso. Na locação por temporada, os armários junto à cozinha procuram concentrar os objetos onde serão utilizados. A intenção de investimento aparece na organização do espaço e na experiência de chegada do hóspede.',
      scope = ARRAY['Cozinha linear com bancada preta pontilhada e frentes inferiores amadeiradas', 'Armários superiores claros e nicho amadeirado para micro-ondas', 'Volume alto de portas claras entre cozinha e bancada de apoio', 'Bancada com duas cadeiras sob a televisão e prateleira superior', 'Verde suave na parede da televisão e no plano próximo à entrada', 'Área de descanso com cama e cortina clara ao fundo', 'Banheiro com bancada clara pontilhada, gabinete com nicho aberto e espelho iluminado']::text[],
      seo_title = 'Exalt Ibirapuera by EZ: estúdio na Vila Clementino',
      seo_description = 'Proposta de estúdio no Exalt Ibirapuera by EZ, na Vila Clementino, com cozinha linear, marcenaria clara e bancada para refeições ou trabalho.',
      cover_alt = 'Cozinha com armários inferiores amadeirados, módulos superiores claros, bancada preta e cama próxima à cortina branca.'
  WHERE slug = 'cr-exalt-ibirapuera-by-ez'
