  UPDATE public.projects
  SET summary = 'No Artesano Oscar Porto, no Paraíso, a proposta reúne cozinha linear, apoio de trabalho e descanso em um ambiente contínuo. Frentes grafite contrastam com superfícies amadeiradas, enquanto tecidos claros suavizam a área da cama. A marcenaria marca a passagem entre preparo e permanência sem fechar a perspectiva até a cortina.',
      intro = 'A vista de entrada apresenta a organização do estúdio: cozinha à direita, uma bancada com cadeiras na sequência e cama junto à cortina ao fundo. Essa disposição concentra os apoios em uma lateral e mantém um percurso contínuo até o descanso. Nas visualizações, o acabamento amadeirado aparece nos armários superiores, no painel junto à bancada e na cabeceira, conectando visualmente funções diferentes. O grafite fica mais presente na cozinha e em uma parede próxima ao sofá, enquanto roupa de cama, estofados e cortinas claros equilibram essas superfícies escuras. Dois quadros sobre a cama pontuam a composição sem disputar espaço com o mobiliário. A área do projeto é de 29,12 m². O custo de reforma registrado para este projeto é de R$ 2.163,46/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava aproximar preparo de alimentos, trabalho e descanso sem transformar todos os apoios em uma única superfície indiferenciada. Outro ponto era equilibrar os volumes altos da cozinha com a área da cama, onde cabeceira, sofá e mesas laterais compartilham uma mesma faixa do ambiente.',
      solution = 'A proposta distingue os usos pelo desenho da marcenaria: a cozinha recebe armários grafite sob uma bancada clara pontilhada, enquanto um painel amadeirado marca a transição para o tampo escuro com cadeiras, apoio possível para trabalho e refeições. Na área de descanso, a cabeceira horizontal reúne cama e luminárias laterais em uma composição baixa. No banheiro, o gabinete amadeirado e a bancada pontilhada retomam a linguagem da cozinha; o espelho redondo contrasta com as linhas retas do lavatório e do box transparente.',
      result_text = 'As visualizações mostram uma proposta em que a continuidade dos acabamentos aproxima os setores, mas cada apoio mantém sua função legível. O sofá ao lado da cama oferece uma alternativa para sentar, e a bancada lateral permite alternar atividades sem ocupar a superfície de descanso.',
      scope = ARRAY['Cozinha linear com frentes grafite e armários superiores amadeirados', 'Bancada clara pontilhada com cuba e cooktop', 'Painel amadeirado na transição entre cozinha e apoio de trabalho', 'Tampo escuro com cadeiras para trabalho e refeições', 'Cabeceira horizontal com luminárias nas laterais da cama', 'Sofá claro ao lado da área de descanso', 'Banheiro com gabinete amadeirado, espelho redondo e box transparente']::text[],
      seo_title = 'Artesano Oscar Porto: estúdio no Paraíso',
      seo_description = 'Proposta de interiores no Artesano Oscar Porto, no Paraíso, com cozinha grafite, marcenaria amadeirada e apoio de trabalho junto ao descanso.',
