  UPDATE public.projects
  SET summary = 'No Highlights Pinheiros, a proposta aproxima cama, estar e apoio para refeições em um ambiente de base clara. O terracota conecta a bancada junto à entrada à faixa de parede do descanso, enquanto a marcenaria concentra roupas, eletrodomésticos e utensílios. Detalhes pretos recortam essa composição sem dominar o espaço.',
      intro = 'O desenho do estúdio em Pinheiros organiza a rotina em duas frentes: de um lado, cama, estofado e bancada com duas cadeiras; do outro, televisão, guarda de roupas e cozinha. Essa disposição mantém uma passagem longitudinal entre os móveis. O piso de aparência amadeirada clara aproxima visualmente os setores, enquanto o terracota marca superfícies de apoio e a altura da cabeceira. Nas visualizações, cortinas enquadram a abertura para a varanda e permitem resguardar o interior em relação ao exterior. Já entre estar e dormir, a proposta assume a continuidade espacial, sem apresentar uma divisória. A área do projeto é de 35,15 m². O custo de reforma registrado para este projeto é de R$ 2.133,71/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio do desenho é acomodar preparo de alimentos, roupas e descanso em um mesmo campo visual, sem tornar todos os elementos igualmente presentes. A proximidade entre cama e estofado também pede apoios bem posicionados, para que o mobiliário de uso cotidiano não interrompa a passagem central.',
      solution = 'A marcenaria reúne cabideiro, gavetas e prateleiras ao lado da geladeira, concentrando a guarda numa frente contínua. Na cozinha, o tampo escuro contrasta com os módulos claros e as gavetas terracota. Junto à entrada, a bancada com duas cadeiras serve a refeições e pode apoiar trabalho pontual. Perto da cama, uma mesa lateral pequena e a arandela oferecem apoio e luz localizada; na parede oposta, prateleiras estreitas acompanham a televisão sem criar volumes profundos.',
      result_text = 'As visualizações apresentam uma moradia em que os usos permanecem próximos, mas reconhecíveis pelo mobiliário. A repetição do terracota dá unidade ao percurso, enquanto superfícies claras equilibram os contrastes. Espelho, iluminação sob prateleiras e abertura para a varanda acrescentam profundidade à composição.',
      scope = ARRAY['Bancada terracota com duas cadeiras junto à entrada', 'Marcenaria com cabideiro, gavetas e nichos ao lado da geladeira', 'Cozinha com tampo escuro e prateleiras abertas', 'Estofado cinza junto à cama, mostrado também em configuração estendida', 'Faixa terracota na cabeceira e na parede da televisão', 'Espelho vertical e prateleiras estreitas na frente da cama', 'Cortinas na abertura para a varanda com mesa e assentos']::text[],
      seo_title = 'Highlights Pinheiros: interiores em terracota e tons claros',
