  UPDATE public.projects
  SET summary = 'A proposta para o estúdio no Level Brooklin, em Santo Amaro, combina paredes verde-oliva, volumes claros e superfícies amadeiradas. Cozinha linear e bancada de trabalho ocupam a faixa próxima à entrada, enquanto cama e sofá compartilham o ambiente junto à varanda, onde uma mesa redonda oferece outro apoio para refeições.',
      intro = 'Nas visualizações do Level Brooklin, o verde-oliva aparece em trechos definidos: atrás da bancada de trabalho, no plano da televisão e na parede do banheiro. Essa repetição conecta os ambientes sem tornar todas as superfícies iguais. Armários de frentes claras contrastam suavemente com o verde, enquanto a cabeceira e os apoios amadeirados acrescentam variação à paleta. A cama fica próxima à abertura da varanda, acompanhada por cortinas claras. Em frente, o pequeno sofá ocupa o intervalo entre dois volumes altos de marcenaria, com a televisão acima e uma prateleira que completa a composição. A área do projeto é de 27,48 m². O custo de reforma registrado para este projeto é de R$ 2.256,19/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa acomodar preparo de alimentos, trabalho, guarda e descanso em um ambiente compartilhado, sem tratar todos os usos como um único bloco. A proximidade entre cama e sofá também pede uma composição que organize os volumes ao redor e mantenha reconhecível o percurso entre entrada e varanda.',
      solution = 'A planta apresenta a cozinha encostada em uma lateral e a bancada com duas cadeiras na parede oposta, deixando a faixa intermediária para passagem. Próximo à cama, a cabeceira amadeirada reúne visualmente os apoios laterais. Os armários altos ladeiam o sofá e concentram a guarda em volumes verticais. Na varanda, mesa e cadeiras estabelecem um apoio separado para refeições. O banheiro retoma o verde-oliva, combinado à bancada pontilhada, ao espelho de contorno arredondado e ao gabinete com prateleiras abertas.',
      result_text = 'O conjunto proposto diferencia os usos pela posição do mobiliário e pelos planos de cor, sem inserir uma divisória entre estar e descanso. A bancada interna e a mesa da varanda oferecem apoios distintos, permitindo alternar trabalho e refeições sem depender da área da cama. O verde suave diferencia a cozinha sem romper a relação com o descanso. Para locação, essa escolha busca dar identidade às fotografias do anúncio e preservar uma atmosfera acolhedora para o hóspede.',
      scope = ARRAY['Cozinha linear junto à entrada, com bancada de aparência pontilhada', 'Bancada amadeirada para trabalho com duas cadeiras e armário superior aberto', 'Cabeceira amadeirada com apoios laterais', 'Sofá entre armários altos de frentes claras', 'Parede verde-oliva com televisão e prateleira acima do sofá', 'Mesa redonda com cadeiras na varanda', 'Banheiro com espelho arredondado, gabinete aberto e box transparente']::text[],
      seo_title = 'Level Brooklin: interiores em verde oliva | Santo Amaro',
      seo_description = 'Conheça a proposta para o Level Brooklin, em Santo Amaro: verde oliva, marcenaria clara, bancada de trabalho e mesa de refeições na varanda.',
      cover_alt = 'Cama diante de cabeceira amadeirada, armários brancos e cortinas claras, com cozinha de detalhes verdes ao lado.'
  WHERE slug = 'mc-level-brooklin'
