  UPDATE public.projects
  SET summary = 'A proposta para o Casa Ibirapuera Cyrela, na Vila Clementino, organiza cozinha, descanso e uma bancada de uso duplo ao longo de uma circulação central. O contraste entre superfícies amadeiradas, frentes cinza e uma parede com aparência de tijolinhos dá identidade ao estúdio, enquanto armários e prateleiras distribuem os espaços de armazenamento.',
      intro = 'Nas visualizações, a cozinha ocupa a lateral da entrada e conduz o olhar até a cama e o fechamento transparente ao fundo. Do lado oposto ao descanso, uma bancada escura acomoda duas cadeiras e se prolonga sobre um gabinete sob a televisão. Essa continuidade aproxima refeição, trabalho e apoio sem acrescentar uma mesa no centro do ambiente. O piso amadeirado percorre o estúdio, enquanto os armários superiores da cozinha retomam sua tonalidade. Já as frentes grafite e cinza estabelecem uma base mais sóbria, equilibrada pelas paredes claras e pela roupa de cama branca. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 2.551,14/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio do desenho é acomodar preparo de alimentos, refeições, trabalho e descanso em um ambiente estreito, preservando a passagem entre a entrada e o fundo. A parede texturizada também exige equilíbrio: sua presença marcante precisa conviver com os volumes de armazenamento sem tornar toda a composição visualmente pesada.',
      solution = 'A proposta concentra os móveis nas laterais e deixa o eixo central para circulação. Na cozinha, o tampo claro pontilhado contrasta com as portas escuras, e o nicho do micro-ondas mantém o equipamento fora da superfície de preparo. A bancada para duas pessoas oferece apoio para refeições ou trabalho. Acima da televisão, prateleiras abertas com perfis pretos e iluminação linear destacam a textura da parede sem acrescentar outro volume fechado.',
      result_text = 'O resultado proposto combina usos próximos, mas reconhecíveis: cozinha na entrada, bancada diante da cama e descanso junto ao fechamento transparente. A repetição do amadeirado e dos detalhes escuros conecta essas partes, enquanto o caminho central permanece desimpedido nas visualizações. A televisão articulada e a cozinha linear compartilham a mesma área de circulação. Na locação por temporada, o projeto procura reunir esses usos para oferecer ao hóspede apoios acessíveis em um espaço compacto.',
      scope = ARRAY['Cozinha linear com tampo claro pontilhado e frentes grafite', 'Armários superiores amadeirados com nicho para micro-ondas', 'Bancada escura para duas pessoas, com apoio para refeição e trabalho', 'Gabinete cinza sob a televisão', 'Parede com aparência de tijolinhos e prateleiras abertas iluminadas', 'Área de descanso com cama voltada para a televisão', 'Circulação central com piso amadeirado e trilho de iluminação']::text[],
      seo_title = 'Casa Ibirapuera Cyrela | Estúdio na Vila Clementino',
      seo_description = 'Proposta de estúdio na Vila Clementino com cozinha linear, bancada para refeições e trabalho, marcenaria cinza e parede com aparência de tijolinhos.',
      cover_alt = 'Cozinha linear com armários escuros e amadeirados, bancada clara e televisão articulada voltada para o ambiente integrado.'
  WHERE slug = 'vv-casa-ibirapuera-cyrela'
