  UPDATE public.projects
  SET summary = 'A proposta para o Galleria SP, na República, organiza cozinha, descanso e uma bancada com dois lugares ao longo de uma circulação central. Superfícies amadeiradas aproximam os diferentes usos, enquanto frentes escuras e detalhes pretos criam contraste. Armários altos enquadram a bancada diante da cama, concentrando armazenamento e apoio.',
      intro = 'Nas visualizações do Galleria SP, a entrada revela a cozinha à direita e a cama mais ao fundo, junto à abertura para a varanda. O piso de aparência amadeirada acompanha esse percurso e encontra acabamento semelhante nos armários, dando continuidade visual ao ambiente. Em frente à cama, uma bancada escura com duas cadeiras fica sob a televisão e uma prateleira. Essa composição oferece apoio para trabalho ou refeições sem acrescentar uma mesa no centro. As cortinas claras delimitam a abertura ao fundo, enquanto os tecidos brancos e cinza da cama equilibram a presença dos volumes amadeirados. A área do projeto é de 22 m². O custo de reforma registrado para este projeto é de R$ 2.795,45/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava aproximar preparo de alimentos, apoio para atividades e descanso sem ocupar a passagem até a varanda. Outro ponto era acomodar volumes de armazenamento na mesma perspectiva da cama, evitando que todos os elementos tivessem o mesmo peso visual em um ambiente aberto.',
      solution = 'A marcenaria se distribui pela lateral da cozinha e enquadra a bancada com dois lugares entre armários altos. O contraste entre acabamento amadeirado e superfícies escuras diferencia volumes de guarda e planos de apoio. Na cozinha, a bancada pontilhada reúne cuba e cooktop, com micro-ondas em nicho inferior. No banheiro, o desenho retoma o pontilhado da bancada e o gabinete amadeirado, combinados a paredes de aparência mineral e espelho de contorno arredondado.',
      result_text = 'As visualizações apresentam uma composição em que o centro permanece destinado à passagem, e as funções se concentram nas laterais. A repetição do amadeirado conecta cozinha e área de descanso; a bancada sob a televisão acrescenta dois lugares de apoio sem interromper esse percurso. O micro-ondas integrado sob a marcenaria e a bancada com cuba e cooktop concentram o preparo. Na hospedagem, essa organização procura oferecer uma cozinha compreensível sem ocupar os apoios destinados aos demais usos.',
      scope = ARRAY['Cozinha linear com bancada pontilhada, cuba e cooktop', 'Nicho inferior para micro-ondas na marcenaria da cozinha', 'Bancada escura com duas cadeiras sob a televisão', 'Armários altos amadeirados nas laterais da bancada', 'Prateleira acima da televisão para objetos e vegetação', 'Cama junto à abertura da varanda com cortinas claras', 'Espelho vertical de contorno arredondado na entrada', 'Banheiro com gabinete amadeirado e espelho arredondado']::text[],
      seo_title = 'Galleria SP na República | Marcenaria e integração',
      seo_description = 'Proposta de interiores no Galleria SP, na República, com cozinha linear, bancada para dois e marcenaria amadeirada conectando os usos.',
      cover_alt = 'Cozinha amadeirada com armários superiores escuros, geladeira prateada e televisão voltada para a cama no ambiente integrado.'
  WHERE slug = 'lc-galleria-sp'
