  UPDATE public.projects
  SET summary = 'A proposta para o Composite Moema aproxima cozinha, refeições e estar em uma composição de cinza, verde e superfícies amadeiradas. A mesa redonda com banco encostado à parede concentra o jantar, enquanto o sofá voltado à televisão define o descanso. Prateleiras abertas e armários fechados distribuem exposição e armazenamento.',
      intro = 'Nas visualizações do Composite Moema, a área social reúne usos cotidianos sem recorrer a divisórias entre cozinha, jantar e estar. O piso amadeirado acompanha todo esse espaço, criando continuidade sob os móveis. Sobre essa base, os armários cinza e as paredes claras deixam o verde do sofá marcar a área de descanso. As cadeiras com estampa pied-de-poule acrescentam contraste em preto e branco junto à mesa redonda. O banco de tom caramelo ocupa a lateral da composição e oferece assentos para as refeições sem exigir outra fileira de cadeiras junto à parede. A área do projeto é de 38,53 m². O custo de reforma registrado para este projeto é de R$ 2.206,07/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é aproximar a mesa da cozinha sem fazer do estar uma extensão da área de preparo. Também é preciso distribuir apoios e armazenamento sem carregar as paredes com volumes fechados. O desenho enfrenta essas questões com posições distintas para jantar e descanso e uma alternância entre armários baixos e prateleiras.',
      solution = 'A bancada escura delimita o preparo, acompanhada por armários inferiores cinza. Acima, prateleiras amadeiradas com iluminação linear destacam objetos sobre o revestimento branco de pequenas peças retangulares. O pendente marca a mesa de refeições, enquanto o móvel baixo sob a televisão oferece apoio sem ocupar toda a parede. No banheiro, a proposta retoma a bancada escura e o gabinete amadeirado; superfícies claras e o fechamento transparente do box mantêm visíveis os limites do ambiente.',
      result_text = 'O resultado proposto é uma área social em que a posição dos móveis distingue preparo, refeições e descanso. Cinza e amadeirado conectam os ambientes, enquanto o sofá verde e as cadeiras estampadas criam pontos de contraste sem depender de divisórias.',
      scope = ARRAY['Cozinha com bancada escura e armários inferiores cinza', 'Prateleiras amadeiradas iluminadas sobre revestimento branco retangular', 'Mesa redonda com banco caramelo e cadeiras pied-de-poule', 'Estar com sofá verde voltado à televisão', 'Móvel baixo amadeirado com compartimentos sob a TV', 'Pendente sobre a mesa e iluminação linear no teto', 'Banheiro com bancada escura, gabinete amadeirado e box transparente']::text[],
      seo_title = 'Composite Moema: cozinha, jantar e estar integrados',
