  UPDATE public.projects
  SET summary = 'A proposta para o Metrocasa República organiza cozinha, descanso e trabalho em torno de uma faixa central de circulação. A bancada acompanha a parede inclinada junto à janela, enquanto a marcenaria junto à cabeceira diferencia os usos. Superfícies claras e amadeiradas recebem contrapontos pretos nas bancadas, cadeiras e molduras dos espelhos.',
      intro = 'No bairro República, o projeto apresentado nas visualizações responde a um perímetro com uma parede inclinada, aproveitada para posicionar uma bancada com duas cadeiras. Na planta 3D, esse apoio fica próximo à janela e separado da cama por um conjunto de marcenaria junto à cabeceira. A cozinha ocupa uma frente linear ao lado do banheiro, deixando o centro desimpedido para conectar os diferentes setores. O piso de aparência amadeirada aproxima visualmente cozinha, bancada e descanso, enquanto as paredes claras mantêm uma base contínua para os volumes de armazenamento e os elementos escuros. A área do projeto é de 17 m². O custo de reforma registrado para este projeto é de R$ 4.201,88/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar a cama, os apoios de trabalho e os equipamentos da cozinha sem transformar o percurso central em uma passagem entre obstáculos. A parede inclinada também exigia uma disposição específica do mobiliário. Outro ponto era distinguir a área de descanso sem fechar a relação com a bancada próxima.',
      solution = 'A proposta posiciona a bancada no trecho inclinado e usa a marcenaria atrás da cabeceira como separação parcial. Na cozinha, armários superiores claros contrastam com frentes inferiores amadeiradas; a bancada preta marca o plano de preparo, e uma prateleira recebe o micro-ondas. Nichos e compartimentos fechados oferecem formas distintas de armazenamento. No banheiro, o desenho retoma a bancada escura e o gabinete amadeirado, com espelho de contorno arredondado e divisória transparente no box.',
      result_text = 'As visualizações mostram uma organização em que o mobiliário acompanha as particularidades do perímetro, em vez de ocupar o centro. A repetição de amadeirados, planos claros e detalhes pretos conecta os setores, enquanto a marcenaria da cabeceira estabelece um limite entre trabalho e descanso. Os dois lugares de apoio junto à janela aproveitam um trecho singular da planta. Para a hospedagem, essa bancada acrescenta possibilidades de refeição e trabalho, enquanto a cabeceira diferencia o lugar de descanso.',
      scope = ARRAY['Bancada com duas cadeiras junto à parede inclinada e à janela', 'Marcenaria junto à cabeceira como separação parcial de usos', 'Cozinha linear com bancada preta e frentes inferiores amadeiradas', 'Armários superiores claros e prateleira para micro-ondas', 'Televisão em frente à cama e pequeno apoio suspenso', 'Espelho vertical de contorno arredondado próximo à entrada', 'Banheiro com gabinete amadeirado, bancada escura e box transparente']::text[],
      seo_title = 'Metrocasa República: cozinha, descanso e trabalho',
      seo_description = 'Conheça a proposta do Metrocasa República, com cozinha linear, bancada junto à janela e marcenaria que diferencia trabalho e descanso.',
      cover_alt = 'Planta 3D de apartamento com cama, cozinha, banheiro e área de estar, mostrando a distribuição compacta dos ambientes.'
  WHERE slug = 'cp-metrocasa-republica'
