  UPDATE public.projects
  SET summary = 'A proposta para o ZIP Brooklin reúne cozinha linear, área de descanso e bancada com dois assentos em um ambiente contínuo. A marcenaria amadeirada aproxima os diferentes usos, enquanto a superfície escura da cozinha delimita o preparo. Portas claras e tecidos neutros equilibram a presença dos armários.',
      intro = 'Nas visualizações do ZIP Brooklin, a cozinha acompanha uma das laterais e conduz o olhar até a abertura envidraçada ao fundo. A cama ocupa o lado oposto ao pequeno sofá, mantendo uma faixa de passagem entre os volumes. Junto à cama, uma bancada amadeirada com duas cadeiras oferece apoio para trabalho ou refeições, sem acrescentar uma mesa solta ao centro. O desenho combina frentes lisas claras, padrões amadeirados e detalhes pretos. Essa distribuição de cores deixa os volumes maiores visualmente próximos das paredes e concentra o contraste nos puxadores, nas cadeiras e na bancada da cozinha. A área do projeto é de 28,4 m². O custo de reforma registrado para este projeto é de R$ 2.288,73/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial está em aproximar preparo, apoio de mesa e descanso sem sobrepor suas áreas de uso. Como cama e sofá compartilham o mesmo ambiente, a proposta precisa acomodar também os volumes de guarda e manter legível o percurso entre a entrada e a abertura ao fundo.',
      solution = 'O desenho concentra cuba e cooktop na bancada escura de aparência pontilhada, com armários inferiores e superiores para organizar esse trecho. Um armário alto amadeirado marca a transição entre cozinha e sofá. Na parede oposta, a cabeceira acompanha a cama, enquanto a bancada com duas cadeiras fica encostada à parede. Prateleiras elevadas acrescentam apoios sem ocupar a passagem, e cortinas claras emolduram a abertura envidraçada.',
      result_text = 'As visualizações apresentam uma composição em que os móveis definem os usos sem divisórias entre cozinha e descanso. A repetição do amadeirado conecta armários, cabeceira e bancada, enquanto os elementos escuros pontuam superfícies de apoio e detalhes, evitando um conjunto inteiramente uniforme. A posição do micro-ondas na marcenaria superior preserva a bancada para o preparo. Para a hospedagem, a cozinha reúne funções em uma leitura direta e deixa os apoios de trabalho livres para o uso cotidiano.',
      scope = ARRAY['Cozinha linear com cuba e cooktop sobre bancada escura pontilhada', 'Armários superiores claros com nicho para micro-ondas', 'Armário alto amadeirado entre cozinha e sofá', 'Bancada junto à parede com duas cadeiras pretas', 'Cabeceira amadeirada e composição de tecidos claros na cama', 'Pequeno sofá com mesa lateral redonda junto à abertura', 'Cortinas claras e faixa de cor no alto das paredes']::text[],
      seo_title = 'ZIP Brooklin: cozinha linear e marcenaria amadeirada',
      seo_description = 'Conheça a proposta do ZIP Brooklin: cozinha linear, bancada com dois assentos e área de descanso conectadas pela marcenaria amadeirada.',
      cover_alt = 'Cozinha de armários amadeirados e superiores claros, bancada preta, geladeira prateada e cama no fundo do ambiente.'
  WHERE slug = 'df-zip-brooklin'
