  UPDATE public.projects
  SET summary = 'A proposta do Single Living organiza cozinha, apoio para refeições e trabalho, guarda de roupas e descanso em torno de uma passagem contínua. Tons amadeirados aproximam piso e mobiliário, enquanto superfícies claras equilibram a parede cinza. A marcenaria intercala volumes altos e nichos, dando lugar a cada função sem criar divisórias entre elas.',
      intro = 'Nas visualizações, a cozinha aparece junto ao acesso, com bancada pontilhada, frentes amadeiradas e prateleiras abertas sobre o revestimento branco retangular. A geladeira marca a transição para uma mesa de duas posições, instalada sob a televisão e voltada para a cama. Os volumes altos de marcenaria enquadram esse apoio e concentram a guarda nas laterais. Mais adiante, o sofá de dois módulos ocupa a mesma faixa de mobiliário, diante da abertura envidraçada. O piso de aparência amadeirada percorre o ambiente, enquanto a cama mantém seu lugar na lateral oposta, sem uma divisória opaca que interrompa a vista até o fundo. A área do projeto é de 21,3 m². O custo de reforma registrado para este projeto é de R$ 3.617,23/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta está em aproximar preparo de alimentos, refeições, trabalho e descanso sem transformar a passagem em área de mobiliário. Também é necessário acomodar peças de alturas distintas — geladeira, armários, mesa e sofá — numa mesma lateral, evitando que essa sequência pareça uma soma de volumes desconectados.',
      solution = 'O desenho reúne bancada e prateleiras na cozinha e reserva um nicho central para a mesa, com duas cadeiras e televisão acima. A vista com os armários abertos revela prateleiras e espaço para cabides, explicitando a função de guarda dos volumes altos. Frentes claras reduzem o contraste desses armários com o entorno; já cadeiras, puxadores e trilho pretos pontuam a composição. Na parede oposta, o espelho vertical de cantos arredondados oferece uma superfície de reflexão junto à cama.',
      result_text = 'As visualizações apresentam uma organização em que os móveis delimitam os usos, sem separar cozinha, mesa e cama por paredes. A sequência de apoios deixa uma passagem legível até a abertura ao fundo, e os estofados claros contrastam com a parede cinza atrás do sofá. As prateleiras de madeira deixam alguns utensílios à vista e aproximam a cozinha de uma escala doméstica. Na locação, a proposta busca acolher o visitante com uma composição clara dos elementos de preparo.',
      scope = ARRAY['Cozinha linear com bancada pontilhada e revestimento branco retangular', 'Prateleiras amadeiradas para utensílios e pequenos objetos', 'Mesa de duas posições sob a televisão', 'Armários altos com prateleiras e espaço para cabides', 'Composição da cama com espelho vertical de cantos arredondados', 'Sofá de dois módulos junto à abertura envidraçada', 'Iluminação proposta com spots em trilho preto']::text[],
      seo_title = 'Single Living: cozinha, mesa e descanso integrados',
      seo_description = 'Conheça a proposta do Single Living, com cozinha linear, mesa para duas pessoas e marcenaria que organiza guarda e descanso em tons claros.',
      cover_alt = 'Cozinha compacta de armários amadeirados, bancada clara com padrão granulado, nichos abertos e geladeira prateada.'
  WHERE slug = 'gf-pjm-single-living'
