  UPDATE public.projects
  SET summary = 'No Exalt Ibirapuera, na Vila Clementino, a proposta organiza cozinha, guarda de roupas e descanso em torno de uma passagem contínua. Armários brancos equilibram as superfícies pretas, enquanto o piso e a cabeceira amadeirados aproximam visualmente os setores. Ao fundo, banco em L, mesa redonda e bancada de trabalho oferecem apoios distintos.',
      intro = 'As visualizações apresentam um estúdio cuja organização pode ser entendida desde a entrada: a cozinha ocupa a lateral esquerda, seguida por um volume alto de armários, enquanto a cama fica à direita. A passagem entre esses elementos conduz à mesa junto às janelas, sem atravessar a área de preparo. O preto aparece nas bases da cozinha, nos puxadores e na faixa acima da cabeceira, criando continuidade entre peças de funções diferentes. Em contraponto, portas brancas e paredes claras reduzem o peso visual dos volumes altos. O desenho amadeirado do piso reaparece atrás da cama e do pequeno sofá. A área do projeto é de 29,86 m². O custo de reforma registrado para este projeto é de R$ 2.563,29/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio espacial é reunir preparo de alimentos, armazenamento, descanso, refeições e trabalho sem sobrepor seus apoios. Como a cama permanece aberta para o restante do ambiente, a proposta precisa distinguir os setores pelo posicionamento dos móveis e pela composição visual, sem sugerir uma privacidade que o desenho não oferece.',
      solution = 'A marcenaria concentra prateleiras, cabideiros e um compartimento estreito para utensílios de limpeza na mesma lateral da cozinha. Junto às janelas, o banco em L acomoda assentos ao redor da mesa redonda, enquanto uma bancada separada recebe a cadeira de trabalho. A TV suspensa dispensa um móvel de piso diante da cama. No banheiro, a bancada clara de aparência pontilhada contrasta com os nichos escuros para toalhas; o espelho redondo interrompe a predominância de linhas retas.',
      result_text = 'A proposta estabelece uma sequência legível de usos, com armazenamento concentrado de um lado e descanso do outro. Refeições e trabalho têm superfícies próprias, e a repetição de branco, preto e amadeirado conecta os setores sem apagar suas diferenças funcionais. O contraste entre armários claros e bancada escura evidencia o espaço de preparo. Na locação, a intenção é oferecer ao hóspede um ambiente compreensível, com lugar para refeições e descanso dentro da área integrada.',
      scope = ARRAY['Cozinha linear com bases pretas, armários superiores brancos e revestimento retangular cinza', 'Armário alto com cabideiros, prateleiras e compartimento para utensílios de limpeza', 'Cabeceira amadeirada contínua junto à cama e ao pequeno sofá', 'Banco estofado em L com mesa redonda e cadeira', 'Bancada de trabalho junto às janelas', 'TV em suporte suspenso diante da cama', 'Banheiro com bancada pontilhada, nichos abertos e espelho redondo']::text[],
      seo_title = 'Exalt Ibirapuera: interiores na Vila Clementino',
      seo_description = 'Proposta para o Exalt Ibirapuera, na Vila Clementino, com cozinha bicolor, armário alto, banco em L e apoios separados para refeições e trabalho.',
      cover_alt = 'Cozinha com armários brancos e inferiores escuros, bancada preta, geladeira prateada e passagem para a área de descanso.'
