  UPDATE public.projects
  SET summary = 'A proposta para o Urban Flex, na Consolação, organiza cozinha, apoios de trabalho e refeição e área de descanso em uma sequência contínua. O contraste entre superfícies grafite e painéis amadeirados distingue os usos, enquanto a marcenaria concentra armazenamento e libera a passagem entre a entrada e a janela.',
      intro = 'Nas visualizações do Urban Flex, a cozinha ocupa uma das laterais do acesso, com armários cinza, bancada escura pontilhada e revestimento preto de peças retangulares. O piso de aparência amadeirada clara conduz até a cama, posicionada junto à janela com cortinas. Nesse trecho, o mesmo tom amadeirado aparece na cabeceira e no painel oposto, que reúne televisão, prateleira e bancada de trabalho. A repetição aproxima visualmente essas duas faces, enquanto os tecidos claros da cama e da cortina equilibram a presença das superfícies escuras. A área do projeto é de 18 m². O custo de reforma registrado para este projeto é de R$ 3.903,00/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial perceptível é acomodar preparo de alimentos, refeições, trabalho, guarda de roupas e descanso sem interromper o percurso longitudinal. Como a cama compartilha o ambiente com os demais usos, o desenho precisa distinguir seus apoios e estabelecer limites visuais sem recorrer a um fechamento completo.',
      solution = 'A proposta concentra pia e cooktop na bancada linear da cozinha, com prateleira iluminada e armários superiores. Mais adiante, uma mesa redonda oferece apoio para refeições, separado da bancada estreita sob a televisão. Ao lado da cama, um painel amadeirado marca a transição desde o acesso e recebe arara aberta, prateleira alta e gavetas. A iluminação linear sob a prateleira da cozinha destaca a superfície de preparo; na cabeceira, delineia o encontro entre o painel e a parede clara.',
      result_text = 'As visualizações apresentam uma organização em que cada atividade encontra um apoio identificável, sem perder a continuidade do ambiente. A cozinha escura marca o acesso, enquanto os planos amadeirados e os tecidos claros deslocam o foco visual para a área de descanso. O revestimento horizontal escuro e os armários cinza dão profundidade à cozinha. Para a locação, a proposta busca equilibrar essa presença com os planos mais leves de descanso e uma apresentação coesa do interior.',
      scope = ARRAY['Cozinha linear com pia, cooktop e armários cinza', 'Revestimento preto de peças retangulares sobre a bancada', 'Painel amadeirado com televisão e bancada de trabalho', 'Mesa redonda com cadeiras para refeições', 'Arara aberta com prateleira alta e gavetas junto à cama', 'Cabeceira amadeirada com iluminação linear', 'Espelho vertical na circulação de entrada']::text[],
      seo_title = 'Urban Flex na Consolação: interiores em grafite e amadeirado',
      seo_description = 'Conheça a proposta do Urban Flex, na Consolação: cozinha linear, bancada de trabalho e área de descanso conectadas pela marcenaria amadeirada.',
      cover_alt = 'Cozinha em tons cinza com bancada escura, armários altos, passagem amadeirada e bancada de refeições ao fundo.'
  WHERE slug = 'cm-urban-flex'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'f98cbdeaee798d26732580ebe2e62252';
