  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'cm-urban-flex';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta do Urban Flex na Consolação organiza 18 m² para locação com uma frente de marcenaria que reúne cozinha, armazenamento e apoio sob a televisão. Nos renders, o verde suave dos armários se combina com superfícies amadeiradas e cadeiras em tom terracota. A composição procura dar identidade ao studio enquanto concentra suas funções nas paredes.',
      intro = 'O verde de aparência oliva acinzentada oferece uma base cromática contida para os volumes altos. Os planos amadeirados do painel, dos nichos e da cabeceira acrescentam calor visual, enquanto o terracota das cadeiras funciona como um acento próximo dessa família de tons quentes. As três cores se relacionam sem exigir que cada móvel receba o mesmo acabamento.

A bancada escura marca a cozinha, e as superfícies claras junto à cama deixam esse setor mais suave. O espelho alto de contorno arredondado retoma as linhas delicadas da composição. Como se trata de uma proposta em projeto, o valor é apresentado como custo de reforma informado: R$ 4.444,44/m².',
      challenge = 'Nesta área compacta, reservar espaço para cama, cozinha, roupas e uma superfície de refeições exige concentrar o mobiliário. Para locação, também é importante que o visitante compreenda facilmente como usar o studio. O desafio da proposta é distinguir os apoios cotidianos dentro de uma frente extensa de armários, evitando uma leitura inteiramente fechada.',
      solution = 'Os renders alternam portas, nichos e bancada, identificando os usos dentro do mesmo conjunto. O apoio sob a televisão recebe duas cadeiras e pode atender a refeições ou trabalho. A cabeceira organiza o lado oposto à marcenaria, e a cortina acompanha a abertura. A luz prevista junto aos móveis destaca planos específicos, aproximando a função de apoio da composição visual.',
      result_text = 'Para a futura locação, a intenção é reunir uma imagem reconhecível e apoios úteis em uma área pequena. O verde e os acentos terrosos podem compor a apresentação do anúncio, inclusive no Airbnb. Na proposta apresentada pelos renders, as funções permanecem reconhecíveis dentro da marcenaria contínua, permitindo que o conjunto mantenha personalidade mesmo com os objetos cotidianos guardados.',
      scope = ARRAY['Frente de marcenaria verde suave com armário alto entre cozinha e mesa', 'Nicho amadeirado da televisão com apoio para duas cadeiras', 'Cozinha proposta com bancada preta e micro-ondas embutido', 'Cabeceira de madeira diante de parede de aparência cimentícia', 'Espelho oval alto junto à área de descanso', 'Iluminação prevista em prateleiras e apoios laterais da cama', 'Banheiro em 3D com peças cinza, bancada escura e gabinete amadeirado']::text[],
      seo_title = 'Projeto de studio na Consolação — Urban Flex | Bewild',
      seo_description = 'Conheça o projeto 3D do Urban Flex na Consolação, com marcenaria verde suave, mesa para dois e cozinha integrada. Imóvel em projeto.',
      cover_alt = 'Planta 3D do Urban Flex na Consolação com cama junto à abertura, cozinha e armário na lateral e banheiro próximo à entrada.'
  WHERE slug = 'apsa2-urban-flex'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '36542f16c9f5f241a13050aebeb0cf4f';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'apsa2-urban-flex';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o High Line Tatuapé aproxima estar e jantar por meio de superfícies amadeiradas, estofados claros e elementos pretos. Uma bancada alta atrás do sofá acrescenta apoio sem fechar a sala, enquanto a varanda recebe uma mesa retangular. No dormitório, cabeceira e armário delimitam as áreas de descanso e guarda.',
      intro = 'Nas visualizações, a sala se organiza entre a mesa redonda, o sofá claro e a TV fixada diretamente na parede. O móvel baixo e a prateleira superior, ambos amadeirados, enquadram a tela sem revestir toda a superfície, mantendo o fundo claro aparente. Cadeiras, banquetas, esquadrias e trilho de iluminação repetem o preto em pontos distintos, criando contraste com o piso e os móveis de aparência amadeirada. Atrás do sofá, a bancada alta acompanha o limite do estar e oferece um segundo apoio para refeições. As cortinas claras suavizam visualmente as esquadrias e marcam a abertura voltada à varanda. A área do projeto é de 35 m². O custo de reforma registrado para este projeto é de R$ 3.000,00/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar mesa de jantar, apoio alto e estar em um espaço compartilhado, preservando o acesso à passagem lateral e à varanda. Outro ponto é estabelecer unidade entre esses ambientes sem apagar suas diferenças: a sala reúne assentos estofados e TV, enquanto a varanda concentra uma mesa maior e uma bancada de preparo.',
      solution = 'A mesa redonda reúne quatro cadeiras sem introduzir quinas junto ao estar. Já a bancada atrás do sofá usa o espaço sob o tampo para acomodar duas banquetas. Na varanda, a mesa retangular combina banco de um lado e cadeiras do outro, diante de armários amadeirados e bancada preta. No dormitório apresentado, a cabeceira horizontal contrasta com o volume alto do guarda-roupa de frentes claras; os pequenos apoios laterais atendem à cama sem acrescentar móveis volumosos.',
      result_text = 'As visualizações apresentam usos distintos conectados pela repetição do amadeirado e do preto. O mobiliário define os limites entre estar e refeições sem exigir uma divisória opaca, enquanto o dormitório concentra a guarda em um volume lateral e mantém a cama como foco. A bancada atrás do sofá cria um apoio adicional sem interromper a composição do estar. Para morar, a solução permite aproximar refeições, conversa e descanso em torno de uma atmosfera clara e acolhedora.',
      scope = ARRAY['Composição do estar com sofá claro, TV na parede e móvel baixo amadeirado', 'Bancada alta atrás do sofá com duas banquetas pretas', 'Mesa redonda de jantar com quatro cadeiras pretas', 'Trilho preto com spots sobre estar e jantar', 'Varanda com mesa retangular, banco e cadeiras', 'Bancada de preparo na varanda com armários amadeirados', 'Dormitório com cabeceira amadeirada, guarda-roupa claro e apoios laterais']::text[],
      seo_title = 'High Line Tatuapé | Amadeirados e contrastes em preto',
      seo_description = 'Conheça a proposta do High Line Tatuapé: estar e jantar conectados, bancada atrás do sofá, varanda com mesa e dormitório com marcenaria clara.',
      cover_alt = 'Sala com sofá claro, mesa redonda, bancada amadeirada com banquetas e cozinha compacta integrada ao espaço de estar.'
  WHERE slug = 'nl-high-line-tatuape'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '0e2d60d1cb9e1cf4d6ddaa0d1a697420';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'nl-high-line-tatuape';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o B.Side Faria Lima usa a marcenaria amadeirada como moldura da cozinha, combinando armazenamento fechado, nichos e uma bancada de aparência pontilhada. A mesa redonda aproxima refeições e estar, enquanto o quarto recebe armários junto à cama. Branco e bege equilibram a presença dos volumes amadeirados.',
      intro = 'Nas visualizações do B.Side Faria Lima, a cozinha ocupa uma faixa junto à entrada e se abre para a mesa e o sofá. Armários superiores e painéis laterais amadeirados delimitam esse trecho sem criar uma barreira diante do estar. Dentro dessa moldura, frentes brancas, prateleiras abertas e revestimento retangular claro dão destaque à bancada cinza pontilhada. A mesa branca acompanha a paleta e oferece apoio para refeições próximo ao preparo. Ao fundo, o sofá bege e as almofadas de diferentes texturas tornam a área de descanso visualmente distinta da cozinha. A área do projeto é de 30,36 m². O custo de reforma registrado para este projeto é de R$ 2.305,67/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial é acomodar preparo, armazenamento, refeições e estar em uma sequência estreita, sem transformar a cozinha em um volume visualmente pesado. No quarto, a proximidade entre cama e armário exige que a guarda de roupas e o apoio de cabeceira compartilhem a mesma lateral.',
      solution = 'O desenho concentra pia e cooktop em uma bancada linear, com nichos próximos à geladeira para micro-ondas e pequenos objetos. Os armários avançam até perto do teto, enquanto as frentes inferiores brancas suavizam a composição. A mesa redonda evita quinas na passagem entre cozinha e estar. No quarto, a marcenaria reúne um volume alto, um nicho junto à cabeceira e gavetas abaixo, oferecendo armazenamento e apoio ao alcance da cama sem acrescentar uma peça solta.',
      result_text = 'A proposta distingue os usos pela disposição do mobiliário e mantém continuidade pela paleta. O amadeirado marca os volumes de guarda; o branco conecta cozinha e refeições; e os tecidos claros concentram textura no sofá e na cama, sinalizando os espaços de descanso. A mesa redonda acrescenta um lugar de refeições entre a cozinha e o estar. Para a locação por temporada, esse apoio busca completar a experiência do hóspede e valorizar o uso do espaço disponível.',
      scope = ARRAY['Cozinha linear emoldurada por painéis e armários amadeirados', 'Bancada cinza pontilhada com pia e cooktop', 'Nichos brancos para micro-ondas e objetos de cozinha', 'Mesa redonda branca com cadeiras junto ao estar', 'Sofá bege com almofadas de texturas e padrões variados', 'Marcenaria lateral à cama com armário, nicho e gavetas', 'Trilho de iluminação ao longo do ambiente integrado']::text[],
      seo_title = 'B.Side Faria Lima: cozinha integrada e marcenaria',
      seo_description = 'Conheça a proposta do B.Side Faria Lima, com cozinha emoldurada por marcenaria, mesa redonda e armário com apoio de cabeceira no quarto.',
      cover_alt = 'Cozinha de armários claros envolvida por painéis amadeirados, mesa redonda branca, geladeira prateada e televisão lateral.'
  WHERE slug = 'rp-b-side-faria-lima'
