  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'rp-b-side-faria-lima';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o estúdio no Living Full Vila Nova Conceição combina marcenaria verde e amadeirada para aproximar cozinha, armazenamento e descanso. Uma mesa com duas cadeiras oferece apoio para refeições e trabalho, enquanto o percurso até a varanda permanece legível entre os móveis e a cama.',
      intro = 'Nas visualizações deste estúdio na Vila Nova Conceição, o verde aparece nos armários da cozinha, no volume que envolve a geladeira e na prateleira acima da televisão. Essa repetição conecta visualmente pontos distintos do ambiente, enquanto as superfícies amadeiradas da mesa, do armário alto e do piso equilibram a cor com tons mais claros. A cama recebe roupa branca e pequenos detalhes alaranjados, concentrando o contraste na área de descanso. Ao fundo, a porta envidraçada da varanda e as cortinas claras mantêm a abertura exterior como referência do percurso desde a entrada. A área do projeto é de 21,3 m². O custo de reforma registrado para este projeto é de R$ 3.051,64/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar preparo de alimentos, guarda, refeições, trabalho e descanso em um ambiente compartilhado, sem transformar a mesa em obstáculo à passagem. Outro desafio era inserir volumes altos de marcenaria sem dominar a composição, já que cozinha, armário e cama aparecem juntos em diferentes ângulos.',
      solution = 'A mesa amadeirada com duas cadeiras marca a transição entre cozinha e descanso sem recorrer a uma divisória fechada. O armário alto concentra a guarda em portas contínuas, junto à bancada da cozinha. Frentes verdes contrastam com o tampo cinza pontilhado e o revestimento branco retangular. Na parede diante da cama, a televisão suspensa dispensa um móvel de piso, e a prateleira superior recebe plantas e objetos.',
      result_text = 'O resultado proposto organiza os usos por meio do mobiliário, mantendo a continuidade visual do estúdio. A mesa permite alternar refeição e trabalho, enquanto a posição da televisão atende ao descanso e as superfícies claras contrabalançam os volumes verdes e amadeirados.',
      scope = ARRAY['Marcenaria verde na cozinha e no volume da geladeira', 'Armário alto com portas de aparência amadeirada', 'Mesa amadeirada com duas cadeiras para refeição e trabalho', 'Bancada cinza pontilhada com revestimento branco retangular', 'Televisão suspensa diante da cama e prateleira verde superior', 'Espelho vertical de contorno arredondado junto à área de descanso', 'Cortinas claras na abertura envidraçada para a varanda']::text[],
      seo_title = 'Living Full Vila Nova Conceição | Estúdio em verde',
      seo_description = 'Proposta de estúdio no Living Full Vila Nova Conceição com marcenaria verde e amadeirada, mesa para refeições e trabalho e conexão com a varanda.',
      cover_alt = 'Cozinha com armários verdes, bancada cinza de aspecto granulado e painel amadeirado junto à porta de vidro para a varanda.'
  WHERE slug = 'fc-living-full-vila-nova-conceicao'
