  UPDATE public.projects
  SET summary = 'A proposta para o estúdio no DO IT Faria Lima organiza cozinha, guarda de roupas e descanso ao longo de uma passagem central. Superfícies amadeiradas equilibram os volumes cinza, enquanto uma bancada com duas cadeiras reúne apoio para refeições e trabalho diante da cama, sem acrescentar uma mesa solta.',
      intro = 'Nas visualizações, a entrada revela a cozinha à direita e conduz o olhar até a abertura envidraçada junto à cama. O piso de aparência amadeirada acompanha esse percurso, retomando o tom dos armários da cozinha. Já os volumes altos em cinza marcam os setores de armazenamento e contrastam com paredes e cortinas claras. Na parede oposta à cama, a bancada comprida fica abaixo da televisão e de uma prateleira elevada. Essa disposição concentra os apoios na lateral e mantém a faixa central livre de mesas e outros móveis independentes. A área do projeto é de 29,69 m². O custo de reforma registrado para este projeto é de R$ 2.189,29/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava aproximar preparo de alimentos, refeições, trabalho e descanso sem preencher a passagem entre a entrada e a janela. Outro ponto era acomodar volumes altos para armazenamento sem tornar toda a composição escura, considerando a presença de cinza, preto e de uma faixa azul-acinzentada junto à cama.',
      solution = 'A proposta alterna frentes amadeiradas na cozinha com armários cinza de maior altura. O tampo preto pontilhado e o revestimento branco em peças retangulares delimitam a área da pia pelo contraste. A bancada lateral recebe duas cadeiras, permitindo alternar refeições e trabalho no mesmo apoio. Junto à entrada, o espelho vertical de contorno arredondado reflete a área de descanso. No banheiro, prateleiras sob a cuba oferecem apoio aberto, e o espelho assimétrico contrapõe as linhas retas do gabinete.',
      result_text = 'O projeto apresenta um estúdio com usos próximos, mas reconhecíveis pela posição do mobiliário e pelos contrastes de cor. A cozinha ocupa o acesso, os armários concentram a guarda e a cama fica junto à abertura, acompanhada por cortinas claras. O armário cinza junto à cama e os nichos da cozinha organizam atividades diferentes no mesmo interior. Na locação, essa disposição procura dar clareza ao uso do apartamento e acolher a rotina do hóspede.',
      scope = ARRAY['Cozinha linear com frentes amadeiradas e tampo preto pontilhado', 'Armários altos cinza para armazenamento e guarda de roupas', 'Bancada com duas cadeiras sob a televisão', 'Prateleira elevada sobre a bancada lateral', 'Parede bicolor com faixa azul-acinzentada junto à cama', 'Espelho vertical arredondado na entrada', 'Gabinete de banheiro com prateleiras abertas e espelho assimétrico']::text[],
      seo_title = 'DO IT Faria Lima | Estúdio em cinza e amadeirado',
      seo_description = 'Proposta de interiores no DO IT Faria Lima com cozinha linear, armários cinza e bancada para refeições e trabalho junto à área de descanso.',
      cover_alt = 'Passagem entre cozinha amadeirada e armários cinza, com bancada preta, espelho vertical e cama ao fundo do ambiente.'
  WHERE slug = 'fd-do-it-faria-lima'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '729d558066d6a6117b98c9d4e0913304';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'fd-do-it-faria-lima';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta em Vila Buarque organiza cozinha, refeições, trabalho e descanso em uma sequência aberta. O azul da entrada contrasta com superfícies amadeiradas e frentes pretas, enquanto a bancada pontilhada e o revestimento branco clareiam a cozinha. No espaço de descanso, o espelho do armário contrapõe a textura da parede atrás da mesa de trabalho.',
      intro = 'As visualizações apresentam um percurso que começa junto à parede azul e acompanha a cozinha linear até o espaço de descanso e a abertura para a varanda. Armários inferiores pretos dão uma base escura à bancada, enquanto os superiores amadeirados acomodam o micro-ondas e deixam utensílios e plantas em nichos abertos. O revestimento branco em peças retangulares ganha destaque sob a iluminação contínua. Mais adiante, a mesa redonda oferece apoio para refeições sem repetir o desenho alongado da cozinha. A cama e a bancada de trabalho ocupam lados opostos, com uma faixa de passagem entre elas. A área do projeto é de 29,4 m². O custo de reforma registrado para este projeto é de R$ 2.448,98/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é aproximar preparo de alimentos, refeições, trabalho e descanso sem tornar os apoios indistintos. A presença de volumes altos junto à passagem também pede equilíbrio visual: geladeira e armário precisam conviver com a cama, a mesa e o acesso à varanda sem interromper a leitura longitudinal do espaço.',
      solution = 'A proposta concentra o preparo de alimentos em uma lateral e posiciona a mesa redonda fora da bancada da cozinha. No trecho de descanso, a mesa preta fica sob a tela, reunindo trabalho e apoio de equipamentos na mesma parede. O armário combina frente espelhada e acabamento amadeirado: oferece guarda e reflete a cama, contrapondo uma superfície contínua à textura de tijolinhos. Cortinas claras enquadram a abertura, enquanto a prateleira iluminada destaca a parede atrás da tela.',
      result_text = 'Nas visualizações, a repetição do preto em cadeiras, bancada e luminárias conecta os diferentes usos. O piso amadeirado mantém a continuidade do percurso, e a varanda acrescenta um ponto de pausa com poltrona e vegetação, separado pela porta de correr. A madeira na marcenaria superior contrapõe os armários inferiores escuros e incorpora o micro-ondas ao conjunto. Para a locação, a cozinha procura transmitir organização e acolhimento desde a apresentação do anúncio.',
      scope = ARRAY['Cozinha linear com bancada pontilhada e armários inferiores pretos', 'Armários superiores amadeirados com nicho para micro-ondas', 'Parede azul junto à entrada', 'Mesa redonda como apoio para refeições', 'Bancada de trabalho sob a tela e prateleira iluminada', 'Armário com frente espelhada ao lado da cama', 'Iluminação sob os armários e pontos de luz no teto', 'Varanda com poltrona preta e vaso com vegetação']::text[],
      seo_title = 'Interiores em Vila Buarque | Azul e amadeirado',
      seo_description = 'Proposta em Vila Buarque reúne cozinha linear, mesa de refeições, bancada de trabalho e descanso, com azul, amadeirado e armário espelhado.',
      cover_alt = 'Cozinha de armários escuros, bancada cinza de aspecto granulado, nichos amadeirados e parede azulada junto à passagem.'
