  UPDATE public.projects
  SET summary = 'A proposta para o Pinheiros by Passarelli aproxima cozinha, refeições e estar em uma faixa contínua, enquanto reserva um ambiente separado para dormir. O verde suave acompanha o sofá claro, e a marcenaria amadeirada conecta os apoios da sala ao posto de trabalho junto à janela.',
      intro = 'Nas visualizações deste apartamento em Pinheiros, a cozinha ocupa uma das laterais do acesso, com armários brancos, puxadores pretos e bancada de aparência pontilhada. Na parede oposta, a mesa redonda branca fica próxima ao sofá, reunindo refeição e estar sem uma divisória entre eles. Ao fundo, a bancada de trabalho se posiciona junto à abertura envidraçada, acompanhada por cadeira giratória. O piso amadeirado estabelece continuidade entre essas áreas. Já o dormitório aparece separado na planta, com cama, apoios laterais e uma cabeceira que retoma os tons claros da marcenaria social. A área do projeto é de 28,91 m². O custo de reforma registrado para este projeto é de R$ 2.594,26/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar preparo de alimentos, refeições, estar e trabalho em um ambiente estreito, sem transformar todos os apoios em uma única superfície. Outra questão era distinguir esse espaço compartilhado do descanso no dormitório, mantendo uma relação visual entre os ambientes por meio das cores e dos acabamentos aparentes.',
      solution = 'A proposta distribui os móveis pelas laterais e concentra o trabalho junto à janela, deixando uma passagem longitudinal entre cozinha e estar. A mesa redonda oferece apoio para refeições, enquanto a bancada amadeirada recebe os objetos de trabalho. O verde suave diferencia a parede do sofá sem criar contraste forte com os estofados claros. No quarto, a cabeceira amadeirada reúne os apoios da cama, e a faixa de luz acima dela destaca a transição para a pintura em dois tons.',
      result_text = 'As visualizações apresentam usos próximos, mas com apoios distintos: mesa para refeições, bancada para trabalho e dormitório separado para descanso. A repetição do amadeirado e dos tons suaves aproxima os ambientes, enquanto puxadores, esquadrias e trilho pretos pontuam a composição clara. A mesa e os apoios de trabalho próximos à janela complementam a cozinha. Para locação por temporada, o projeto busca apresentar uma unidade que acolha tanto as refeições quanto pequenas tarefas do hóspede.',
      scope = ARRAY['Cozinha linear com armários brancos e bancada de aparência pontilhada', 'Mesa redonda branca próxima ao sofá', 'Parede verde suave como fundo do estar', 'Bancada de trabalho amadeirada junto à abertura envidraçada', 'Móvel baixo e prateleira amadeirados na área social', 'Cabeceira amadeirada com apoios laterais e faixa de luz', 'Trilho preto com spots na área integrada']::text[],
      seo_title = 'Pinheiros by Passarelli | Interiores em verde e amadeirado',
      seo_description = 'Conheça a proposta no Pinheiros by Passarelli: cozinha e estar integrados, bancada de trabalho junto à janela e dormitório separado.',
      cover_alt = 'Cozinha de armários brancos, bancada cinza com padrão granulado, geladeira prateada e mesa de refeições com cadeiras claras.'
  WHERE slug = 'ef-pinheiros-by-passarelli'
