  UPDATE public.projects
  SET summary = 'No Edifício Fortune Residence, em Cerqueira César, a proposta reúne cozinha, jantar e estar em uma área social de contorno irregular, mantendo o quarto separado. A parede terracota destaca a mesa de refeições, enquanto superfícies claras e amadeiradas dão continuidade ao ambiente. Bancadas escuras pontilhadas introduzem contraste na cozinha e no banheiro.',
      intro = 'A planta 3D mostra como o desenho acompanha as diagonais do apartamento: a cozinha ocupa uma das extremidades e sua bancada avança em direção ao jantar, oferecendo um segundo apoio para refeições. A mesa de contorno arredondado fica próxima à entrada, sem ocupar o eixo entre o sofá e a televisão. Junto ao estar, a varanda aparece com uma poltrona e vegetação. O quarto permanece em um setor separado, ao lado do banheiro, distinguindo o espaço de descanso dos ambientes de convivência e preservando sua privacidade. A área do projeto é de 44,57 m². O custo de reforma registrado para este projeto é de R$ 3.425,82/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio espacial sugerido pelas visualizações é acomodar os usos sociais dentro de um perímetro com paredes diagonais, sem espalhar o mobiliário pela circulação. Também era importante diferenciar jantar, preparo de alimentos e estar sem fechar esses ambientes, reservando ao quarto uma separação física em relação à área compartilhada.',
      solution = 'A proposta concentra os apoios da cozinha junto à parede e na bancada transversal, deixando o centro para circulação e refeições. No jantar, terracota, mesa escura e pendente preto formam um núcleo de contraste diante das superfícies claras. O painel amadeirado enquadra a passagem para o setor íntimo, ao lado do móvel baixo da televisão. No banheiro, o desenho combina tampo preto pontilhado, cuba branca e prateleiras abertas sob a bancada, mantendo os itens de apoio acessíveis.',
      result_text = 'As visualizações apresentam uma área social contínua, mas com usos reconhecíveis pela posição dos móveis e pelos contrastes de cor. O quarto separado resguarda o descanso, enquanto a repetição do amadeirado aproxima visualmente estar, circulação e banheiro. Na moradia, o dormitório delimitado na planta dá ao descanso um lugar próprio. A área comum reúne estar e refeições, procurando conciliar privacidade, convivência e aconchego sem dispersar os apoios cotidianos.',
      scope = ARRAY['Distribuição de cozinha, jantar e estar no perímetro diagonal', 'Bancada de cozinha com prolongamento para refeições e banquetas', 'Parede terracota no jantar com mesa escura e pendente preto', 'Painel amadeirado junto à passagem para o setor íntimo', 'Móvel baixo claro sob a televisão da sala', 'Quarto separado da área social', 'Bancada de banheiro pontilhada com prateleiras abertas', 'Varanda com poltrona e vegetação']::text[],
      seo_title = 'Edifício Fortune Residence em Cerqueira César | Interiores',
      seo_description = 'Proposta de interiores no Edifício Fortune Residence, em Cerqueira César, com área social integrada, parede terracota e quarto separado.',
      cover_alt = 'Planta 3D de apartamento com dormitório, banheiro, cozinha, mesa de refeições e sofá distribuídos em uma planta irregular.'
  WHERE slug = 'ps-edificio-fortune-residence'
