  UPDATE public.projects
  SET summary = 'A proposta para o Think Tanabi, em Perdizes, organiza cozinha, guarda, apoio para refeições ou trabalho e descanso ao longo de um ambiente estreito. A marcenaria alterna frentes amadeiradas e claras, enquanto detalhes pretos pontuam a composição. A passagem central mantém a conexão visual entre a entrada e a varanda.',
      intro = 'Nas visualizações do Think Tanabi, a cozinha ocupa a lateral próxima à entrada, seguida por um armário alto e uma bancada com duas cadeiras. Do lado oposto, a cama fica próxima à abertura para a varanda, com cortinas claras que permitem resguardar essa área. Essa distribuição aproxima funções sem inserir uma divisória entre a bancada e o descanso. O piso de aparência amadeirada acompanha o eixo de circulação, enquanto paredes e marcenaria claras formam um fundo contínuo. Geladeira escura, trilho de iluminação e molduras pretas introduzem contraste em pontos definidos. A área do projeto é de 29,4 m². O custo de reforma registrado para este projeto é de R$ 2.306,84/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio espacial sugerido pelas imagens é acomodar diferentes profundidades de mobiliário sem interromper a passagem até a varanda. A cozinha e o armário alto ocupam mais espaço junto à parede; adiante, a bancada rasa precisa oferecer apoio para duas pessoas e coexistir com a cama à frente.',
      solution = 'O desenho concentra os volumes de armazenamento em uma lateral e posiciona a bancada sob a televisão, reunindo apoio para refeições e trabalho no mesmo trecho. Uma prateleira acima da tela acrescenta espaço para objetos sem ocupar o tampo. Na entrada, o espelho de topo arredondado reflete essa composição. No banheiro, o gabinete suspenso amadeirado contrasta com o box cinza, e o espelho circular iluminado destaca a área da cuba.',
      result_text = 'As visualizações apresentam uma sequência legível de usos, da cozinha ao descanso, conectada pela passagem central. A repetição do amadeirado e dos tons claros aproxima os ambientes, enquanto a bancada compartilhada evita acrescentar uma mesa independente à circulação. O armário branco marca a transição entre a cozinha de madeira e a bancada. Para a hospedagem, a marcenaria distribui preparo, armazenamento e apoio de trabalho em lugares reconhecíveis.',
      scope = ARRAY['Cozinha linear com frentes amadeiradas e bancada pontilhada', 'Armário alto de portas claras entre cozinha e bancada', 'Bancada para duas pessoas sob a televisão', 'Prateleira superior para objetos e plantas', 'Área de descanso junto às cortinas da varanda', 'Espelho de topo arredondado próximo à entrada', 'Banheiro com gabinete suspenso e espelho circular iluminado', 'Trilho preto de iluminação no eixo longitudinal']::text[],
      seo_title = 'Think Tanabi em Perdizes | Marcenaria e integração de usos',
      seo_description = 'Conheça a proposta do Think Tanabi, em Perdizes: cozinha linear, bancada para dois e descanso conectados por marcenaria clara e amadeirada.',
      cover_alt = 'Cozinha com armários amadeirados e escuros, bancada cinza, espelho de topo curvo e passagem em direção à cama e à varanda.'
  WHERE slug = 'to-think-tanabi-perdizes'
