  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'ml-mbi-one';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para este estúdio no Aria Higienópolis organiza cozinha, refeições, trabalho e descanso em uma sequência aberta. Armários claros e painéis amadeirados dão continuidade ao ambiente, enquanto a mesa preta e os detalhes escuros pontuam a composição. A iluminação sob os armários destaca a bancada sem acrescentar volumes à circulação.',
      intro = 'Nas visualizações do Aria Higienópolis, a perspectiva desde a entrada revela a cozinha à esquerda, a cama à direita e o estar junto à abertura envidraçada. O piso de aparência amadeirada percorre essa sequência, reforçando a continuidade entre os usos. Bege, branco e tons amadeirados formam uma base próxima em cor, contrastada pelos puxadores, pela mesa de refeições e pela cadeira de trabalho escuros. A marcenaria alterna portas fechadas, nichos e prateleiras: concentra a guarda na cozinha e oferece espaços abertos para objetos e plantas ao longo da parede. A área do projeto é de 31,67 m². O custo de reforma registrado para este projeto é de R$ 2.895,85/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial da proposta é reunir preparo de alimentos, refeições, trabalho e descanso sem fragmentar o estúdio com novas divisões. A proximidade entre cama, mesa e cozinha exige distinguir os apoios de cada atividade, mantendo legível o percurso que conecta a entrada ao estar junto às cortinas.',
      solution = 'O desenho concentra pia, superfície de cocção e micro-ondas em uma frente de armários, com um nicho estreito para potes acima da bancada pontilhada. Ao lado, a mesa redonda preta acomoda duas cadeiras sem repetir o volume de uma bancada fixa. Mais ao fundo, uma mesa clara sob a televisão define o apoio de trabalho diante do sofá. Painéis verticais amadeirados marcam essas transições, e um pequeno apoio de café ocupa a lateral da área de descanso.',
      result_text = 'As visualizações mostram uma proposta em que cada uso tem um apoio reconhecível, embora compartilhe o mesmo ambiente. A repetição dos acabamentos claros aproxima cozinha e estar; os elementos pretos destacam mesas, assentos e luminárias, tornando seus contornos mais definidos na composição. Na locação por temporada, a cozinha clara e a mesa próxima ao descanso procuram tornar a rotina direta. O investimento em marcenaria está relacionado à distribuição dos objetos e à apresentação acolhedora do apartamento.',
      scope = ARRAY['Cozinha linear com armários claros e nicho aberto para potes', 'Bancada pontilhada com pia, superfície de cocção e micro-ondas abaixo', 'Mesa redonda preta com duas cadeiras junto ao painel amadeirado', 'Mesa de trabalho sob a televisão, diante do sofá', 'Painéis amadeirados com nichos e prateleiras para objetos e plantas', 'Apoio de café sobre armário com portas envidraçadas', 'Iluminação linear no teto e sob os armários da cozinha', 'Banco junto à geladeira com espaço inferior para calçados']::text[],
      seo_title = 'Aria Higienópolis | Estúdio com marcenaria e usos integrados',
      seo_description = 'Conheça a proposta do Aria Higienópolis: cozinha clara, mesa redonda, apoio de trabalho e descanso conectados por painéis amadeirados.',
      cover_alt = 'Cozinha amadeirada e branca com bancada clara, geladeira prateada, iluminação sob os armários e mesa de refeições ao fundo.'
  WHERE slug = 'cm-aria-higienopolis'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '81620c0a52fd984465c4fd397647cf40';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'cm-aria-higienopolis';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o studio no ID Alta Romana, na Vila Romana, reúne cozinha, guarda de roupas e bancada com duas cadeiras em uma mesma parede. Em frente, a cama ganha cabeceira amadeirada e luz indireta. Superfícies brancas, tons castanhos e detalhes pretos diferenciam os elementos sem fragmentar o ambiente.',
      intro = 'Nas visualizações, a organização do studio parte de duas frentes: uma concentra preparo de alimentos, armazenamento e apoio para trabalho ou refeições; a outra acomoda o descanso. Entre elas, a faixa de piso livre conecta a entrada à região das cortinas. O armário alto de portas brancas ocupa a transição entre a cozinha e a bancada, enquanto as prateleiras amadeiradas aproximam visualmente esses usos. Na área da cama, o painel baixo recebe uma linha de iluminação superior, destacando a cabeceira sem acrescentar volume sobre os travesseiros. O banheiro permanece separado por paredes e porta. A área do projeto é de 19,53 m². O custo de reforma registrado para este projeto é de R$ 3.657,55/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio do desenho é acomodar funções distintas no mesmo recinto sem transformar toda a parede em um bloco fechado de armários. Também é necessário reservar uma superfície para refeições ou computador e manter o acesso à cama, ao banheiro e à entrada legível na planta.',
      solution = 'A marcenaria alterna módulos fechados brancos e prateleiras abertas amadeiradas, concentrando o armazenamento e deixando objetos de uso à vista. Ao lado do armário alto, a bancada com duas cadeiras pretas fica sob a televisão. O fundo castanho aproxima cozinha e apoio de trabalho, em contraste com as portas claras. Junto à cama, pequenos apoios laterais dispensam volumes maiores. No banheiro, o gabinete aberto oferece duas prateleiras sob a bancada pontilhada, ao lado do box transparente.',
      result_text = 'A proposta apresenta uma separação de usos feita sobretudo pela posição do mobiliário, sem divisórias entre cozinha e cama. A repetição do amadeirado conecta as duas frentes, enquanto cortinas claras, enxoval neutro e luz na cabeceira distinguem visualmente a área de descanso. A planta organiza cozinha e descanso em planos próximos, deixando os apoios sociais na passagem entre os usos. Para locação, o objetivo é oferecer ao hóspede uma unidade funcional e bem apresentada.',
