  UPDATE public.projects
  SET summary = 'A proposta para o Next One Arthur Prado, na Bela Vista, aproxima cozinha, estar e trabalho por meio de uma sequência de móveis junto à parede. Verde acinzentado, superfícies amadeiradas e sofá cinza compõem uma paleta de contrastes suaves, enquanto o quarto aparece separado, com cortinas claras e espelho de topo arredondado.',
      intro = 'Nas visualizações, a cozinha ocupa uma das laterais do ambiente e se prolonga visualmente pelo móvel baixo sob a TV até a bancada de trabalho junto à janela. Do lado oposto, o sofá cinza deixa uma faixa central livre para circulação. A geladeira aparece em um módulo verde acinzentado, acompanhado de nichos claros abertos que oferecem armazenamento sem formar uma frente inteiramente fechada. O piso amadeirado aproxima esses elementos, enquanto paredes neutras reduzem a competição visual entre equipamentos, mobiliário e a vista urbana ao fundo. A área do projeto é de 29,4 m². O custo de reforma registrado para este projeto é de R$ 3.231,29/m², conforme a base de contratos da Bewild.',
      challenge = 'O principal desafio espacial está na proximidade entre preparo, estar e trabalho: bancada, TV e mesa precisam compartilhar a mesma lateral sem confundir seus apoios. Também é necessário acomodar o volume da geladeira perto do sofá e das portas, mantendo legível o percurso até a área envidraçada.',
      solution = 'O desenho diferencia os usos pelas alturas: bancada com cuba na cozinha, armário baixo diante do sofá e superfície amadeirada com cadeira de trabalho ao fundo. Uma pequena mesa redonda oferece apoio para refeições junto ao envidraçamento. No quarto, a cama se volta para a TV, com cortinas claras e espelho vertical ao lado. O banheiro retoma o verde no gabinete suspenso e combina bancada clara pontilhada, armário espelhado e fechamento transparente do box.',
      result_text = 'As visualizações apresentam uma composição em que o verde marca volumes de armazenamento e o amadeirado conecta piso e mobiliário. A disposição lateral dos apoios mantém o centro desobstruído, enquanto o quarto separado distingue o descanso das atividades reunidas no estar. O móvel baixo verde acinzentado dá identidade à área da televisão e dialoga com a cozinha de madeira. Na locação, a intenção é reunir preparo e descanso em uma experiência visual contínua.',
      scope = ARRAY['Cozinha linear com bancada clara pontilhada e frentes amadeiradas', 'Móvel baixo verde acinzentado sob a TV do estar', 'Bancada amadeirada de trabalho junto à janela', 'Módulo para geladeira acompanhado de nichos claros abertos', 'Mesa redonda de refeições junto ao envidraçamento', 'Quarto com TV, cortinas claras e espelho de topo arredondado', 'Banheiro com gabinete verde suspenso e armário espelhado']::text[],
      seo_title = 'Next One Arthur Prado: interiores na Bela Vista',
