  UPDATE public.projects
  SET summary = 'A proposta para o Urban Flex Flats Bela Cintra aproxima cozinha, refeições, trabalho e descanso sem recorrer a divisórias entre esses usos. O desenho da marcenaria distingue cada apoio, enquanto o azul profundo ao fundo contrasta com superfícies amadeiradas. Armários cinza e nichos abertos complementam a organização do conjunto.',
      intro = 'Nas visualizações, a entrada se conecta a uma passagem entre a cozinha linear e o banheiro, conduzindo à cama posicionada ao fundo. Na lateral oposta à cabeceira, um enquadramento amadeirado reúne banco estofado, mesa redonda e bancada de trabalho sob a televisão. Essa composição aproxima funções distintas, mas oferece um apoio próprio para cada atividade. O azul profundo dá continuidade à parede atrás desses elementos; já os armários cinza estabelecem uma transição discreta para a cozinha. A roupa de cama clara contrasta com essa base mais escura, e as almofadas em tom dourado retomam os tons quentes do amadeirado. A área do projeto é de 21,3 m². O custo de reforma registrado para este projeto é de R$ 3.708,92/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial está em acomodar apoios de refeição e trabalho diante da cama, mantendo uma passagem contínua desde a entrada. Também é necessário conciliar a presença da geladeira e dos armários com uma composição visual coesa, sem transformar toda a lateral em um bloco fechado de armazenamento.',
      solution = 'O desenho alterna volumes fechados na cozinha com uma área aberta emoldurada pelo amadeirado. O banco encostado à parede atende à mesa redonda, enquanto a bancada ao lado recebe cadeira e apoio para computador. Acima, a prateleira longa acompanha a televisão, com linhas de luz que evidenciam sua extensão. Próximo à cama, cabideiro e prateleiras abertas delimitam a guarda de roupas. As vistas com compartimentos abertos também mostram armazenamento sob o banco e na cozinha.',
      result_text = 'O resultado apresentado em 3D é uma sequência de usos reconhecíveis pelo mobiliário, não por novas divisórias. A repetição do amadeirado conecta os apoios, enquanto o cinza concentra visualmente a cozinha e o azul marca o fundo da área de trabalho e refeições. A madeira aproxima a bancada de apoio da linguagem da cozinha cinza. Para a hospedagem, essa continuidade permite combinar refeição e trabalho sem que o studio perca sua unidade visual.',
      scope = ARRAY['Cozinha linear com armários cinza e bancada escura', 'Enquadramento amadeirado para banco e bancada de trabalho', 'Mesa redonda junto ao banco estofado com armazenamento inferior', 'Bancada de trabalho com cadeira sob a televisão', 'Prateleira longa com iluminação linear sobre a parede azul', 'Cabideiro aberto e prateleiras para guarda de roupas', 'Cama ao fundo com cabeceira amadeirada e cortina lateral']::text[],
      seo_title = 'Urban Flex Flats Bela Cintra | Interiores e marcenaria',
