      seo_title = 'Urbanflex | Marcenaria entre trabalho e descanso',
      seo_description = 'Conheça a proposta para o Urbanflex: cozinha linear, banco com mesa redonda e bancada de trabalho conectados pela composição amadeirada.',
      cover_alt = 'Planta 3D de apartamento compacto com dormitório, cozinha, banheiro e mesa, destacando os móveis e a posição das divisórias.'
