  UPDATE public.projects
  SET summary = 'A proposta aproxima estar, refeições e cozinha por meio do piso amadeirado e de uma paleta clara, pontuada por elementos pretos. A mesa redonda ocupa a transição entre os usos, enquanto painéis com frisos verticais, prateleiras altas e armários distribuem apoios sem concentrar todo o armazenamento junto ao chão.',
      intro = 'Nas visualizações, o sofá claro fica diante da televisão, instalada em um painel com frisos verticais ao lado de uma porta. Uma prateleira amadeirada percorre a parte superior dessa parede, conectando visualmente o espelho, a passagem e o painel. A mesa preta com duas cadeiras de tom castanho marca o ponto de refeições sem formar uma barreira contínua entre estar e cozinha. Ao fundo, a cortina clara cobre uma ampla abertura e suaviza o contraste com os contornos escuros das cadeiras, do espelho e dos suportes da prateleira. A área do projeto é de 28,4 m². O custo de reforma registrado para este projeto é de R$ 3.243,30/m², conforme a base de contratos da Bewild.',
      challenge = 'A proximidade entre cozinha, equipamento de lavagem, mesa e sofá exige distinguir atividades sem fragmentar o espaço. Outro ponto do desenho é conciliar a parede da televisão com uma passagem: o painel precisa acomodar a tela e o apoio inferior, mantendo o vão da porta desimpedido.',
      solution = 'O desenho combina armários inferiores cinza, volumes superiores amadeirados e bancada de aparência pontilhada na cozinha. Prateleiras abertas deixam utensílios e pequenos equipamentos acessíveis, com iluminação sob os apoios. No estar, o móvel suspenso sob a televisão deixa o piso aparente. Já no quarto, a cabeceira cinza recebe uma linha de luz, e o interior do roupeiro apresenta cabideiros, gavetas e prateleiras, separando espaços para peças penduradas e dobradas.',
      result_text = 'As visualizações mostram continuidade entre as áreas de convívio e separação dos espaços de descanso por paredes e portas. O amadeirado aproxima piso e marcenaria, enquanto preto e cinza delimitam móveis e equipamentos sobre a base clara, sem depender de grandes superfícies escuras. A mesa redonda com duas cadeiras organiza refeições junto à circulação do studio. Para a hospedagem, esse núcleo de apoio complementa o descanso e estabelece uma leitura doméstica do espaço compacto.',
      scope = ARRAY['Mesa redonda preta com duas cadeiras em tom castanho', 'Painel de televisão com frisos verticais junto à porta', 'Prateleira alta amadeirada com suportes pretos no estar', 'Cozinha com armários cinza e amadeirados e bancada pontilhada', 'Equipamento de lavagem sob bancada de apoio', 'Cabeceira cinza com linha de iluminação no quarto', 'Roupeiro com cabideiros, gavetas e prateleiras visíveis']::text[],
      seo_title = 'Estar e cozinha com marcenaria clara e contrastes pretos',
