  UPDATE public.projects
  SET summary = 'A proposta para o GO BALKON organiza cozinha, bancada de apoio e cama ao longo de uma circulação contínua. Superfícies amadeiradas aproximam visualmente esses usos, enquanto armários claros equilibram os planos em marrom acinzentado. A bancada escura da cozinha e os perfis pretos da iluminação introduzem contraste sem dominar o conjunto.',
      intro = 'Nas visualizações do GO BALKON, a cozinha ocupa uma das extremidades do ambiente, e a cama aparece junto à abertura com cortinas, ao fundo. Entre esses pontos, o piso de aparência amadeirada acompanha a passagem, sem mudanças de acabamento que fragmentem o percurso. Na lateral oposta à cama, uma bancada com duas cadeiras reúne apoio para trabalho ou refeições sob a televisão. O armário alto de portas claras faz a transição entre essa bancada e a cozinha. Assim, a marcenaria organiza os usos pelas posições e pelos volumes, sem fechar o setor de descanso com uma divisória. A área do projeto é de 28,4 m². O custo de reforma registrado para este projeto é de R$ 2.429,58/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar preparo de alimentos, armazenamento, apoio para duas pessoas e descanso, mantendo desimpedido o caminho até a cama. Outro ponto é equilibrar a presença dos armários e da televisão: concentrar esses elementos nas laterais permite preservar a passagem central e reduzir a sobreposição entre móveis e circulação.',
      solution = 'Na cozinha, a proposta combina módulos inferiores amadeirados, armários superiores brancos e um nicho para micro-ondas. A faixa iluminada sobre o revestimento branco retangular evidencia a área da pia. Junto à televisão, a bancada alongada deixa espaço para as cadeiras sob o tampo, e a prateleira superior acrescenta apoio sem ocupar o piso. O fundo marrom acinzentado com frisos verticais diferencia esse trecho, enquanto o espelho de contorno arredondado marca a circulação.',
      result_text = 'As visualizações apresentam uma composição em que cada lateral assume funções distintas, conectadas pelo piso e pela repetição do amadeirado. A cozinha mantém seus equipamentos agrupados, e a bancada sob a televisão acrescenta um segundo apoio sem avançar sobre o acesso à cama. O nicho de madeira incorpora o micro-ondas à marcenaria branca, em contraste com a bancada escura. Para a hospedagem, essa cozinha concentrada procura oferecer preparo organizado e uma imagem de acolhimento.',
      scope = ARRAY['Cozinha com bancada escura, pia e cooktop', 'Armários superiores brancos e nicho amadeirado para micro-ondas', 'Bancada de trabalho ou refeições com duas cadeiras', 'Televisão sobre plano marrom acinzentado com frisos verticais', 'Armário alto de portas claras junto à bancada', 'Prateleira com iluminação linear acima da televisão', 'Espelho vertical de contorno arredondado na circulação']::text[],
