  UPDATE public.projects
  SET summary = 'A proposta para o Urban Flex aproxima estar, refeições e cozinha por uma combinação de superfícies amadeiradas, volumes claros e linhas pretas. O espelho junto à mesa amplia visualmente o ambiente, enquanto a separação do quarto, legível na planta, distingue a área de descanso dos demais usos.',
      intro = 'Nas visualizações do Urban Flex, os estofados claros formam o centro do estar, acompanhados por um pufe e uma pequena mesa lateral preta. Os contornos escuros do sofá reaparecem nas cadeiras, no pendente e na estante, criando continuidade entre peças de funções diferentes. Ao fundo, a mesa redonda fica junto à janela e à parede espelhada, que reflete o mobiliário e prolonga a percepção do espaço. O piso de aparência amadeirada conecta os ambientes, enquanto cortinas claras suavizam o contraste com os perfis pretos das janelas. A área do projeto é de 40,75 m². O custo de reforma registrado para este projeto é de R$ 3.479,01/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava aproximar os apoios de refeição, preparo e estar sem tornar os volumes visualmente indistintos. Na cozinha, a concentração de armários e equipamentos exigia uma composição diferente da leveza dos assentos. Já o quarto pedia uma leitura própria, separado da área que reúne mesa, sofá e televisão.',
      solution = 'A marcenaria clara concentra nichos e gavetas na cozinha, com bancada escura e revestimento preto em pequenas peças retangulares marcando a faixa de preparo. O painel amadeirado acompanha a passagem lateral. No estar, prateleiras abertas com montantes pretos contrapõem-se aos estofados volumosos. No quarto, o painel atrás da cama reúne visualmente os apoios laterais, enquanto a persiana sobre a cabeceira e a cortina lateral permitem graduar a entrada de luz.',
      result_text = 'As imagens apresentam uma proposta em que o contraste organiza a leitura: preto nos contornos e na faixa de preparo, tons claros nos volumes maiores e aparência amadeirada como ligação. A planta evidencia a separação do descanso sem interromper a proximidade entre estar e refeições. O sofá claro, o pufe e a mesa próxima à janela estabelecem lugares de convivência e pausa. Para morar, a composição valoriza a luz e o conforto dos diferentes momentos da rotina.',
      scope = ARRAY['Composição do estar com sofá claro, pufe e mesa lateral preta', 'Mesa redonda junto à parede espelhada e à janela', 'Estante aberta com prateleiras claras e montantes pretos', 'Marcenaria da cozinha com nichos superiores e gavetas inferiores', 'Bancada escura e revestimento preto na faixa de preparo', 'Painel amadeirado na passagem lateral da cozinha', 'Cabeceira amadeirada com apoios laterais, persiana e cortina']::text[],
      seo_title = 'Urban Flex: interiores claros com contrastes em preto',
      seo_description = 'Explore a proposta do Urban Flex: estar e refeições próximos, cozinha com marcenaria clara e quarto separado, em tons neutros e amadeirados.',
      cover_alt = 'Estar integrado à área de descanso com poltronas claras, armários amadeirados e estrutura escura nos móveis de apoio.'
  WHERE slug = 'tb-urban-flex'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'd8f4ea14c1f73ba7ae9f54c1bc4d7254';
