  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'tb-urban-flex';
  END IF;

  UPDATE public.projects
  SET summary = 'No LM Urban Flex, a proposta de 40,12 m² tem a moradia como foco. A sala e o dormitório recebem lugares próprios, ligados pela presença da madeira e por uma base de cinza e branco. O projeto combina organização dos usos com uma atmosfera tranquila, valorizando a convivência na sala e o recolhimento na área de dormir.',
      intro = 'O painel amadeirado ocupa um papel central entre os ambientes: dá suporte à televisão e estabelece uma referência de separação entre estar e dormitório. Sua textura aquece a composição de frentes cinza, móveis claros e bancada escura da cozinha. A repetição da madeira na cabeceira e nos nichos aproxima os setores, mesmo quando cumprem funções diferentes.

Na sala, o sofá claro e a mesa redonda com cadeiras brancas equilibram a presença do painel. O espelho próximo à área de refeições repete visualmente partes do ambiente, acrescentando profundidade à composição. Os renders apresentam uma proposta em fase de projeto, com custo de reforma informado de R$ 2.492,52/m².',
      challenge = 'Para morar em uma área compacta, o conforto cotidiano depende de poder alternar convivência e descanso com alguma distinção entre os espaços. O desafio da proposta está em organizar essa relação sem perder os apoios de cozinha, refeições e armazenamento. A sala precisa oferecer permanência própria, e o dormitório deve preservar uma leitura mais reservada.',
      solution = 'O painel central estrutura a relação entre os ambientes, enquanto sofá e mesa definem os usos da sala. A cozinha concentra seus equipamentos e armários em uma frente organizada. No dormitório, cabeceira, armários superiores e armazenamento alto compõem os apoios de rotina. A madeira repetida e as linhas de luz previstas junto à marcenaria ligam organização e sensação de acolhimento.',
      result_text = 'A proposta favorece uma rotina em que descansar, preparar refeições e permanecer na sala têm lugares reconhecíveis. O aconchego nasce da combinação entre textura amadeirada, superfícies suaves e distinção de usos. A distinção entre sala e dormitório permite alternar convivência e recolhimento, enquanto a linguagem dos móveis mantém os ambientes próximos na experiência de morar.',
      scope = ARRAY['Painel amadeirado da televisão na transição entre sala e dormitório', 'Móvel baixo claro com nichos do lado da sala', 'Mesa redonda de madeira com quatro cadeiras e pendente preto', 'Cozinha cinza com bancada e revestimento pretos', 'Prateleiras amadeiradas e iluminação sob os armários previstos em 3D', 'Estrutura vertical de nichos abertos junto ao estar', 'Quarto proposto com cabeceira de madeira e armários claros elevados']::text[],
      seo_title = 'Apartamento de 40,12 m² — LM Urban Flex | Bewild',
      seo_description = 'Veja o projeto de 40,12 m² no LM Urban Flex para moradia, com sala e quarto separados, marcenaria amadeirada e tons neutros. Conheça a proposta.',
      cover_alt = 'Planta 3D do apartamento Urban Flex com sala e mesa redonda à esquerda, dormitório à direita e cozinha junto à entrada.'
  WHERE slug = 'lc-lm-urban-flex'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '0441e3655592c3e9560f28e9ecc5cb81';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'lc-lm-urban-flex';
  END IF;

  UPDATE public.projects
  SET summary = 'No Green View Butantã, a proposta distribui cozinha, cama, bancada de trabalho e mesa de refeições ao longo de uma planta estreita. O piso de aparência amadeirada aproxima os usos, enquanto superfícies claras equilibram a presença da marcenaria. A organização junto às laterais mantém uma passagem contínua entre a entrada e a extremidade com mesa redonda.',
      intro = 'O desenho para o studio no Butantã combina um ambiente principal compartilhado com banheiro separado. Na planta 3D, a cozinha acompanha uma das laterais próximas à entrada; mais adiante, a bancada de trabalho fica diante da cama, e a mesa redonda com duas cadeiras ocupa a extremidade oposta. Essa distribuição oferece apoios diferentes para alimentação e trabalho, sem depender de uma única superfície. Na área de descanso, o painel amadeirado prolonga visualmente a cabeceira e recebe uma linha de luz no encontro com a parede clara. Roupa de cama branca, manta bege e pequenos apoios pretos estabelecem contrastes pontuais, sem competir com o desenho do painel. A área do projeto é de 23,61 m². O custo de reforma registrado para este projeto é de R$ 2.689,54/m², conforme a base de contratos da Bewild.',
      challenge = 'A planta pede uma articulação cuidadosa entre passagem e mobiliário: cama e bancada se enfrentam, enquanto cozinha e banheiro ocupam o trecho de acesso. O desafio da proposta é acomodar esses usos sem preencher o centro com móveis adicionais, além de prever armazenamento para objetos que não precisam ficar expostos.',
      solution = 'A cozinha reúne cuba e área de cocção em uma bancada clara e pontilhada, sobre portas e gavetas amadeiradas. Um gavetão junto ao piso aparece aberto na visualização, revelando espaço para utensílios de limpeza. O revestimento claro de peças retangulares contrasta com as frentes mais escuras. No banheiro, o desenho combina bancada pontilhada, gabinete aberto e espelho circular; a divisória transparente delimita o banho sem ocultar as superfícies claras ao fundo.',
      result_text = 'As visualizações apresentam uma proposta em que cada apoio tem posição definida: preparo junto à entrada, trabalho diante da cama e refeições na extremidade da planta. A repetição do amadeirado conecta os setores, enquanto o banheiro mantém separação física em relação ao ambiente principal.',
      scope = ARRAY['Distribuição lateral da cozinha e da bancada de trabalho', 'Mesa redonda com duas cadeiras na extremidade da planta', 'Painel de cabeceira amadeirado com linha de iluminação', 'Cozinha com bancada pontilhada e revestimento retangular claro', 'Gavetão inferior para utensílios de limpeza', 'Apoios pretos junto à cama', 'Banheiro com gabinete aberto, espelho circular e divisória transparente']::text[],
      seo_title = 'Green View Butantã: projeto de studio com marcenaria',
      seo_description = 'Conheça a proposta do Green View Butantã: cozinha linear, cabeceira iluminada e apoios distintos para trabalho e refeições em um studio.',
      cover_alt = 'Planta 3D de apartamento com cozinha linear, cama, banheiro, bancada de trabalho e mesa redonda junto à área de estar.'
  WHERE slug = 'jw-green-view-butanta'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'b2b959fc4b4174a01fb396262b3e8d37';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'jw-green-view-butanta';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o Green View Butantã aproxima descanso e refeições em um ambiente de tons claros, com contrastes concentrados nos planos amadeirados. A cabeceira horizontal organiza a composição da cama, enquanto a mesa circular oferece apoio próximo. No banheiro, o gabinete bege e a bancada pontilhada retomam essa paleta.',
      intro = 'Nas visualizações do Green View Butantã, a cama ocupa o centro da composição, apoiada por uma cabeceira amadeirada que se estende além de suas laterais. Acima dela, uma faixa de luz marca a transição para a parede clara e destaca o desenho horizontal. Roupa de cama e cortinas em tons suaves reduzem os contrastes junto à área de descanso. Ao lado, a mesa circular com cadeiras claras introduz um lugar para refeições sem estabelecer uma divisão física. O amadeirado aparece também no piso e no tampo, aproximando visualmente esses usos. A área do projeto é de 23,61 m². O custo de reforma registrado para este projeto é de R$ 2.689,54/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio perceptível no desenho é acomodar a presença dominante da cama e o apoio de refeições sem transformar o ambiente em uma sequência de volumes pesados. No banheiro, a composição precisa reunir bancada, guarda fechada e área de banho, mantendo uma leitura simples entre superfícies próximas.',
      solution = 'A proposta concentra o tom amadeirado mais escuro na cabeceira, em contraste com a cama clara, e utiliza uma pequena mesa lateral preta como apoio. O tampo circular junto às cadeiras evita quinas na área de refeições. No banheiro, o gabinete de frentes lisas reúne a guarda sob a pia; a bancada pontilhada acrescenta textura, enquanto o espelho redondo contrasta com as linhas retas do móvel e do box transparente.',
      result_text = 'As visualizações apresentam uma composição em que os contrastes ajudam a distinguir os apoios: cabeceira para o descanso, mesa para refeições e gabinete para guarda no banheiro. A repetição de beges e superfícies claras aproxima os ambientes sem torná-los idênticos.',
      scope = ARRAY['Cabeceira amadeirada com faixa de iluminação superior', 'Composição da cama em tons claros e apoio lateral preto', 'Mesa circular de aparência amadeirada com cadeiras claras', 'Piso amadeirado na área de descanso e refeições', 'Gabinete bege de frentes lisas sob bancada pontilhada', 'Espelho circular sobre a pia do banheiro', 'Box transparente e superfícies claras na área de banho']::text[],
      seo_title = 'Green View Butantã: descanso, refeições e tons suaves',
      seo_description = 'Conheça a proposta do Green View Butantã, com cabeceira amadeirada, mesa circular e banheiro em tons bege com bancada pontilhada.',
      cover_alt = 'Banheiro com parede de tonalidade bege, espelho redondo, bancada clara de aspecto granulado, vaso branco e box de vidro.'
  WHERE slug = 'jw-green-view-butanta-2'
