  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'jw-green-view-butanta-2';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o Edifício Dom Brás aproxima estar, mesa de refeições e cozinha, enquanto mantém o quarto e o ambiente com poltrona separados por paredes. Tons bege e superfícies amadeiradas conectam os espaços visualmente. Prateleiras, nichos e cabideiro aberto distribuem funções de apoio, exposição e guarda sem recorrer a grandes volumes fechados.',
      intro = 'Nas visualizações do Edifício Dom Brás, o piso de aparência amadeirada percorre os ambientes secos e estabelece uma base comum para paredes bege, estofados claros e detalhes marrons. O estar ocupa a faixa junto à janela, com sofá voltado para um apoio baixo na parede oposta. Mais perto da entrada, a mesa redonda com quatro cadeiras faz a transição até a cozinha linear. A planta mostra uma organização distinta para o descanso: o quarto fica separado da área de refeições, e outro ambiente reúne poltrona, tapete e bancada junto à parede. A área do projeto é de 34 m². O custo de reforma registrado para este projeto é de R$ 2.396,76/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava reunir sofá, refeições e preparo em uma mesma área, sem ocupar com mobiliário o percurso até os demais ambientes. No quarto, a questão era acomodar a guarda de roupas ao lado da cama e da janela, mantendo apoios acessíveis e uma composição visualmente leve.',
      solution = 'A mesa redonda concentra os assentos entre o estar e a cozinha, deixando suas bordas sem quinas voltadas à passagem. Na cozinha, prateleiras abertas aproveitam a faixa acima da bancada e da geladeira. No quarto, uma prateleira alta se prolonga até a estrutura com cabideiro, nichos e apoio lateral à cama. O banheiro combina bancada amadeirada, cuba branca e espelho arredondado, contrastando com as linhas retas do box transparente.',
      result_text = 'As visualizações apresentam continuidade de cores sem eliminar a separação entre os espaços. A área de refeições permanece ligada à cozinha, enquanto paredes resguardam o quarto. A marcenaria aberta torna visíveis os lugares destinados a roupas, objetos e apoios cotidianos. A mesa com quatro lugares amplia a convivência junto à cozinha, enquanto o quarto separado resguarda o descanso. Na moradia, essa distribuição permite equilibrar encontros, atividades diárias e intimidade.',
      scope = ARRAY['Estar com sofá claro e apoio baixo na parede oposta', 'Mesa redonda com quatro cadeiras junto à cozinha', 'Cozinha linear com prateleiras acima da bancada e da geladeira', 'Quarto com cabideiro aberto, nichos baixos e prateleira alta', 'Ambiente separado com poltrona, tapete e bancada', 'Banheiro com bancada amadeirada, cuba de apoio e box transparente', 'Paleta bege com piso amadeirado e detalhes marrons']::text[],
      seo_title = 'Edifício Dom Brás: interiores e marcenaria aberta',
      seo_description = 'Conheça a proposta do Edifício Dom Brás, com estar e cozinha conectados, mesa redonda, quarto separado e marcenaria aberta em tons neutros.',
      cover_alt = 'Planta 3D de apartamento com quarto separado, cozinha, banheiro e área de estar, incluindo mesa e posição dos armários.'
  WHERE slug = 'ls-edificio-dom-bras'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = '4b7abed148a1e44944f0dfb75575ce6e';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'ls-edificio-dom-bras';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o Nex One Vila Nova organiza cozinha, apoio para refeições e trabalho e estar ao longo de uma passagem central. Superfícies amadeiradas equilibram os armários escuros, enquanto detalhes bordô aproximam o painel da bancada e as almofadas do sofá. A porta do dormitório preserva o espaço de descanso da sequência formada por cozinha, mesa e estar.',
      intro = 'Nas visualizações do Nex One Vila Nova, a abertura envidraçada ao fundo marca o eixo entre a cozinha e o sofá. À esquerda, armários inferiores escuros e módulos superiores amadeirados acompanham uma bancada que se prolonga em apoio com cadeiras. À direita, o sofá cinza recebe almofadas bordô e claras, retomando as cores do quadro e do painel oposto. Cortinas cinza emolduram a abertura, enquanto o piso de aparência amadeirada dá continuidade aos ambientes. A planta mostra o dormitório separado do estar, com a cama entre apoios laterais e uma área de guarda junto ao acesso. A área do projeto é de 29 m². O custo de reforma registrado para este projeto é de R$ 2.241,38/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar preparo, refeições, trabalho pontual e estar em um ambiente alongado, sem ocupar a passagem até a abertura externa. Outro ponto é equilibrar o peso visual dos armários escuros com as superfícies claras e amadeiradas, mantendo o dormitório como um recinto separado, com espaço próprio para cama e roupas.',
      solution = 'A proposta concentra os equipamentos e a guarda da cozinha em uma lateral, incluindo um nicho para micro-ondas e um painel amadeirado junto à geladeira. O tampo com cadeiras oferece apoio para refeições e notebook, diante do sofá. Spots em trilho acompanham o eixo longitudinal do teto. No dormitório, a faixa amadeirada contrasta com a parede cinza-escura, e o armário apresentado aberto distribui cabideiro, prateleiras e compartimentos superiores para diferentes volumes de roupas e objetos.',
      result_text = 'As visualizações apresentam uma composição em que o mobiliário deixa legível a passagem central e diferencia os apoios de cozinha, trabalho e estar. A repetição do amadeirado e dos tons de cinza conecta os ambientes, enquanto as divisórias delimitam o espaço de descanso. A madeira superior e o painel junto à geladeira integram equipamentos à cozinha escura. Para a locação, a intenção é conferir uma identidade consistente ao conjunto de preparo e à apresentação do apartamento.',
      scope = ARRAY['Cozinha linear com armários escuros e módulos superiores amadeirados', 'Nicho para micro-ondas e painel lateral junto à geladeira', 'Tampo amadeirado com cadeiras para refeições e apoio ao notebook', 'Sofá cinza com almofadas bordô e mesa lateral redonda', 'Trilho de spots no eixo longitudinal do estar', 'Dormitório separado com faixa amadeirada e parede cinza-escura', 'Armário com cabideiro, prateleiras e compartimentos superiores']::text[],
      seo_title = 'Nex One Vila Nova: interiores em grafite e amadeirado',
      seo_description = 'Conheça a proposta para o Nex One Vila Nova: cozinha linear, apoio para refeições e trabalho, sofá cinza e dormitório separado com armário.',
      cover_alt = 'Ambiente integrado com cama, sofá, cozinha amadeirada, bancada escura e porta de vidro para a varanda ao fundo.'
  WHERE slug = 'jg-nex-one-vila-nova'
    AND md5(jsonb_build_array(id,status,published,visible,title,neighborhood,location,area_m2,project_type,cover_url,gallery_urls,ready_gallery_urls,summary,intro,challenge,solution,result_text,scope,seo_title,seo_description,cover_alt)::text) = 'fcfbff328d1ad009e58514086f57a312';
  GET DIAGNOSTICS affected = ROW_COUNT;
  IF affected <> 1 THEN
    RAISE EXCEPTION 'Cadastro alterado; revise e regenere a guarda antes de aplicar: %', 'jg-nex-one-vila-nova';
  END IF;

  UPDATE public.projects
  SET summary = 'A proposta para o Do It Pinheiros organiza cozinha, estar e apoios de trabalho e refeição ao longo de um eixo contínuo. A marcenaria amadeirada aproxima esses usos, enquanto o sofá verde contrasta com as superfícies claras. No dormitório separado, painel, nichos e apoios laterais compõem a área de descanso.',
      intro = 'Nas visualizações do Do It Pinheiros, a cozinha ocupa uma lateral, com bancada clara pontilhada, armários amadeirados e revestimento branco de peças retangulares com relevo. À frente, o sofá verde marca o estar sem criar uma barreira alta no percurso. Na parede oposta, uma bancada com cadeira oferece apoio para trabalho sob a televisão. Esse desenho se prolonga até o banco estofado em L junto às janelas, acompanhado de mesa redonda preta e assento baixo. O piso de aparência amadeirada aproxima visualmente os setores, enquanto os detalhes pretos pontuam a composição. A área do projeto é de 28 m². O custo de reforma registrado para este projeto é de R$ 4.556,09/m², conforme a base de contratos da Bewild.',
      challenge = 'O desafio espacial sugerido pelas imagens é acomodar preparo de alimentos, estar, trabalho e refeições numa sequência alongada, mantendo o caminho central desimpedido. Também é importante distinguir o apoio de trabalho da mesa junto às janelas e reservar ao dormitório uma organização própria, separado dos demais usos.',
      solution = 'O desenho concentra armários e superfícies de apoio nas laterais. A bancada sob a televisão atende ao trabalho, enquanto a mesa de base central se aproxima do banco em L para apoiar refeições. Prateleiras com luz inferior destacam os planos amadeirados. No dormitório, o painel atrás da cama reúne apoios laterais e recebe nichos superiores; a estante aberta ao lado amplia a guarda visível sem repetir um volume fechado junto à cama.',
      result_text = 'As visualizações apresentam uma composição em que o amadeirado conecta os ambientes e o verde marca o estar. A disposição lateral dos móveis deixa legível o percurso até as janelas, enquanto o dormitório separado mantém o descanso fora desse eixo. A madeira e o relevo horizontal claro dão textura à cozinha sem fragmentar sua composição. Para a hospedagem, o conjunto procura oferecer um ambiente de preparo acolhedor e uma imagem coerente do interior.',
