  UPDATE public.projects
  SET summary = 'A proposta para o Nex One Pereira Coutinho organiza cozinha, guarda de roupas e bancada com duas cadeiras em uma mesma lateral, deixando a cama no lado oposto. Acabamentos amadeirados aproximam os setores, enquanto o verde dos tecidos marca o descanso e contrasta com a base clara de paredes, armários e cortinas.',
      intro = 'Nas visualizações, a circulação central conecta a entrada à abertura envidraçada sem atravessar a área ocupada pela cama. À direita, a cozinha reúne cuba, bancada pontilhada, armários e nicho para micro-ondas. Essa sequência encontra um módulo aberto para roupas e uma bancada sob a televisão, com duas cadeiras e apoio para refeição ou trabalho. Do outro lado, a cabeceira amadeirada delimita o descanso, acompanhada por um apoio lateral suspenso. As cortinas claras percorrem as aberturas ao fundo e formam uma superfície contínua que contrapõe as linhas mais rígidas da marcenaria. A área do projeto é de 27 m². O custo de reforma registrado para este projeto é de R$ 3.349,33/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava aproximar preparo de alimentos, guarda, refeição e descanso sem colocar todos os elementos na mesma faixa de circulação. Outro ponto era diferenciar a cama da frente de armários e equipamentos, mantendo uma linguagem comum entre os lados e o acesso livre à porta envidraçada.',
      solution = 'A proposta concentra os volumes altos junto à cozinha e intercala portas claras, nichos e um cabideiro aberto com gavetas e espaço inferior para calçados. A bancada com duas cadeiras ocupa o trecho próximo à abertura, sem avançar sobre o eixo central. Na cama, almofadas e manta verdes destacam o descanso. A luz linear sobre a cabeceira realça o plano amadeirado, enquanto a iluminação sob os armários evidencia a bancada e o revestimento de peças retangulares.',
      result_text = 'As visualizações apresentam usos próximos, mas identificáveis pelo mobiliário: a bancada oferece apoio compartilhado, o módulo aberto reúne roupas e calçados, e o tapete demarca a cama. O amadeirado conecta essas partes, sem apagar o contraste entre equipamentos, tecidos e superfícies claras. O micro-ondas na marcenaria superior e os armários de madeira distribuem os apoios da cozinha. Para a locação, essa organização reúne preparo e armazenamento sem competir com o espaço reservado ao descanso.',
      scope = ARRAY['Cozinha linear com bancada pontilhada e armários inferiores amadeirados', 'Armários superiores claros com nicho para micro-ondas', 'Módulo aberto com cabideiro, gavetas e apoio para calçados', 'Bancada com duas cadeiras sob a televisão', 'Cabeceira amadeirada com luz linear e apoio lateral suspenso', 'Composição da cama com tecidos verdes e tapete claro', 'Cortinas claras nas aberturas e espelho vertical de contorno arredondado']::text[],
