  UPDATE public.projects
  SET summary = 'No Infinity Brooklin, a proposta aproxima descanso, refeições e trabalho sem recorrer a divisórias entre esses usos. O armário amadeirado, a bancada de trabalho e a cozinha ocupam uma mesma frente, enquanto a mesa redonda reúne cadeiras e banco estofado junto ao fechamento envidraçado. Verde e bege equilibram a composição clara.',
      intro = 'As visualizações do projeto no Brooklin mostram a cama voltada para uma parede que concentra guarda, trabalho e preparo de alimentos. Nessa frente, o volume amadeirado do armário contrasta com as superfícies claras da bancada e dos módulos da cozinha. Do outro lado, a parede bege delimita visualmente o descanso, acompanhado por mesas laterais redondas. Perto do fechamento envidraçado, outra mesa circular recebe duas cadeiras brancas e um banco estofado. A manta verde sobre a cama encontra correspondência nas almofadas e na vegetação, criando pontos de cor sem fragmentar o ambiente. A área do projeto é de 21,59 m². O custo de reforma registrado para este projeto é de R$ 3.381,19/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisava acomodar superfícies de apoio e volumes de armazenamento próximos à cama, sem transformar todos os usos em uma única bancada indiferenciada. A proximidade entre cozinha e trabalho também pedia uma transição legível, enquanto o conjunto de refeições deveria ocupar a faixa junto ao vidro.',
      solution = 'A proposta intercala o armário alto e a cozinha com uma bancada clara, cadeira de trabalho e televisão suspensa. Entre essa bancada e a geladeira, nichos verticais amadeirados oferecem apoios para objetos e espaço inferior para uma mala. Na área de refeições, o banco encostado ao fechamento envidraçado complementa as duas cadeiras, concentrando os assentos ao redor da mesa. Puxadores, base da mesa e cadeira de trabalho introduzem linhas escuras sobre os tons claros.',
      result_text = 'O resultado apresentado nas visualizações é um ambiente em que o mobiliário distingue as atividades sem isolá-las. A continuidade dos acabamentos aproxima cozinha e trabalho, enquanto a parede bege, os tecidos claros e os detalhes verdes identificam a área de descanso. O armário alto e a bancada com cadeira colocam roupas e trabalho em lugares definidos. Para a hospedagem, esses apoios ajudam a organizar a estadia, enquanto a televisão suspensa participa do descanso.',
      scope = ARRAY['Armário alto com frentes amadeiradas e puxadores escuros', 'Bancada de trabalho com cadeira giratória e televisão suspensa', 'Nichos verticais entre a bancada e a geladeira', 'Cozinha linear com módulos claros e bancada pontilhada', 'Mesa redonda com duas cadeiras brancas e banco estofado', 'Composição da cama com manta verde e mesas laterais redondas', 'Vegetação e almofadas verdes junto ao fechamento envidraçado']::text[],
      seo_title = 'Infinity Brooklin: interiores em tons claros e verde',
