  UPDATE public.projects
  SET summary = 'A proposta aproxima cozinha, apoio para refeições ou trabalho e área de descanso por meio de uma paleta amadeirada, branca e cinza. A marcenaria alterna volumes fechados e prateleiras iluminadas, enquanto uma peça vertical branca marca a passagem entre a bancada escura da cozinha e o tampo com duas cadeiras.',
      intro = 'Nas visualizações do ID Alto da Vila Romana, a cozinha ocupa uma faixa da parede, com cuba e cooktop sobre bancada escura pontilhada. Prateleiras amadeiradas acomodam o micro-ondas e objetos, deixando os equipamentos concentrados nesse trecho. Ao lado, o tampo branco com duas cadeiras oferece apoio para refeições ou trabalho, sob uma televisão instalada no painel cinza. A vista superior mostra a cama próxima à janela e um percurso entre ela e a cozinha. O piso amadeirado aproxima esses setores, enquanto as cortinas longas acompanham a abertura junto à área de descanso. A área do projeto é de 19 m². O custo de reforma registrado para este projeto é de R$ 3.368,42/m², conforme a base de contratos da Bewild.',
      challenge = 'O desenho precisa conciliar preparo de alimentos, apoio de mesa e descanso em setores próximos, sem tornar todos os elementos visualmente equivalentes. A concentração de equipamentos na cozinha pede organização vertical; junto à cama, a composição depende de apoios menores e de uma cabeceira que diferencie esse trecho do restante.',
      solution = 'Na proposta, portas e gavetas amadeiradas formam a base da cozinha, enquanto as prateleiras abertas recebem linhas de luz voltadas às superfícies inferiores. O volume branco alto interrompe essa sequência e delimita o apoio com cadeiras, sem fechar sua frente. Na cama, a cabeceira amadeirada contrasta com a parede cinza e reúne mesas laterais estreitas. O banheiro retoma a bancada escura pontilhada, agora com cuba branca, prateleiras inferiores abertas e espelho de contorno irregular iluminado.',
      result_text = 'As visualizações apresentam uma composição em que a repetição do amadeirado aproxima os usos, mas os volumes verticais e os fundos cinza ajudam a distingui-los. A iluminação sob prateleiras e ao redor do espelho destaca superfícies de apoio e contornos específicos. As gavetas e a prateleira do micro-ondas integram diferentes apoios ao conjunto de madeira. Para a locação, a intenção é concentrar preparo e armazenamento em uma cozinha acolhedora e visualmente organizada.',
      scope = ARRAY['Cozinha com bancada escura pontilhada, cuba e cooktop', 'Marcenaria amadeirada com portas, gavetas e prateleira para micro-ondas', 'Linhas de iluminação sob as prateleiras da cozinha', 'Tampo branco com duas cadeiras sob painel com televisão', 'Cabeceira amadeirada com apoios laterais estreitos', 'Cortinas longas junto à janela e à cama', 'Banheiro com espelho irregular iluminado e prateleiras abertas sob a bancada']::text[],
      seo_title = 'ID Alto da Vila Romana | Marcenaria e usos integrados',
