  UPDATE public.projects
  SET summary = 'No Collection Moema, a proposta organiza cozinha, apoio de trabalho e descanso a partir de uma sequência de armários junto à parede. Volumes amadeirados enquadram a bancada azul-escura e a televisão, enquanto frentes claras e grafite distinguem a cozinha. A cama ocupa a faixa próxima à abertura para a varanda.',
      intro = 'O desenho do estúdio em Moema concentra cozinha e armários em uma lateral, deixando uma passagem contínua desde a entrada até a abertura da varanda. Em frente à cama, uma bancada com duas cadeiras oferece apoio para trabalho e refeições, com a televisão instalada acima. Dois volumes altos amadeirados delimitam esse trecho e o diferenciam da cozinha, sem fechar o ambiente. O piso de aparência amadeirada aproxima visualmente as áreas, enquanto o azul da manta e da bancada se contrapõe às superfícies claras e aos detalhes em ocre junto à cabeceira. A área do projeto é de 27,46 m². O custo de reforma registrado para este projeto é de R$ 2.876,91/m², conforme a base de contratos da Bewild.',
      challenge = 'A questão espacial da proposta é acomodar preparo de alimentos, armazenamento, trabalho e descanso em um ambiente estreito, sem transformar a passagem em área de mobiliário. Também é necessário distinguir a bancada da cozinha e o apoio diante da cama, embora ambos ocupem a mesma lateral do estúdio.',
      solution = 'A marcenaria intercala volumes fechados e um trecho aberto para a bancada com duas cadeiras. Esse enquadramento identifica o apoio de trabalho e refeições, enquanto a prateleira acima da televisão reúne objetos sem ocupar o tampo. Na cozinha, armários inferiores escuros contrastam com a bancada clara de aparência pontilhada e os aéreos cinza-claro. Junto à cama, o espelho vertical de contorno arredondado introduz uma linha curva entre os planos retos, e as cortinas claras acompanham a abertura para a varanda.',
      result_text = 'As visualizações apresentam usos próximos, mas reconhecíveis pelo desenho dos móveis: preparo junto à entrada, apoio compartilhado em frente à cama e descanso perto da varanda. A repetição do amadeirado conecta esses trechos, enquanto azul, grafite e cinza marcam diferenças entre eles.',
      scope = ARRAY['Cozinha linear com frentes grafite e aéreos cinza-claro', 'Bancada azul-escura com duas cadeiras para trabalho e refeições', 'Televisão e prateleira entre volumes altos amadeirados', 'Armários altos distribuídos na mesma lateral da cozinha', 'Cama próxima à abertura da varanda, com cabeceira amadeirada', 'Espelho vertical de contorno arredondado junto à cama', 'Cortinas claras e trilho de iluminação com spots']::text[],
