  UPDATE public.projects
  SET summary = 'O Zip Brooklin combina branco e madeira para criar uma atmosfera tranquila nos seus 25,12 m². A cozinha, o apoio sob a televisão e a área de dormir compartilham essa linguagem. Para receber hóspedes, o projeto valoriza uma chegada simples: equipamentos, armazenamento e superfícies de apoio aparecem em posições reconhecíveis.',
      intro = 'As frentes brancas dos armários superiores reduzem o contraste com paredes e teto. Na parte inferior e nos nichos, a aparência amadeirada acrescenta calor e diferencia os volumes de apoio. Essa alternância dá leveza ao conjunto sem abrir mão de uma presença acolhedora. Os pequenos puxadores pretos e o trilho de spots pontuam a composição, ligando móveis e iluminação por detalhes escuros.

Próxima à cama, a cabeceira cinza acrescenta outra superfície discreta, enquanto o espelho de contorno arredondado suaviza o encontro entre os planos. A cortina clara acompanha a linguagem dos armários superiores. O investimento de reforma informado para este projeto corresponde a R$ 2.843,63/m².',
      challenge = 'Para acomodar hóspedes, a área de guardar roupas precisa conviver com cozinha, cama e apoio para computador. O desafio perceptível é reunir esses usos nas paredes, evitando que cada atividade demande um móvel independente no centro. Também importa manter uma relação visual consistente entre armazenamento alto e superfícies de uso diário.',
      solution = 'A cozinha linear insere o micro-ondas em um nicho e distribui armários acima e abaixo da bancada. Sob a televisão, o tampo oferece apoio para refeições ou trabalho. O armário alto concentra o armazenamento junto aos demais móveis. No banheiro, o gabinete amadeirado e a bancada de aparência cinza prolongam a paleta do studio, mantendo o mesmo equilíbrio entre textura e neutralidade.',
      result_text = 'A organização oferece ao imóvel de locação uma apresentação clara do que cabe na estadia. Madeira e branco constroem uma imagem acolhedora, enquanto os apoios respondem a necessidades concretas do hóspede. Para a divulgação em plataformas como o Airbnb, esse conjunto associa atratividade visual e função como parte da intenção de investimento.',
      scope = ARRAY['Cozinha linear de bancada cinza com cuba e cooktop', 'Nicho amadeirado para micro-ondas entre portas superiores brancas', 'Armário alto alinhado à frente da cozinha', 'Mesa sob a televisão com prateleira superior', 'Cabeceira cinza e espelho vertical de cantos arredondados', 'Cortina clara na abertura de fundo do studio', 'Banheiro com gabinete amadeirado e espelho oval de borda preta']::text[],
